window.CHAPTER_DATA = window.CHAPTER_DATA || {};
window.CHAPTER_DATA[1] = "<section class=\"chapter-section\" id=\"c11h-ch1\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#c2410c;\">1</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#c2410c;\">CBSE Class 11 हिंदी कोर &bull; आरोह भाग - 1 (गद्य खंड) &bull; पाठ 1</div>\n      <h2>नमक का दारोगा (प्रेमचंद)</h2>\n      <p>NCERT तर्कसंगत (Rationalised) 2026–27 पाठ्यक्रम &bull; संपूर्ण 6 प्रामाणिक प्रश्नोत्तर एवं मार्किंग स्कीम</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #fff7ed, #ffedd5); border:1px solid #fed7aa; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#9a3412; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#ea580c\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"m16 12-4-4-4 4M12 16V8\"/></svg>\n      कहानी का केंद्रीय द्वंद्व: ‘धर्म’ और ‘धन’ का संघर्ष\n    </h3>\n    <svg viewBox=\"0 0 800 160\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"25\" y=\"25\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#c2410c\" stroke-width=\"2\"/>\n      <text x=\"137\" y=\"55\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#9a3412\">धर्म (सत्य व कर्तव्य)</text>\n      <text x=\"137\" y=\"78\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">मुंशी वंशीधर</text>\n      <text x=\"137\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• 40,000 की रिश्वत ठुकराई</text>\n      <text x=\"137\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• नौकरी खोई पर उसूल नहीं</text>\n\n      <path d=\"M 250 80 L 335 80\" stroke=\"#94a3b8\" stroke-width=\"2\" stroke-dasharray=\"4,4\"/>\n      <circle cx=\"295\" cy=\"80\" r=\"14\" fill=\"#ffedd5\" stroke=\"#ea580c\" stroke-width=\"2\"/>\n      <text x=\"295\" y=\"84\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"bold\" fill=\"#ea580c\">VS</text>\n\n      <rect x=\"335\" y=\"25\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#b45309\" stroke-width=\"2\"/>\n      <text x=\"447\" y=\"55\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#78350f\">धन (अहंकार व प्रभुत्व)</text>\n      <text x=\"447\" y=\"78\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">पंडित अलोपीदीन</text>\n      <text x=\"447\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• \"लक्ष्मी के आगे सब झुकते हैं\"</text>\n      <text x=\"447\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• भ्रष्ट कानून व वकीलों की फौज</text>\n\n      <path d=\"M 560 80 L 595 80\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"595\" y=\"25\" width=\"180\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#16a34a\" stroke-width=\"2\"/>\n      <text x=\"685\" y=\"55\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#15803d\">सत्य की विजय</text>\n      <text x=\"685\" y=\"78\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">आदर्शोन्मुख यथार्थवाद</text>\n      <text x=\"685\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• स्थायी मैनेजर पद</text>\n      <text x=\"685\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• धर्म की सर्वोच्च प्रतिष्ठा</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT पाठ्यपुस्तक अभ्यास: पाठ के साथ एवं भाषा की बात</div>\n\n  <!-- c11h-ch1-q1 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch1-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch1-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        कहानी का कौन-सा पात्र आपको सर्वाधिक प्रभावित करता है और क्यों?\n      </div>\n      <div class=\"q-marks\">[4 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>कहानी का मुख्य पात्र <strong>मुंशी वंशीधर</strong> हमें सर्वाधिक प्रभावित करता है। इसके प्रमुख कारण निम्नलिखित हैं:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>कर्तव्यनिष्ठा एवं सत्यनिष्ठा:</strong> वंशीधर विपरीत परिस्थितियों में भी सत्य और कर्तव्य के मार्ग से विचलित नहीं होते। जब चारों ओर भ्रष्टाचार और रिश्वतखोरी का बोलबाला था, तब भी उन्होंने अपने पद की मर्यादा का मान रखा।</li>\n        <li><strong>प्रलोभन पर विजय:</strong> यमुना के तट पर पंडित अलोपीदीन द्वारा दी जा रही एक हज़ार से चालीस हज़ार रुपये तक की भारी रिश्वत को उन्होंने एक झटके में ठुकरा दिया, जो उस युग में एक साधारण वेतनभोगी दारोगा के लिए अकल्पनीय था।</li>\n        <li><strong>पारिवारिक दबाव के बावजूद अडिगता:</strong> वृद्ध पिता द्वारा 'पीर की मज़ार' और 'ऊपरी आमदनी' का पाठ पढ़ाए जाने के बावजूद उन्होंने अपने नैतिक मूल्यों से कभी समझौता नहीं किया।</li>\n        <li><strong>स्वाभिमान:</strong> अदालत द्वारा झूठे आरोपों में फँसाकर नौकरी से बर्खास्त किए जाने के बाद भी वे न तो झुके और न ही अपनी ईमानदारी पर पछताए। उनकी इसी सच्चाई ने अंततः अलोपीदीन को भी उनके चरणों में झुकने पर विवश कर दिया।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">मुंशी वंशीधर का चयन एवं कर्तव्यपरायणता का उल्लेख</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">चालीस हज़ार की रिश्वत ठुकराने का उदाहरण</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पिता के भ्रष्ट उपदेशों व सामाजिक दबाव पर अडिगता</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">चरित्र की स्वाभाविकता एवं प्रेरणादायी अंत का विश्लेषण</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch1-q2 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch1-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch1-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        ‘नमक का दारोगा’ कहानी में पंडित अलोपीदीन के व्यक्तित्व के कौन-से दो पहलू (पक्ष) उभरकर आते हैं?\n      </div>\n      <div class=\"q-marks\">[4 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>पंडित अलोपीदीन के व्यक्तित्व के दो विरोधी एवं महत्वपूर्ण पहलू कहानी में उभरते हैं:</p>\n      <ol style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>पहला पहलू (भ्रष्ट, धनलोलुप एवं शोषक महाजन):</strong>\n          <br>कहानी के पूर्वार्द्ध में अलोपीदीन धन के घमंड में चूर एक भ्रष्ट पूँजीपति के रूप में सामने आते हैं। वे कानून और शासन को अपनी जेब में समझते हैं। उनका अटूट विश्वास था कि <em>“संसार में ही नहीं, स्वर्ग में भी लक्ष्मी का ही राज्य है।”</em> वे नमक का काला बाज़ार करते हैं और अदालत के वकीलों व अहलकारों को धन के बल पर खरीदकर न्याय का उपहास उड़ाते हैं।\n        </li>\n        <li><strong>दूसरा पहलू (सच्चाई के कद्रदान एवं विवेकशील पारखी):</strong>\n          <br>कहानी के उत्तरार्द्ध में उनका दूसरा, उज्ज्वल पक्ष सामने आता है। वंशीधर द्वारा उन्हें हिरासत में लिए जाने के बावजूद वे मन ही मन वंशीधर की अदम्य ईमानदारी के कायल हो जाते हैं। वे वंशीधर के घर जाकर अपनी समस्त संपत्ति का आजीवन स्थायी मैनेजर पद (छह हज़ार वार्षिक वेतन, बँगला, नौकर-चाकर) सौंपकर उनकी सत्यनिष्ठा का वंदन करते हैं। यह उनके भीतर छिपे गुणग्राही और न्यायप्रिय रूप को उजागर करता है।</li>\n      </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">प्रथम पक्ष: धन के मद में चूर भ्रष्ट एवं शोषक व्यापारी</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">द्वितीय पक्ष: ईमानदारी का सम्मान करने वाला गुणग्राही एवं उदार व्यक्ति</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch1-q3 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch1-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch1-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        कहानी के लगभग सभी पात्र समाज की किसी-न-किसी सच्चाई को उजागर करते हैं। निम्नलिखित पात्रों के संदर्भ में पाठ से उस अंश को उद्धृत करते हुए बताइए कि यह समाज की किस सच्चाई को उजागर करते हैं: (क) वृद्ध मुंशी, (ख) वंशीधर की पत्नी, (ग) अलोपीदीन के वकील।\n      </div>\n      <div class=\"q-marks\">[4 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>पात्रों द्वारा उजागर की जाने वाली सामाजिक सच्चाइयाँ:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>(क) वृद्ध मुंशी (वंशीधर के पिता):</strong>\n          <br><strong>उद्धरण:</strong> <em>“ओहदे की ओर ध्यान मत देना, यह तो पीर का मज़ार है। निगाह चढ़ावे और चादर पर रखनी चाहिए... मासिक वेतन तो पूर्णमासी का चाँद है जो घटते-घटते लुप्त हो जाता है, ऊपरी आय बहता हुआ स्रोत है जिससे सदैव प्यास बुझती है।”</em>\n          <br><strong>सामाजिक यथार्थ:</strong> यह समाज के उस नैतिक पतन को दर्शाता है जहाँ अभिभावक स्वयं अपनी संतानों को सांसारिक विवशता और दरिद्रता के नाम पर रिश्वतखोरी और भ्रष्टाचार की सीख देते हैं।\n        </li>\n        <li><strong>(ख) वंशीधर की पत्नी:</strong>\n          <br><strong>उद्धरण:</strong> <em>“पत्नी ने तो कई दिनों तक सीधे मुँह बात तक नहीं की।”</em>\n          <br><strong>सामाजिक यथार्थ:</strong> यह भौतिकवादी मानसिकता को दर्शाता है जहाँ आर्थिक तंगी में परिवार के सदस्य भी आदर्शों और ईमानदारी की क़द्र नहीं करते, बल्कि केवल सांसारिक सुख-सुविधाओं को प्राथमिकता देते हैं।\n        </li>\n        <li><strong>(ग) अलोपीदीन के वकील:</strong>\n          <br><strong>उद्धरण:</strong> <em>“वकीलों ने यह फैसला सुना और उछल पड़े... न्याय के मैदान में धर्म और धन में युद्ध ठन गया था।”</em>\n          <br><strong>सामाजिक यथार्थ:</strong> यह न्यायपालिका और वकालत के पेशे में बिक चुके व्यावसायिक अवसरवाद को उजागर करता है, जहाँ वकीलों का उद्देश्य सत्य की रक्षा करना नहीं, बल्कि भ्रष्ट धनपतियों के पैसे से अपनी जेबें भरना होता है।\n        </li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">वृद्ध मुंशी: रिश्वतखोरी को जायज़ ठहराने वाली अभिभावकीय सोच</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वंशीधर की पत्नी: आदर्शों की उपेक्षा कर भौतिकता को तवज्जो</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वकील: बिकाऊ न्याय प्रणाली और पेशेवर अवसरवाद</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch1-q4 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch1-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch1-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        ‘धर्म ने धन को पैरों तले कुचल डाला’—कहानी में इस कथन का क्या आशय है? स्पष्ट कीजिए।\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>इस कथन का आशय है—<strong>सत्य, कर्तव्य और चारित्रिक ईमानदारी के समक्ष धन, प्रलोभन और रिश्वत का पूरी तरह परास्त हो जाना।</strong></p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>घटनाक्रम:</strong> यमुना के पुल पर जब वंशीधर ने नमक की अवैध गाड़ियाँ पकड़ीं, तो पंडित अलोपीदीन ने अपनी अकूत दौलत के बल पर दारोगा को खरीदने की पूरी चेष्टा की। उन्होंने रिश्वत की राशि एक हज़ार से बढ़ाकर क्रमशः पाँच, दस, बीस और अंत में चालीस हज़ार रुपये तक पहुँचा दी।</li>\n        <li><strong>धर्म की विजय:</strong> चालीस हज़ार रुपये की विशाल धनराशि के सामने भी वंशीधर का धर्म (कर्तव्यनिष्ठा) रत्ती भर नहीं डिगा। उन्होंने ललकार कर जमादार बदलू सिंह को अलोपीदीन को तुरंत हिरासत में लेने का हुक्म दिया। इस प्रकार एक निर्धन कर्मचारी के चारित्रिक बल ने एक अति-धनाढ्य व्यापारी के अहंकार और धन को धूल चटा दी।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">कथन का मूल भाव: सत्य व कर्तव्य के सम्मुख भौतिक धन की पराजय</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">चालीस हज़ार की रिश्वत की पेशकश और वंशीधर का दृढ़ प्रत्युत्तर</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अलोपीदीन की गिरफ्तारी द्वारा चारित्रिक विजय का निरूपण</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch1-q5 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch1-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch1-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        ‘नमक का दारोगा’ कहानी का अंत प्रेमचंद के ‘आदर्शोन्मुख यथार्थवाद’ को किस प्रकार प्रमाणित करता है?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>प्रेमचंद की कहानियों की मुख्य विशेषता <strong>आदर्शोन्मुख यथार्थवाद (Idealistic Realism)</strong> है, जिसमें यथार्थ की कटु सच्चाइयों का चित्रण करते हुए अंत में मानवीय आदर्शों की विजय दिखाई जाती है:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>यथार्थवादी पक्ष:</strong> कहानी में समाज की नग्न सच्चाई दिखाई गई है—अदालतें भ्रष्ट हैं, अहलकार बिकाऊ हैं, और ईमानदार कर्मचारी को नौकरी गँवानी पड़ती है तथा अपने ही घर में माता-पिता और पत्नी के ताने सहने पड़ते हैं। यह समाज का यथार्थ (सत्य) है।</li>\n        <li><strong>आदर्शवादी पक्ष:</strong> यदि कहानी वंशीधर की बर्खास्ती पर ही समाप्त हो जाती, तो यह निराशावादी यथार्थ होता। परंतु प्रेमचंद ने अलोपीदीन के अंतर्मन को जगाया। अलोपीदीन स्वयं वंशीधर के द्वार पहुँचे और उन्हें अपनी संपूर्ण रियासत का आजीवन स्थायी मैनेजर नियुक्त कर दिया।</li>\n        <li><strong>निष्कर्ष:</strong> इस प्रकार यह प्रमाणित होता है कि सांसारिक कष्ट सहने के बावजूद अंततः धर्म और ईमानदारी की ही विजय होती है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">आदर्शोन्मुख यथार्थवाद की परिभाषा एवं यथार्थ पक्ष का निरूपण</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वंशीधर की बर्खास्ती और सामाजिक कटुता का यथार्थवादी अंकन</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अलोपीदीन के हृदय परिवर्तन द्वारा नैतिक आदर्श की स्थापना</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch1-q6 (भाषा की बात) -->\n  <div class=\"q-card\" id=\"c11h-ch1-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch1-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">भाषा की बात</span><br>\n        पाठ में आए निम्नलिखित मुहावरों के अर्थ स्पष्ट करते हुए अपने वाक्यों में प्रयोग कीजिए: (क) फूला न समाना, (ख) आसमान के तारे तोड़ना, (ग) हाथ मलना, (घ) मुँह में कालिख लगना।\n      </div>\n      <div class=\"q-marks\">[4 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>मुहावरों के अर्थ एवं सटीक वाक्य प्रयोग:</p>\n      <ol style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>(क) फूला न समाना:</strong>\n          <br><strong>अर्थ:</strong> अत्यधिक प्रसन्न होना / खुशी से गद्गद हो जाना।\n          <br><strong>वाक्य प्रयोग:</strong> जब वंशीधर को नमक विभाग में दारोगा की नौकरी मिली, तो उनके वृद्ध पिता <em>फूले न समाए</em>।\n        </li>\n        <li><strong>(ख) आसमान के तारे तोड़ना:</strong>\n          <br><strong>अर्थ:</strong> असंभव अथवा अत्यंत कठिन कार्य कर दिखाना।\n          <br><strong>वाक्य प्रयोग:</strong> आज के युग में बिना किसी सिफारिश और रिश्वत के सरकारी नौकरी पाना <em>आसमान के तारे तोड़ने</em> जैसा है।\n        </li>\n        <li><strong>(ग) हाथ मलना:</strong>\n          <br><strong>अर्थ:</strong> पछताना / अवसर बीत जाने पर अफ़सोस करना।\n          <br><strong>वाक्य प्रयोग:</strong> समय पर परिश्रम न करने वाले छात्र परीक्षा परिणाम आने पर केवल <em>हाथ मलते</em> रह जाते हैं।\n        </li>\n        <li><strong>(घ) मुँह में कालिख लगना:</strong>\n          <br><strong>अर्थ:</strong> कलंकित होना / कुल अथवा परिवार की बदनामी होना।\n          <br><strong>वाक्य प्रयोग:</strong> चोरी के आरोप में पकड़े जाने पर मुंशी जी ने अपने बेटे से कहा कि तूने पूरे खानदान के <em>मुँह में कालिख लगा</em> दी।\n        </li>\n      </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">फूला न समाना: अर्थ एवं वाक्य प्रयोग</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आसमान के तारे तोड़ना: अर्थ एवं वाक्य प्रयोग</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हाथ मलना: अर्थ एवं वाक्य प्रयोग</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मुँह में कालिख लगना: अर्थ एवं वाक्य प्रयोग</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <a href=\"../ncert-solutions-class-11-hindi.html\" class=\"ch-nav-btn prev\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; text-decoration:none; color:#334155;\">← Class 11 Hindi Hub</a>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(2)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#c2410c; color:white; font-weight:700; cursor:pointer;\">अगला पाठ: मियाँ नसीरुद्दीन →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[2] = "<section class=\"chapter-section\" id=\"c11h-ch2\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#c2410c;\">2</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#c2410c;\">CBSE Class 11 हिंदी कोर &bull; आरोह भाग - 1 (गद्य खंड) &bull; पाठ 2</div>\n      <h2>मियाँ नसीरुद्दीन (कृष्णा सोबती)</h2>\n      <p>NCERT तर्कसंगत (Rationalised) 2026–27 पाठ्यक्रम &bull; संपूर्ण 5 प्रामाणिक प्रश्नोत्तर एवं मार्किंग स्कीम</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #fffbeb, #fef3c7); border:1px solid #fde68a; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#92400e; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#d97706\" stroke-width=\"2\"><path d=\"M12 2v20\"/><path d=\"M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6\"/></svg>\n      मियाँ नसीरुद्दीन का व्यक्तित्व: 56 किस्म की रोटियों का फन\n    </h3>\n    <svg viewBox=\"0 0 800 150\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"25\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d97706\" stroke-width=\"2\"/>\n      <text x=\"137\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#92400e\">खानदानी फन</text>\n      <text x=\"137\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">नानबाइयों के मसीहा</text>\n      <text x=\"137\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• 56 प्रकार की रोटियाँ बनाना</text>\n      <text x=\"137\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• \"काम करने से आता है, नसीहतों से नहीं\"</text>\n\n      <path d=\"M 250 75 L 285 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"285\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#c2410c\" stroke-width=\"2\"/>\n      <text x=\"397\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#9a3412\">शाही शेखी व स्वाभिमान</text>\n      <text x=\"397\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">कहावतें व दावे</text>\n      <text x=\"397\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• \"ऐसी रोटी जो न पानी से पके न आग से\"</text>\n      <text x=\"397\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• बादशाह सलामत के बावर्चियों के वंशज</text>\n\n      <path d=\"M 510 75 L 545 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"545\" y=\"20\" width=\"230\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <text x=\"660\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#065f46\">गुमनाम अतीत का दर्द</text>\n      <text x=\"660\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">बदलता ज़माना</text>\n      <text x=\"660\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• अब कद्रदान नहीं रहे</text>\n      <text x=\"660\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• तंदूरी मोटी रोटी खाकर भागने वाले लोग</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT पाठ्यपुस्तक अभ्यास: पाठ के साथ एवं भाषा की बात</div>\n\n  <!-- c11h-ch2-q1 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch2-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch2-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        मियाँ नसीरुद्दीन को ‘नानबाइयों का मसीहा’ क्यों कहा गया है?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>मियाँ नसीरुद्दीन को ‘नानबाइयों का मसीहा’ इसलिए कहा गया है क्योंकि:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>रोटी बनाने की कला में अद्वितीय महारत:</strong> वे साधारण रोटी पकाने वाले कारीगर नहीं, बल्कि छप्पन (56) किस्म की भिन्न-भिन्न रोटियाँ बनाने का दुर्लभ हुनर जानते थे।</li>\n        <li><strong>रोटी निर्माण को कला (फन) का दर्जा देना:</strong> वे रोटी पकाने को मात्र पेट भरने का धंधा नहीं, बल्कि साधना और कला मानते थे। उनका मानना था कि इस हुनर को सीखने के लिए बरसों भट्ठी सुलगाने, खोमचा लगाने और बर्तन मांजने का लंबा अभ्यास करना पड़ता है।</li>\n        <li><strong>खानदानी गौरव और आत्मविश्वास:</strong> उनके बातचीत करने का अंदाज़ मसीहाई था। वे अपने पुरखों की कारीगरी पर गर्व करते हुए एक मसीहा की तरह अधिकारपूर्वक अपनी बात रखते थे।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">56 प्रकार की रोटियाँ बनाने का अद्वितीय फन</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">रोटी निर्माण को कला एवं साधना मानने का दृष्टिकोण</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">खानदानी गौरव और मसीहाई अंदाज़ का उल्लेख</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch2-q2 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch2-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch2-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        लेखिका मियाँ नसीरुद्दीन के पास क्यों गई थी?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>लेखिका कृष्णा सोबती मियाँ नसीरुद्दीन के पास कोई रोटी खरीदने अथवा खाने के उद्देश्य से नहीं गई थीं। उनके जाने का उद्देश्य निम्नलिखित था:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>पत्रकारिता एवं शोधपरक जिज्ञासा:</strong> लेखिका को गड़हैया मुहल्ले में चलते-चलते एक साधारण दुकान पर ढेर सारा आटा सनते देखकर उत्सुकता हुई। पूछताछ करने पर पता चला कि यह खानदानी नानबाई मियाँ नसीरुद्दीन की मशहूर दुकान है।</li>\n        <li><strong>कारीगरी का शब्दचित्र खींचना:</strong> लेखिका एक पत्रकार की हैसियत से मियाँ नसीरुद्दीन के 56 किस्म की रोटियाँ बनाने के फन, उनकी खानदानी परंपरा, कारीगरी के रहस्यों और उनके अनोखे व्यक्तित्व का साक्षात्कार लेकर एक रोचक शब्दचित्र (रेखाचित्र) तैयार करना चाहती थीं।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">रोटी खरीदने नहीं, पत्रकार के रूप में साक्षात्कार लेने जाना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">56 किस्म की रोटियों के फन और खानदानी कारीगरी को लिपिबद्ध करने की मंशा</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch2-q3 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch2-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch2-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        बादशाह के नाम का प्रसंग आते ही मियाँ नसीरुद्दीन की दिलचस्पी लेखिका की बातों में क्यों कम होने लगी?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>बादशाह के नाम का प्रसंग आते ही मियाँ नसीरुद्दीन उखड़ने लगे और उनकी दिलचस्पी समाप्त होने लगी, इसके कारण निम्नलिखित थे:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>झूठ पकड़े जाने का भय:</strong> मियाँ नसीरुद्दीन ने शेखी बघारते हुए दावा किया था कि उनके बुजुर्ग बादशाह सलामत के बावर्चीखाने में ऐसी नई चीज़ पकाते थे जो <em>“न आग से पके न पानी से।”</em></li>\n        <li><strong>ऐतिहासिक अज्ञानता:</strong> जब लेखिका ने उस विशिष्ट बादशाह का नाम पूछा (बहादुर शाह ज़फ़र अथवा कोई अन्य), तो मियाँ किसी भी बादशाह का नाम नहीं बता सके। वे केवल सुनी-सुनाई बातों और काल्पनिक दावों के आधार पर शेखी मार रहे थे।</li>\n        <li><strong>झेंप मिटाने की कोशिश:</strong> लगातार कुरेदने पर वे झेंप गए और अपनी पोल खुलती देखकर लेखिका की बातों से पल्ला झाड़ने लगे तथा कारीगर बब्बन मियाँ को भट्ठी सुलगाने के काम में व्यस्त दिखाने लगे।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">शाही बावर्चीखाने की शेखी और काल्पनिक दावों की पोल खुलना</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बादशाह का वास्तविक नाम न मालूम होने की झेंप</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">लेखिका के तीखे सवालों से बचने के लिए बातचीत से किनारा करना</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch2-q4 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch2-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch2-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        ‘मियाँ नसीरुद्दीन के चेहरे पर किसी दबे हुए अंधड़ के आसार देख यह मजमून न छेड़ने का फैसला किया’—इस कथन के पहले और बाद के प्रसंग का उल्लेख कीजिए।\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>इस मार्मिक प्रसंग का विवरण:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>पहले का प्रसंग:</strong> लेखिका मियाँ नसीरुद्दीन से उनके परिवार, बेटे-बेटियों और शागिर्दों के बारे में पूछना चाहती थीं। उन्होंने पूछा कि क्या ये काम करने वाले कारीगर आपके शागिर्द हैं? मियाँ ने तल्ख़ स्वर में कहा— <em>“खाली शागिर्दी ही नहीं, काम के दो रुपये मन आटे की और चार रुपये मन मैदे की मज़दूरी देता हूँ।”</em></li>\n        <li><strong>चेहरे पर अंधड़ के आसार:</strong> जब लेखिका उनके बेटों के बारे में पूछने ही वाली थीं, तो उन्होंने देखा कि मियाँ के चेहरे पर गहरे आक्रोश, पीड़ा और अतीत के किसी दबे हुए तूफ़ान के भाव उभर आए हैं। उनका चेहरा तमतमा गया था।</li>\n        <li><strong>बाद का प्रसंग:</strong> स्थिति की गंभीरता को भांपकर लेखिका ने पारिवारिक विषय को टाल दिया और बातचीत का रुख बदल दिया। उन्होंने केवल रोटियों की किस्मों (बाकरखानी, शीरमाल, ताफ़तान, खमीरी, रुमाली, गावेदीदा, गाज़ेबान, तुनकी आदि) के बारे में पूछना ही उचित समझा।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">पहले का प्रसंग: शागिर्दों और मजदूरी से संबंधित तल्ख़ बातचीत</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">चेहरे के भाव: आक्रोश और दबे हुए पारिवारिक दर्द का उभार</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बाद का प्रसंग: विषय बदलकर केवल रोटियों की किस्मों तक सीमित रहना</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch2-q5 (भाषा की बात) -->\n  <div class=\"q-card\" id=\"c11h-ch2-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch2-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">भाषा की बात</span><br>\n        पाठ में मियाँ नसीरुद्दीन द्वारा बनाई जाने वाली विभिन्न प्रकार की रोटियों के नाम आए हैं। उनमें से किन्हीं पाँच रोटियों के नाम लिखिए तथा उनकी विशेषता बताइए।\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>मियाँ नसीरुद्दीन की भट्ठी पर पकने वाली प्रसिद्ध रोटियाँ:</p>\n      <ol style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>बाकरखानी:</strong> यह मैदे, घी और दूध से गूँथकर बनाई जाने वाली परतदार, खस्ता और मीठी रोटी होती है, जो विशेष अवधी व्यंजनों के साथ खाई जाती है।</li>\n        <li><strong>शीरमाल:</strong> यह केसर, दूध और घी के मिश्रण से पकाई जाने वाली अत्यंत सुगंधित, कोमल और नारंगी रंगत वाली शाही रोटी है।</li>\n        <li><strong>ताफ़तान:</strong> यह मुगलई पद्धति से बनाई जाने वाली अत्यधिक मुलायम, फुल्की और स्वादिष्ट रोटी है।</li>\n        <li><strong>खमीरी:</strong> खमीर (Yeast) उठाकर तैयार की जाने वाली मोटी, स्पंजी और सुपाच्य रोटी।</li>\n        <li><strong>तुनकी:</strong> यह कागज़ की तरह अत्यंत पतली और महीन रोटी होती है। मियाँ के अनुसार <em>“तुनकी पापड़ से भी महीन होती है।”</em></li>\n      </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">पाँच पारंपरिक रोटियों के शुद्ध नाम</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रत्येक रोटी की निर्माण सामग्री एवं विशेषताओं का संक्षिप्त विवरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(1)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← पाठ 1</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(3)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#c2410c; color:white; font-weight:700; cursor:pointer;\">अगला पाठ: अपू के साथ ढाई साल →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[3] = "<section class=\"chapter-section\" id=\"c11h-ch3\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#c2410c;\">3</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#c2410c;\">CBSE Class 11 हिंदी कोर &bull; आरोह भाग - 1 (गद्य खंड) &bull; पाठ 3</div>\n      <h2>अपू के साथ ढाई साल (सत्यजित राय)</h2>\n      <p>NCERT तर्कसंगत (Rationalised) 2026–27 पाठ्यक्रम &bull; संपूर्ण 5 प्रामाणिक प्रश्नोत्तर एवं मार्किंग स्कीम</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #f0fdf4, #dcfce7); border:1px solid #bbf7d0; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#14532d; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"2\"><rect x=\"2\" y=\"2\" width=\"20\" height=\"20\" rx=\"2.18\" ry=\"2.18\"/><line x1=\"7\" y1=\"2\" x2=\"7\" y2=\"22\"/><line x1=\"17\" y1=\"2\" x2=\"17\" y2=\"22\"/><line x1=\"2\" y1=\"12\" x2=\"22\" y2=\"12\"/></svg>\n      पथेर पांचाली निर्माण की चुनौतियाँ (1952–1955)\n    </h3>\n    <svg viewBox=\"0 0 800 150\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"25\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#16a34a\" stroke-width=\"2\"/>\n      <text x=\"137\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#14532d\">आर्थिक संकट</text>\n      <text x=\"137\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">पैसे का नितांत अभाव</text>\n      <text x=\"137\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• विज्ञापन कंपनी में नौकरी</text>\n      <text x=\"137\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• पैसे खत्म होते ही शूटिंग बंद</text>\n\n      <path d=\"M 250 75 L 285 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"285\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n      <text x=\"397\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#0369a1\">पात्र एवं पशु संकट</text>\n      <text x=\"397\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">कंटिन्यूटी (निरंतरता)</text>\n      <text x=\"397\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• 'भूलो' कुत्ते की आकस्मिक मृत्यु</text>\n      <text x=\"397\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• मिठाईवाले श्रीनिवास का निधन</text>\n\n      <path d=\"M 510 75 L 545 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"545\" y=\"20\" width=\"230\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#ca8a04\" stroke-width=\"2\"/>\n      <text x=\"660\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#713f12\">प्राकृतिक विवशता</text>\n      <text x=\"660\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">मौसम पर निर्भरता</text>\n      <text x=\"660\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• काशफूलों को मवेशियों ने खाया</text>\n      <text x=\"660\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• शरद ऋतु में प्राकृतिक बारिश का इंतज़ार</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT पाठ्यपुस्तक अभ्यास: पाठ के साथ</div>\n\n  <!-- c11h-ch3-q1 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch3-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch3-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        ‘पथेर पांचाली’ फ़िल्म की शूटिंग का काम ढाई साल तक क्यों चला?\n      </div>\n      <div class=\"q-marks\">[4 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>सत्यजित राय की विश्वप्रसिद्ध कालजयी फ़िल्म ‘पथेर पांचाली’ के निर्माण में ढाई साल का लंबा समय लगने के मुख्य कारण निम्नलिखित थे:</p>\n      <ol style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>आर्थिक संकट (धन का अभाव):</strong> सत्यजित राय उस समय एक विज्ञापन एजेंसी में काम करते थे। उनके पास शूटिंग के लिए पर्याप्त पूँजी नहीं थी। वे अपनी तनख्वाह से थोड़े-थोड़े पैसे जमा करते, फिर शूटिंग करते। जब पैसे समाप्त हो जाते, तो शूटिंग हफ़्तों-महीनों के लिए रोकनी पड़ती थी।</li>\n        <li><strong>समय का अभाव:</strong> निर्देशक और अधिकांश तकनीशियन अन्य पूर्णकालिक नौकरियों में कार्यरत थे, इसलिए केवल रविवार या छुट्टियों के दिन ही शूटिंग संभव हो पाती थी।</li>\n        <li><strong>पात्रों और कलाकारों की निरंतरता (Continuity) बनाए रखने की समस्या:</strong> लंबे अंतराल के कारण काशफूलों का नष्ट होना, अभिनेताओं और पशुओं (जैसे भूलो कुत्ता और मिठाईवाला श्रीनिवास) की मृत्यु आदि प्राकृतिक बाधाएँ आईं, जिन्हें सुलझाने में लंबा समय व्यतीत हुआ।</li>\n      </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">पूँजी का घोर अभाव और किश्तों में शूटिंग</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नौकरीपेशा होने के कारण केवल छुट्टियों में काम</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पात्रों, मौसम और दृश्य निरंतरता की गंभीर बाधाएँ</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch3-q2 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch3-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch3-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        काशफूलों के मैदान में रेलगाड़ी के दृश्य की शूटिंग में क्या-क्या कठिनाइयाँ आईं?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>पालशिट गाँव के पास काशफूलों से भरे मैदान में अपू और दुर्गा द्वारा पहली बार रेलगाड़ी देखने के दृश्य की शूटिंग में भीषण कठिनाइयाँ आईं:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>अधूरा दृश्य और काशफूलों का विनाश:</strong> पहले दिन पैसे और समय के अभाव में केवल आधा दृश्य ही शूट हो सका। सात दिन बाद जब पूरी टीम शेष दृश्य शूट करने पहुँची, तो देखा कि पूरा मैदान खाली हो चुका था—सारे काशफूलों को गाँव के जानवर खाकर चट कर चुके थे। निर्देशक को पूरा एक साल अगले मौसम में काशफूल खिलने की प्रतीक्षा करनी पड़ी।</li>\n        <li><strong>रेलगाड़ियों का तालमेल:</strong> अपू और दुर्गा के पीछे से धुआँ उड़ाती हुई गुजरती रेलगाड़ी का शॉट लेने के लिए एक ही दिन में तीन अलग-अलग रेलगाड़ियों का सहारा लेना पड़ा। बॉयलर में कोयला झोंकने वाले ड्राइवर को पहले से समझाना पड़ता था कि कैमरे के पास आते ही खूब काला धुआँ उड़ाए।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">जानवरों द्वारा काशफूल खा जाना एवं एक वर्ष की प्रतीक्षा</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तीन रेलगाड़ियों का समन्वय एवं ड्राइवर से काला धुआँ निकलवाने का जतन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch3-q3 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch3-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch3-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        ‘भूलो’ की जगह दूसरा कुत्ता क्यों लाया गया? उसने फ़िल्म के किस दृश्य को पूरा किया?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p><strong>दूसरा कुत्ता लाने का कारण:</strong></p>\n      <p>पथेर पांचाली की शूटिंग पैसों के अभाव में छह महीने के लिए बंद रही। जब छह महीने बाद बोडाल गाँव में दोबारा शूटिंग शुरू हुई, तो पता चला कि मूल ‘भूलो’ कुत्ते की वृद्धावस्था के कारण मृत्यु हो चुकी थी। दृश्य की निरंतरता (कंटिन्यूटी) बचाने के लिए राय साहब को गाँव-गाँव भटककर भूलो जैसा दिखने वाला एक दूसरा कुत्ता ढूँढना पड़ा।</p>\n      <p><strong>पूरा किया गया दृश्य:</strong></p>\n      <p>उसने अपू की माँ (सर्वजया) द्वारा थाली में परोसे गए भात को गमले में फेंकने का दृश्य पूरा किया। अपू तीर-कमान से खेल रहा था और माँ उसे खिला रही थी। जब अपू भाग जाता है, तो सर्वजया बचा हुआ भात एक गमले में फेंक देती है, जिसे भूलो कुत्ता बड़े चाव से खाता है। इस दृश्य का पूर्वार्द्ध पहले कुत्ते के साथ और उत्तरार्द्ध दूसरे कुत्ते के साथ शूट हुआ, और दर्शक आज तक यह अंतर नहीं पहचान पाते।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">मूल भूलो कुत्ते की मृत्यु एवं मिलते-जुलते कुत्ते की खोज</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गमले से भात खाने वाले भोजन दृश्य का प्रामाणिक विवरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch3-q4 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch3-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch3-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        फ़िल्म में मिठाईवाले ‘श्रीनिवास’ से जुड़े दृश्य की शूटिंग के दौरान क्या समस्या आई और उसका समाधान कैसे निकाला गया?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p><strong>आई हुई समस्या:</strong></p>\n      <p>मिठाई बेचने वाले का किरदार निभाने वाले वृद्ध सज्जन श्रीनिवास का आधा दृश्य शूट होने के बाद निधन हो गया। दृश्य अधूरा था—अपू और दुर्गा मिठाईवाले के पीछे-पीछे दौड़ते हुए मुखर्जी बाबू के घर तक जाते हैं।</p>\n      <p><strong>निकाला गया समाधान:</strong></p>\n      <p>सत्यजित राय ने एक दूसरा व्यक्ति खोजा जिसका चेहरा तो श्रीनिवास से नहीं मिलता था, परंतु उसका शरीर और कद-काठी श्रीनिवास जैसी ही थी। निर्देशक ने कैमरे का एंगल इस प्रकार रखा कि नए व्यक्ति को केवल <strong>पीठ के पीछे से (Behind the back)</strong> दिखाया गया। दर्शक केवल उसकी पीठ और काँधे पर बँधी मिठाई की टोकरी देखते हैं, जिससे स्क्रीन पर यह भ्रम बना रहा कि वही मूल श्रीनिवास चल रहा है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">श्रीनिवास की आकस्मिक मृत्यु से दृश्य का आधा अधूरा रह जाना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">समान कद-काठी वाले नए व्यक्ति को पीछे (पीठ) से शूट करने का तकनीकी समाधान</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch3-q5 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch3-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch3-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        बारिश के दृश्य को शूट करने में क्या कठिनाई आई और उसका फिल्मांकन कैसे संभव हुआ?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>बारिश के दृश्य में आई कठिनाई एवं फिल्मांकन:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>बरसात के दिनों में पैसे न होना:</strong> जब घनघोर वर्षा का मौसम (सावन-भादों) था, तब निर्देशक के पास पैसे नहीं थे। जब अक्टूबर में पैसे की व्यवस्था हुई, तब वर्षा ऋतु समाप्त हो चुकी थी और आकाश पूरी तरह साफ़ व धूपदार था।</li>\n        <li><strong>प्रतीक्षा और अचानक वर्षा:</strong> शरद ऋतु में कृत्रिम फव्वारों के साधन नहीं थे। निर्देशक पूरी टीम और बाल कलाकारों (अपू और दुर्गा) को लेकर रोज़ खुले मैदान में बादलों की टकटकी लगाए बैठे रहते थे।</li>\n        <li><strong>भीषण ठंड में भीगना:</strong> अक्टूबर के अंत में एक दिन अचानक दोपहर में आकाश में काले बादल छाए और मूसलाधार बारिश हुई। दुर्गा और अपू ने भीषण ठंड में काँपते हुए वह कालजयी दृश्य शूट किया, जिसमें दुर्गा अपू को सीने से चिपकाकर गाती है। शॉट पूरा होने के बाद दोनों बच्चों को दूध में ब्रांडी मिलाकर पिलाई गई ताकि उन्हें निमोनिया न हो।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">मानसून में धन का अभाव और शरद ऋतु में मौसम का साफ होना</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">रोज़ मैदान में जाकर बादलों का इंतज़ार करना</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अक्टूबर की अचानक बारिश में काँपते बच्चों का जीवंत फिल्मांकन</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(2)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← पाठ 2</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(4)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#c2410c; color:white; font-weight:700; cursor:pointer;\">अगला पाठ: विदाई-संभाषण →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[4] = "<section class=\"chapter-section\" id=\"c11h-ch4\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#c2410c;\">4</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#c2410c;\">CBSE Class 11 हिंदी कोर &bull; आरोह भाग - 1 (गद्य खंड) &bull; पाठ 4</div>\n      <h2>विदाई-संभाषण (बालमुकुंद गुप्त)</h2>\n      <p>NCERT तर्कसंगत (Rationalised) 2026–27 पाठ्यक्रम &bull; संपूर्ण 5 प्रामाणिक प्रश्नोत्तर एवं मार्किंग स्कीम</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #fef2f2, #fee2e2); border:1px solid #fecaca; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#991b1b; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#dc2626\" stroke-width=\"2\"><path d=\"M18 6 6 18M6 6l12 12\"/></svg>\n      लॉर्ड कर्ज़न का निरंकुश शासन एवं पतन\n    </h3>\n    <svg viewBox=\"0 0 800 150\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"25\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#dc2626\" stroke-width=\"2\"/>\n      <text x=\"137\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#991b1b\">तानाशाही चरमोत्कर्ष</text>\n      <text x=\"137\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">दमनकारी नीतियाँ</text>\n      <text x=\"137\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• 8 करोड़ जनता की इच्छा के विरुद्ध बंग-भंग</text>\n      <text x=\"137\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• प्रेस व विश्वविद्यालयों की स्वायत्तता छीनी</text>\n\n      <path d=\"M 250 75 L 285 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"285\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d97706\" stroke-width=\"2\"/>\n      <text x=\"397\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#b45309\">अहंकार का टकराव</text>\n      <text x=\"397\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">काउंसिल में पराजय</text>\n      <text x=\"397\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• फौजी अफ़सर की नियुक्ति पर हठ</text>\n      <text x=\"397\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• धमकी भरा इस्तीफ़ा स्वीकार हो गया</text>\n\n      <path d=\"M 510 75 L 545 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"545\" y=\"20\" width=\"230\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#475569\" stroke-width=\"2\"/>\n      <text x=\"660\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1e293b\">अपमानजनक विदाई</text>\n      <text x=\"660\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">शिवशंभु का व्यंग्य</text>\n      <text x=\"660\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• बिछड़न का समय अत्यंत पवित्र होता है</text>\n      <text x=\"660\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• जालिम गाय के जाने पर भी प्रजा दुखी</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT पाठ्यपुस्तक अभ्यास: पाठ के साथ</div>\n\n  <!-- c11h-ch4-q1 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch4-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch4-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        शिवशंभु की दो गायों की कहानी के माध्यम से लेखक क्या कहना चाहता है?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>शिवशंभु की दो गायों के दृष्टांत के माध्यम से लेखक भारत की संवेदनशील और क्षमाशील सांस्कृतिक परंपरा को उजागर करता है:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>कथा का प्रसंग:</strong> शिवशंभु के पास दो गायें थीं—एक सीधी-सादी और दूसरी अत्यधिक बलशाली व सींग मारने वाली। जब मारने वाली गाय को किसी पुरोहित को दान दे दिया गया, तो लेखक ने देखा कि दुर्बल, सीधी गाय ने उस दिन दाना-घास कुछ नहीं खाया और उसकी आँखों से आँसू बहते रहे।</li>\n        <li><strong>प्रतीकात्मक संदेश:</strong> लेखक लॉर्ड कर्ज़न पर तीखा कटाक्ष करते हुए कहता है कि इस देश में जहाँ क्रूर और कष्ट पहुँचाने वाले पशु के बिछुड़ने पर भी मूक पशु दुःखी होते हैं, उस देश की सहृदय जनता अपने अत्याचारी शासक कर्ज़न की विदाई पर भी करुणा और उदासी का अनुभव कर रही है। बिछड़न का समय वैर-भाव भुलाकर पवित्र और करुणामय हो जाता है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">शिवशंभु की दो गायों का दृष्टांत और दुर्बल गाय का विलाप</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कर्ज़न पर तीखा व्यंग्य एवं भारतीय संस्कृति में बिछड़न की करुणा</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch4-q2 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch4-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch4-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        ‘आठ करोड़ प्रजा के गिड़गिड़ाकर विच्छेद न करने की प्रार्थना पर आपने ज़रा भी ध्यान नहीं दिया’—यहाँ किस ऐतिहासिक घटना की ओर संकेत किया गया है?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>यहाँ वर्ष 1905 के कुख्यात <strong>‘बंग-भंग’ (बंगाल का विभाजन)</strong> की ऐतिहासिक घटना की ओर संकेत किया गया है:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>ऐतिहासिक पृष्ठभूमि:</strong> तत्कालीन वायसराय लॉर्ड कर्ज़न ने 'फूट डालो और राज करो' (Divide and Rule) की साम्राज्यवादी नीति के तहत हिंदू और मुस्लिम एकता को तोड़ने के लिए बंगाल प्रेसीडेंसी को दो टुकड़ों में विभाजित कर दिया।</li>\n        <li><strong>जनता की गुहार की अनसुनी:</strong> बंगाल की आठ करोड़ जनता ने एक स्वर में बंगाल विभाजन का विरोध किया, सड़कों पर उतरकर प्रार्थनाएँ कीं, गिड़गिड़ाए और याचिकाएँ दीं। परंतु निरंकुश और अहंकारी कर्ज़न ने जनता की आर्त पुकार को पैरों तले कुचलते हुए अपनी हठधर्मिता से विभाजन लागू कर दिया।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">1905 के बंगाल विभाजन (बंग-भंग) का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आठ करोड़ जनता की गुहार को रौंदकर विभाजन थोपने की निरंकुशता</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch4-q3 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch4-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch4-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        लॉर्ड कर्ज़न को अपने पद से इस्तीफ़ा क्यों देना पड़ गया?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>लॉर्ड कर्ज़न के पतन और इस्तीफ़े के कारण:</p>\n      <ol style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>काउंसिल में मनमानी की हठ:</strong> कर्ज़न अपनी सैन्य परिषद (Military Council) में अपनी पसंद के एक फौजी अफ़सर को सदस्य नियुक्त करवाना चाहते थे।</li>\n        <li><strong>ब्रिटिश सरकार द्वारा उपेक्षा:</strong> ब्रिटेन की गृह सरकार और भारत मंत्री ने कर्ज़न की सिफ़ारिश को सिरे से ठुकरा दिया और उनकी बात नहीं मानी।</li>\n        <li><strong>धमकी का उल्टा पड़ना:</strong> अपने असीम घमंड में आकर कर्ज़न ने ब्रिटिश हुकूमत पर दबाव बनाने के लिए इस्तीफ़े की धमकी दी। उन्हें गुमान था कि उनके बिना भारत का काम नहीं चल सकता, परंतु ब्रिटिश सरकार ने बिना किसी झिझक के उनका इस्तीफ़ा तुरंत मंज़ूर कर लिया। इस प्रकार जिस कर्ज़न के इशारे पर राजे-महाराजे नाचते थे, उनका अपने ही देश की सत्ता के आगे घमंड चूर-चूर हो गया।</li>\n      </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">पसंदीदा फौजी अफ़सर को काउंसिल में रखने की ज़िद</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">ब्रिटिश गृह सरकार द्वारा उनकी बात का ठुकराया जाना</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">धमकी भरा इस्तीफ़ा स्वीकार होकर अपमानजनक विदाई का शिकार होना</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch4-q4 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch4-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch4-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        ‘विचारिए तो, क्या शान आपकी इस देश में थी और अब क्या हो गई!’—कर्ज़न की शान का वर्णन कीजिए।\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>भारत में लॉर्ड कर्ज़न की भव्य शान-शौकत और उसके बाद हुए पतन का तुलनात्मक विवरण:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>भूतपूर्व अद्वितीय शान:</strong>\n          <br>दिल्ली दरबार में कर्ज़न का हाथी सबसे आगे और सबसे ऊँचा होता था। उनका सोने का सिंहासन (तख्त) इंग्लैंड के राजकुमार (एडवर्ड) के सिंहासन से भी अधिक ऊँचा और भव्य था। बड़े-बड़े भारतीय राजे-महाराजे उनके हाथ बाँधकर सामने खड़े रहते थे। उनके एक इशारे पर राजा गद्दी से उतार दिए जाते थे और नए नवाब बिठा दिए जाते थे।\n        </li>\n        <li><strong>पतन और दुर्दशा:</strong>\n          <br>उसी देश में अंत में स्थिति यह हो गई कि कर्ज़न अपने एक चहेते अफ़सर को काउंसिल में नियुक्त तक नहीं करवा सके। उनका पद और प्रतिष्ठा धूल में मिल गई और उन्हें भारी अपमान व बेइज्जती के साथ यह देश छोड़कर जाना पड़ा।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">दिल्ली दरबार में सोने का सिंहासन और सबसे ऊँचा हाथी</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">राजे-महाराजाओं पर रौब एवं अंत में एक क्लर्क नियुक्त न कर पाने की लाचारी</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch4-q5 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch4-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch4-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        ‘आपके और यहाँ के निवासियों के बीच कोई तीसरी शक्ति और भी है’—यहाँ ‘तीसरी शक्ति’ किसे कहा गया है और उसकी क्या विशेषता है?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>यहाँ <strong>‘तीसरी शक्ति’</strong> सर्वशक्तिमान <strong>ईश्वर (विधाता / कालचक्र)</strong> को कहा गया है:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>ईश्वर की सर्वोच्चता:</strong> लेखक कर्ज़न को समझाता है कि आप स्वयं को भारत का भाग्यविधाता समझ बैठे थे और भारत की निरीह प्रजा आपको सर्वशक्तिमान मानती थी। परंतु आपके और इस प्रजा के ऊपर एक तीसरी शक्ति—ईश्वर—विद्यमान है।</li>\n        <li><strong>तीसरी शक्ति की विशेषताएँ:</strong>\n          <br>1. यह शक्ति असीम, सर्वव्यापी और न्यायप्रिय है।\n          <br>2. इसके इशारे पर बड़े-बड़े तानाशाहों और साम्राज्यवादी शासकों का घमंड एक पल में चकनाचूर हो जाता है।\n          <br>3. इस शक्ति के सामने कर्ज़न की सारी कूटनीति, घमंड और सत्ता ताश के पत्तों की तरह ढह गई।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">तीसरी शक्ति की पहचान ईश्वर (विधाता/परम सत्ता) के रूप में</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">विशेषताएँ: सर्वव्यापी न्याय, तानाशाहों के घमंड को चूर करने वाली परम शक्ति</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(3)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← पाठ 3</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(5)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#c2410c; color:white; font-weight:700; cursor:pointer;\">अगला पाठ: गलता लोहा →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[5] = "<section class=\"chapter-section\" id=\"c11h-ch5\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#c2410c;\">5</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#c2410c;\">CBSE Class 11 हिंदी कोर &bull; आरोह भाग - 1 (गद्य खंड) &bull; पाठ 5</div>\n      <h2>गलता लोहा (शेखर जोशी)</h2>\n      <p>NCERT तर्कसंगत (Rationalised) 2026–27 पाठ्यक्रम &bull; संपूर्ण 5 प्रामाणिक प्रश्नोत्तर एवं मार्किंग स्कीम</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #f8fafc, #e2e8f0); border:1px solid #cbd5e1; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#1e293b; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#475569\" stroke-width=\"2\"><path d=\"M12 2v20\"/><path d=\"m4.93 4.93 14.14 14.14\"/><path d=\"m19.07 4.93-14.14 14.14\"/></svg>\n      जातिगत अभिमान का विगलन: ‘गलता लोहा’\n    </h3>\n    <svg viewBox=\"0 0 800 150\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"25\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n      <text x=\"137\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#0369a1\">मोहन (ब्राह्मण पुत्र)</text>\n      <text x=\"137\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">मेधावी छात्र</text>\n      <text x=\"137\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• मास्टर त्रिलोक का दुलारा</text>\n      <text x=\"137\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• लखनऊ में घरेलू नौकर बन गया</text>\n\n      <path d=\"M 250 75 L 285 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"285\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#ea580c\" stroke-width=\"2\"/>\n      <text x=\"397\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#c2410c\">धनराम (लोहार पुत्र)</text>\n      <text x=\"397\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">जातिगत हीनभावना</text>\n      <text x=\"397\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• \"तेरी अक्ल में लोहा भरा है\"</text>\n      <text x=\"397\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• पैतृक धंधा: भट्ठी व हथौड़ा</text>\n\n      <path d=\"M 510 75 L 545 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"545\" y=\"20\" width=\"230\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#16a34a\" stroke-width=\"2\"/>\n      <text x=\"660\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#15803d\">जातीय बेड़ियों का टूटना</text>\n      <text x=\"660\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">कलात्मक सृजन</text>\n      <text x=\"660\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• मोहन ने हथौड़ा संभाल छल्ला बनाया</text>\n      <text x=\"660\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• आँखों में सर्जक की चमक</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT पाठ्यपुस्तक अभ्यास: पाठ के साथ</div>\n\n  <!-- c11h-ch5-q1 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch5-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch5-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        कहानी के उस प्रसंग का उल्लेख करें, जिसमें किताबों की विद्या और लोहे की विद्या (गनही) का ज़िक्र आया है?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>पाठ में जब धनराम बचपन में मास्टर त्रिलोक सिंह के स्कूल में पढ़ता था, तब यह प्रसंग आता है:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>किताबों की विद्या में विफलता:</strong> धनराम मंदबुद्धि था। उसे तेरह का पहाड़ा कभी याद नहीं होता था। मास्टर जी डंडे से उसकी पिटाई करते और ताना मारते थे। दिन भर स्कूल में वह किताबों की विद्या सीखने का विफल प्रयास करता।</li>\n        <li><strong>लोहे की विद्या की शुरुआत:</strong> स्कूल की छुट्टी होते ही धनराम अपने पिता गंगाराम के आफ़र (लोहार की दुकान) पर पहुँच जाता। वहाँ उसके पिता उसे धौंकनी फूँकने, सँणसी पकड़ने, हथौड़ा चलाने और भट्ठी सुलगाने की <em>“लोहे की विद्या”</em> सिखाने लगते थे।</li>\n        <li><strong>पिता का व्यावहारिक रुख:</strong> गंगाराम का मानना था कि किताबों की विद्या ब्राह्मणों और उच्च वर्ग के लिए है, लोहार के बेटे के लिए हाथ का हुनर (लोहे की विद्या) ही उसकी असली आजीविका बनेगा।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">मास्टर त्रिलोक सिंह की कक्षा में तेरह का पहाड़ा न रट पाने का प्रसंग</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आफ़र पर पिता गंगाराम द्वारा धौंकनी और हथौड़े की तालीम देने का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch5-q2 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch5-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch5-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        धनराम मोहन को अपना प्रतिद्वंद्वी क्यों नहीं समझता था?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>धनराम के मन में मोहन के प्रति कभी ईर्ष्या या प्रतिद्वंद्विता की भावना नहीं पनपी, इसके प्रमुख कारण निम्नलिखित थे:</p>\n      <ol style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>जातिगत हीनभावना:</strong> धनराम निम्न जाति (लोहार / शिल्पकार) से संबंध रखता था, जबकि मोहन उच्च कुल का ब्राह्मण था। समाज की सामंती व्यवस्था ने धनराम के मन में बचपन से ही यह बैठा दिया था कि ब्राह्मण श्रेष्ठ होते हैं।</li>\n        <li><strong>मास्टर त्रिलोक सिंह की भविष्यवाणी:</strong> मास्टर जी पूरी कक्षा में बार-बार कहते थे कि <em>“मोहन एक दिन बड़ा आदमी बनकर स्कूल और मेरा नाम रोशन करेगा।”</em> धनराम ने इसे अकाट्य सत्य मान लिया था।</li>\n        <li><strong>सज़ा देने का अधिकार:</strong> जब मास्टर जी मोहन से कमजोर छात्रों (धनराम सहित) के कान खिंचवाते और छड़ी से पिटवाते थे, तब भी धनराम इसे मोहन का स्वाभाविक अधिकार मानता था। वह मोहन की कुशाग्र बुद्धि का आदर करता था।</li>\n      </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">जातिगत संस्कार और ब्राह्मणों के प्रति आदरभाव</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मास्टर त्रिलोक सिंह की प्रशंसा एवं मोहन की असाधारण मेधा</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मोहन द्वारा दी जाने वाली सज़ा को सहर्ष स्वीकार करना</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch5-q3 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch5-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch5-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        धनराम को मोहन के किस व्यवहार पर आश्चर्य होता है और क्यों?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p><strong>आश्चर्यजनक व्यवहार:</strong></p>\n      <p>जब मोहन धनराम के आफ़र पर गया, तो उसने देखा कि धनराम लोहे की एक मोटी छड़ को गोलाई में मोड़कर छल्ला बनाने में विफल हो रहा था। अचानक उच्चकुलीन ब्राह्मण पुत्र मोहन ने बिना किसी झिझक के अपनी पैंट मरोड़ी, सँणसी से लाल-तप्त लोहे को पकड़ा और नपे-तुले हाथों से हथौड़े की सटीक चोटें मारते हुए लोहे की छड़ को एक संपूर्ण सुडौल गोल वृत्त (छल्ले) में ढाल दिया।</p>\n      <p><strong>आश्चर्य का कारण:</strong></p>\n      <p>पहाड़ी समाज में जातिगत छुआछूत और मर्यादा के कड़े नियम थे। किसी पुरोहित (ब्राह्मण) परिवार के युवक का लोहार के आफ़र पर घंटों बैठना ही निषिद्ध था, उसका लोहार के औज़ार (हथौड़ा-सँणसी) छूना और नीच माने जाने वाले शिल्पकार का काम स्वयं करना धनराम की कल्पना से परे था।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">मोहन द्वारा सँणसी और हथौड़ा लेकर लोहे को सुडौल वृत्त में ढालना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">ब्राह्मण होकर लोहार का काम करने पर जातिगत मर्यादा टूटने का विस्मय</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch5-q4 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch5-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch5-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        मोहन के लखनऊ आने के बाद के समय को लेखक ने उसके जीवन का एक नया अध्याय क्यों कहा है?\n      </div>\n      <div class=\"q-marks\">[4 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>लखनऊ आने के बाद मोहन के जीवन की दिशा पूरी तरह बदल गई, जिसके कारण लेखक ने इसे 'नया अध्याय' कहा:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>गाँव में मेधावी विद्यार्थी की छवि:</strong> गाँव में मोहन एक कुशाग्र बुद्धि, होनहार और उच्च शिक्षा का सपना देखने वाला मेधावी छात्र था, जिसे छात्रवृत्ति मिली थी।</li>\n        <li><strong>लखनऊ में घरेलू नौकर की स्थिति:</strong> गाँव के रिश्तेदार रमेश ने लखनऊ ले जाकर अच्छी शिक्षा दिलाने का झाँसा दिया था, परंतु लखनऊ पहुँचते ही मोहन को घर का नौकर बना दिया गया। वह दिन भर रमेश के घर का चूल्हा-चौका, बर्तन-झाड़ू और मुहल्ले भर की औरतों के लिए बाज़ार से सौदे-सुलफ़ लाने के काम में पिस गया।</li>\n        <li><strong>प्रतिभा का दमन:</strong> उसे किसी प्रतिष्ठित स्कूल में दाखिला न दिलाकर एक साधारण तकनीकी स्कूल में भेजा गया। इस प्रकार उसके डॉक्टर या अफ़सर बनने के सुनहरे सपने चूर-चूर हो गए और उसकी मेधा चूल्हे की राख बन गई।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">गाँव के मेधावी छात्र का लखनऊ में घरेलू नौकर बन जाना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दैनिक घरेलू कामकाज और बाज़ार के सामान ढोने में पिसना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शिक्षा और प्रतिभा का पूर्ण दमन होकर सपनों का टूटना</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch5-q5 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch5-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch5-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        ‘गलता लोहा’ शीर्षक की सार्थकता स्पष्ट कीजिए।\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>शेखर जोशी द्वारा रचित कहानी ‘गलता लोहा’ का शीर्षक अत्यंत प्रतीकात्मक, व्यंग्यात्मक और सार्थक है:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>स्थूल (भौतिक) अर्थ:</strong> भट्ठी में जलते हुए अंगारों के बीच लोहार लोहे को गर्म करता है, जिससे कठोर लोहा गलकर लचीला हो जाता है और उसे मनचाहा आकार दिया जा सकता है। कहानी में मोहन गर्म लोहे को सँणसी से पकड़कर सुडौल छल्ला बनाता है।</li>\n        <li><strong>सूक्ष्म (प्रतीकात्मक) अर्थ:</strong> ‘लोहा’ समाज की कठोर, जड़ और सदियों पुरानी <strong>जातिवादी वर्ण-व्यवस्था</strong> का प्रतीक है। ब्राह्मण श्रेष्ठता का झूठा घमंड एक कड़े लोहे के समान था। जब मोहन उस जातिवादी अहंकार को तिलांजलि देकर आफ़र पर हथौड़ा उठाता है, तो मानो जाति का वह कठोर लोहा हमेशा के लिए गल जाता है।</li>\n        <li><strong>सर्जक की चमक:</strong> मोहन के चेहरे पर कोई हीनभावना या संकोच नहीं था, बल्कि एक सच्चे सर्जक और कलाकार की चमक थी। अतः ‘गलता लोहा’ शीर्षक सर्वथा उपयुक्त और सटीक है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">स्थूल अर्थ: भट्ठी में लोहे का पिघलना और लचीला होना</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सूक्ष्म अर्थ: जातिगत अहंकार और संकीर्ण मर्यादाओं का विगलन</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मोहन की आँखों में एक सर्जक के आत्मविश्वास की प्रतिष्ठा</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(4)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← पाठ 4</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(6)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#c2410c; color:white; font-weight:700; cursor:pointer;\">अगला पाठ: रजनी →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[6] = "<section class=\"chapter-section\" id=\"c11h-ch6\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#c2410c;\">6</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#c2410c;\">CBSE Class 11 हिंदी कोर &bull; आरोह भाग - 1 (गद्य खंड) &bull; पाठ 6</div>\n      <h2>रजनी (मन्नू भंडारी)</h2>\n      <p>NCERT तर्कसंगत (Rationalised) 2026–27 पाठ्यक्रम &bull; संपूर्ण 5 प्रामाणिक प्रश्नोत्तर एवं मार्किंग स्कीम</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #fdf4ff, #fae8ff); border:1px solid #f0abfc; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#86198f; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#c026d3\" stroke-width=\"2\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg>\n      शिक्षा के व्यवसायीकरण के विरुद्ध जन-आंदोलन\n    </h3>\n    <svg viewBox=\"0 0 800 150\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"25\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#c026d3\" stroke-width=\"2\"/>\n      <text x=\"137\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#86198f\">ट्यूशन रैकेट</text>\n      <text x=\"137\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">अमित का उत्पीड़न</text>\n      <text x=\"137\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• गणित के मेधावी छात्र के कम अंक</text>\n      <text x=\"137\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• ट्यूशन न लेने पर द्वेषपूर्ण व्यवहार</text>\n\n      <path d=\"M 250 75 L 285 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"285\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#a21caf\" stroke-width=\"2\"/>\n      <text x=\"397\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#701a75\">अधिकारियों की उदासीनता</text>\n      <text x=\"397\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">जिम्मेदारी से पल्ला झाड़ना</text>\n      <text x=\"397\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• हेडमास्टर: \"यह टीचर-पेरेंट का मामला\"</text>\n      <text x=\"397\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• डायरेक्टर: \"कोई शिकायत नहीं आई\"</text>\n\n      <path d=\"M 510 75 L 545 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"545\" y=\"20\" width=\"230\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#16a34a\" stroke-width=\"2\"/>\n      <text x=\"660\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#15803d\">रजनी का संघर्ष</text>\n      <text x=\"660\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">अभिभावक सभा</text>\n      <text x=\"660\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• मीडिया व प्रेस का सहयोग</text>\n      <text x=\"660\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• बोर्ड का ऐतिहासिक नियम पारित</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT पाठ्यपुस्तक अभ्यास: पाठ के साथ</div>\n\n  <!-- c11h-ch6-q1 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch6-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch6-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        रजनी ने ट्यूशन के विरुद्ध आंदोलन क्यों छेड़ा?\n      </div>\n      <div class=\"q-marks\">[4 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>रजनी ने ट्यूशन के विरुद्ध एक सशक्त जन-आंदोलन खड़ा किया, इसके प्रमुख कारण निम्नलिखित थे:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>अमित के साथ हुआ घोर अन्याय:</strong> उसकी पड़ोसन लीला का बेटा अमित गणित में बहुत होशियार था और उसने सारे सवाल सही किए थे। परंतु गणित के अध्यापक पाठक सर के बार-बार दबाव डालने पर भी उसने ट्यूशन नहीं ली थी, जिसके बदले में अध्यापक ने दुर्भावनापूर्वक उसके अंक काटकर उसे मात्र बाइस (22) नंबर दिए।</li>\n        <li><strong>शिक्षा का व्यावसायिक दोहन:</strong> रजनी ने महसूस किया कि शिक्षक बच्चों को कक्षा में ठीक से नहीं पढ़ाते ताकि बच्चे ट्यूशन पढ़ने के लिए मजबूर हों। यह कोई व्यक्तिगत समस्या नहीं, बल्कि एक संगठित शिक्षा माफिया का रूप ले चुका था।</li>\n        <li><strong>व्यवस्था की संवेदनहीनता:</strong> जब हेडमास्टर और शिक्षा निदेशक ने इस गंभीर समस्या पर कार्रवाई करने से मना कर दिया, तो रजनी ने इसे एक सामाजिक बुराई मानकर इसके विरुद्ध मोर्चा खोल दिया।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">अमित के साथ गणित के पेपर में दुर्भावनापूर्ण अंक कटौती</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शिक्षकों द्वारा जबरन ट्यूशन थोपकर शिक्षा का व्यवसायीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हेडमास्टर व शिक्षा विभाग की संवेदनहीनता के विरुद्ध संघर्ष</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch6-q2 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch6-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch6-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        हेडमास्टर के पास जब रजनी शिकायत लेकर गई, तो उनका क्या रुख था?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>हेडमास्टर का रुख अत्यंत गैर-ज़िम्मेदाराना, उदासीन और टालमटोल वाला था:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>मामले से पल्ला झाड़ना:</strong> हेडमास्टर ने रजनी की शिकायत को गंभीरता से लेने के बजाय हँसकर टाल दिया और कहा— <em>“यह तो टीचर्स और स्टूडेंट्स का आपस का मामला है। इसमें स्कूल क्या कर सकता है?”</em></li>\n        <li><strong>ट्यूशन का अप्रत्यक्ष समर्थन:</strong> उन्होंने कहा कि टीचर कमज़ोर बच्चों को पढ़ाते हैं और पेरेंट्स अपनी मर्ज़ी से ट्यूशन लगवाते हैं, स्कूल का इसमें कोई हस्तक्षेप नहीं हो सकता।</li>\n        <li><strong>रजनी का प्रतिवाद:</strong> रजनी ने उन्हें फटकार लगाते हुए कहा कि जब नियम है कि स्कूल के शिक्षक अपने ही स्कूल के बच्चों को प्राइवेट ट्यूशन नहीं पढ़ा सकते, तो प्रिंसिपल इस खुली लूट पर आँखें मूँदकर क्यों बैठे हैं?</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">हेडमास्टर द्वारा मामले को निजी बताकर पल्ला झाड़ना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">रजनी द्वारा नियम की याद दिलाकर फटकार लगाना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch6-q3 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch6-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch6-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        शिक्षा निदेशक (डायरेक्टर ऑफ एजुकेशन) के दफ़्तर में रजनी ने किस प्रकार अपनी बात रखी?\n      </div>\n      <div class=\"q-marks\">[4 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>शिक्षा निदेशक के दफ़्तर में रजनी ने निडरता, तर्कों और प्रशासनिक दृढ़ता के साथ अपनी बात रखी:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>चपरासी की बाधा पार करना:</strong> जब चपरासी ने घूस या पर्ची न होने पर मिलने से रोका, तो रजनी सीधे दरवाज़ा धकेलकर निदेशक के कमरे में घुस गईं।</li>\n        <li><strong>निदेशक के बहाने को काटना:</strong> निदेशक ने कहा कि हमारे पास जब तक पेरेंट्स की कोई लिखित शिकायत नहीं आती, हम कुछ नहीं कर सकते। रजनी ने तपाक से उत्तर दिया कि पेरेंट्स डरते हैं कि उनके बच्चों को फेल कर दिया जाएगा, इसलिए सरकार और शिक्षा बोर्ड की यह ज़िम्मेदारी बनती है कि वह स्वयं जांच करे।</li>\n        <li><strong>अल्टीमेटम:</strong> रजनी ने स्पष्ट चेतावनी दी कि यदि विभाग ने निजी ट्यूशन पर पाबंदी लगाने का सख्त नियम नहीं बनाया, तो वे जनता की अदालत में जाएँगी और प्रेस व अभिभावकों को एकजुट करेंगी।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">निदेशक के कक्ष में बेधड़क प्रवेश और निडरता का प्रदर्शन</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">लिखित शिकायत न होने के बहाने को तार्किक रूप से काटना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">जन-आंदोलन और मीडिया में जाने की स्पष्ट चेतावनी देना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch6-q4 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch6-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch6-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        रजनी का चरित्र आपको किस प्रकार प्रेरित करता है? उसकी चारित्रिक विशेषताओं पर प्रकाश डालिए।\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>रजनी एक आधुनिक, जुझारू, न्यायप्रिय और जागरूक भारतीय नारी का प्रतीक है, जिसका चरित्र हमें निम्नलिखित रूपों में प्रेरित करता है:</p>\n      <ol style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>अन्याय के विरुद्ध शून्य सहनशीलता (Zero Tolerance):</strong> अमित उसका सगा बेटा नहीं था, केवल पड़ोसन का बच्चा था। लोग दूसरों के मामलों में चुप रहते हैं, परंतु रजनी ने अन्याय को व्यक्तिगत चुनौती के रूप में स्वीकार किया।</li>\n        <li><strong>अद्भुत संगठन क्षमता:</strong> उसने अखबार के संपादक से मिलकर प्रेस का समर्थन लिया, अभिभावकों की विशाल सभा बुलाई और सरकार को झुकने पर मजबूर कर दिया।</li>\n        <li><strong>पति की संकीर्ण सोच पर विजय:</strong> जब उसके पति रवि ने कहा कि <em>“तुम क्यों दुनिया का ठेका लेती हो?”</em>, तब भी उसने अपने क़दम पीछे नहीं हटाए। उसका चरित्र सिखाता है कि एक जागरूक नागरिक पूरे समाज की व्यवस्था को बदल सकता है।</li>\n      </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">अन्याय के विरुद्ध निर्भीक संघर्ष और सामाजिक सरोकार</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कुशल नेतृत्व, संगठन क्षमता और मीडिया का सही उपयोग</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पारिवारिक विरोध के बावजूद सामाजिक दायित्व पर अडिगता</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch6-q5 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch6-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch6-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        इस एकांकी में शिक्षा व्यवस्था की किस विकृति को रेखांकित किया गया है और उसका क्या स्थायी समाधान बताया गया है?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p><strong>शिक्षा व्यवस्था की विकृति:</strong></p>\n      <p>पवित्र शिक्षा व्यवस्था का बाज़ारीकरण हो जाना। शिक्षकों द्वारा कक्षा में कर्तव्य न निभाना और छात्रों को ब्लैकमेल करके ज़बरन प्राइवेट ट्यूशन के लिए विवश करना। जो बच्चे ट्यूशन नहीं लेते, उनके अंक काटकर उनका मनोबल तोड़ा जाता है।</p>\n      <p><strong>सुझाया गया स्थायी समाधान:</strong></p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li>शिक्षा बोर्ड ऐसा सख्त नियम बनाए कि कोई भी स्कूल शिक्षक अपने ही विद्यालय के विद्यार्थियों को ट्यूशन नहीं पढ़ा सकेगा।</li>\n        <li>यदि किसी छात्र को वास्तव में किसी विषय में कठिनाई है, तो स्कूल प्रबंधन अतिरिक्त उपचारात्मक कक्षाएं (Remedial Classes) आयोजित करे।</li>\n        <li>अभिभावकों को शिक्षकों के अन्याय के सामने झुकने के बजाय एकजुट होकर आवाज़ उठानी चाहिए।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">शिक्षा के बाज़ारीकरण और ट्यूशन माफिया की विकृति का अंकन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बोर्ड के नियमों, उपचारात्मक कक्षाओं और अभिभावक एकता का समाधान</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(5)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← पाठ 5</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(7)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#c2410c; color:white; font-weight:700; cursor:pointer;\">अगला पाठ: जामुन का पेड़ →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[7] = "<section class=\"chapter-section\" id=\"c11h-ch7\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#c2410c;\">7</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#c2410c;\">CBSE Class 11 हिंदी कोर &bull; आरोह भाग - 1 (गद्य खंड) &bull; पाठ 7</div>\n      <h2>जामुन का पेड़ (कृष्ण चंदर)</h2>\n      <p>NCERT तर्कसंगत (Rationalised) 2026–27 पाठ्यक्रम &bull; संपूर्ण 5 प्रामाणिक प्रश्नोत्तर एवं मार्किंग स्कीम</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #fefce8, #fef08a); border:1px solid #fde047; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#854d0e; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#ca8a04\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"8\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"16\" x2=\"12.01\" y2=\"16\"/></svg>\n      दफ़्तरशाही की संवेदनहीन फ़ाइल यात्रा\n    </h3>\n    <svg viewBox=\"0 0 800 150\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"25\" y=\"20\" width=\"165\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#ca8a04\" stroke-width=\"2\"/>\n      <text x=\"107\" y=\"50\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"bold\" fill=\"#854d0e\">व्यापार विभाग</text>\n      <text x=\"107\" y=\"70\" text-anchor=\"middle\" font-size=\"10\" fill=\"#475569\">जिम्मेदारी टालना</text>\n      <text x=\"107\" y=\"90\" text-anchor=\"middle\" font-size=\"9\" fill=\"#64748b\">\"पेड़ फलदार है,</text>\n      <text x=\"107\" y=\"105\" text-anchor=\"middle\" font-size=\"9\" fill=\"#64748b\">कृषि विभाग देखे\"</text>\n\n      <path d=\"M 190 75 L 220 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"220\" y=\"20\" width=\"165\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n      <text x=\"302\" y=\"50\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"bold\" fill=\"#0369a1\">हॉर्टिकल्चर विभाग</text>\n      <text x=\"302\" y=\"70\" text-anchor=\"middle\" font-size=\"10\" fill=\"#475569\">पेड़ बचाव अभियान</text>\n      <text x=\"302\" y=\"90\" text-anchor=\"middle\" font-size=\"9\" fill=\"#64748b\">\"पेड़ उगाओ का दौर है,</text>\n      <text x=\"302\" y=\"105\" text-anchor=\"middle\" font-size=\"9\" fill=\"#64748b\">काट नहीं सकते\"</text>\n\n      <path d=\"M 385 75 L 415 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"415\" y=\"20\" width=\"175\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#9333ea\" stroke-width=\"2\"/>\n      <text x=\"502\" y=\"50\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"bold\" fill=\"#7e22ce\">कल्चरल विभाग</text>\n      <text x=\"502\" y=\"70\" text-anchor=\"middle\" font-size=\"10\" fill=\"#475569\">शायरी व अकादमी</text>\n      <text x=\"502\" y=\"90\" text-anchor=\"middle\" font-size=\"9\" fill=\"#64748b\">\"दबा आदमी कवि ओस है,</text>\n      <text x=\"502\" y=\"105\" text-anchor=\"middle\" font-size=\"9\" fill=\"#64748b\">अकादमी सदस्य बना लो\"</text>\n\n      <path d=\"M 590 75 L 620 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"620\" y=\"20\" width=\"155\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#dc2626\" stroke-width=\"2\"/>\n      <text x=\"697\" y=\"50\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"bold\" fill=\"#991b1b\">फ़ॉरेन डिपार्टमेंट</text>\n      <text x=\"697\" y=\"70\" text-anchor=\"middle\" font-size=\"10\" fill=\"#475569\">पिटोनिया राज्य संबंध</text>\n      <text x=\"697\" y=\"90\" text-anchor=\"middle\" font-size=\"9\" fill=\"#64748b\">फ़ाइल पूरी हुई,</text>\n      <text x=\"697\" y=\"105\" text-anchor=\"middle\" font-size=\"9\" fill=\"#64748b\">जीवन समाप्त हुआ</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT पाठ्यपुस्तक अभ्यास: पाठ के साथ</div>\n\n  <!-- c11h-ch7-q1 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch7-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch7-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        सेक्रेटेरिएट के लॉन में जामुन का पेड़ गिरने से क्या घटना घटी और उस पर विभिन्न विभागों की क्या प्रतिक्रिया रही?\n      </div>\n      <div class=\"q-marks\">[4 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>रात के भयंकर अंधड़ में सेक्रेटेरिएट के लॉन में एक पुराना जामुन का पेड़ गिर पड़ा, जिसके नीचे एक अभागा आदमी दब गया।</p>\n      <p><strong>विभिन्न विभागों की हास्यास्पद एवं असंवेदनशील प्रतिक्रिया:</strong></p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>क्लर्कों की जामुन-स्मृति:</strong> क्लर्क दबे हुए आदमी को निकालने के बजाय जामुन के पेड़ के रसीले जामुनों की याद में शोक मनाने लगे कि इसके जामुन कितने मीठे होते थे।</li>\n        <li><strong>व्यापार और कृषि विभाग का विवाद:</strong> व्यापार विभाग ने कहा कि पेड़ लॉन में गिरा है अतः यह कृषि विभाग का मामला है। कृषि विभाग ने कहा कि जामुन फलदार पेड़ है इसलिए यह हॉर्टिकल्चर (उद्यान कृषि) विभाग की ज़िम्मेदारी है।</li>\n        <li><strong>हॉर्टिकल्चर विभाग की हठ:</strong> हॉर्टिकल्चर सचिव ने कहा कि इस समय देश में 'पेड़ लगाओ' अभियान चल रहा है, इसलिए हम किसी भी फलदार पेड़ को काटने की इजाज़त कतई नहीं दे सकते। इस प्रकार हर विभाग अपनी ज़िम्मेदारी से पल्ला झाड़ता रहा।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">पेड़ के नीचे आदमी का दबना और क्लर्कों की जामुन-प्रियता</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">व्यापार, कृषि और हॉर्टिकल्चर विभागों का आपसी गतिरोध</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">व्यवस्था की संवेदनहीनता और औपचारिकता का अंकन</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch7-q2 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch7-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch7-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        ‘दबा हुआ आदमी एक कवि है’—यह बात पता चलने पर फ़ाइल किस विभाग में भेज दी गई और वहाँ क्या तमाशा हुआ?\n      </div>\n      <div class=\"q-marks\">[4 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>जब दबे हुए आदमी ने मिर्ज़ा ग़ालिब का मशहूर शेर पढ़ा— <em>“ये तो माना कि तगाफ़ुल न करोगे लेकिन, ख़ाक हो जाएँगे हम तुमको ख़बर होने तक!”</em> तो सबको पता चला कि दबा हुआ आदमी एक शायर/कवि है (उपनाम ‘ओस’)।</p>\n      <p><strong>कल्चरल (सांस्कृतिक) विभाग का तमाशा:</strong></p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li>मामला तुरंत कल्चरल डिपार्टमेंट को भेज दिया गया। कल्चरल विभाग के सेक्रेटरी ने आकर कवि का इंटरव्यू लिया।</li>\n        <li>उसने कहा कि यह घोर लज्जा की बात है कि इतना बड़ा कवि हमारी अकादमी का सदस्य नहीं है। उसने तुरंत दबे हुए आदमी को 'साहित्य अकादमी की केंद्रीय शाखा' का सदस्य चुन लिया और बधाई दी।</li>\n        <li>जब कवि ने चीखकर कहा कि <em>“मुझे इस पेड़ के नीचे से निकालिए, मैं मर रहा हूँ!”</em>, तो सेक्रेटरी ने हाथ जोड़कर कहा— <em>“यह हमारे अधिकार क्षेत्र में नहीं है। हम पेड़ नहीं काट सकते। यदि आप मर जाएँगे तो हम आपकी पत्नी को पेंशन दे सकते हैं।”</em> यह नौकरशाही की असंवेदनशीलता का चरम था।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">ग़ालिब के शेर से कवि होने का रहस्योद्घाटन</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कल्चरल विभाग द्वारा अकादमी का सदस्य बनाना और बधाई देना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पेड़ से निकालने से इनकार कर केवल मरणोपरांत पेंशन का आश्वासन देना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch7-q3 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch7-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch7-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        दबे हुए आदमी को निकालने के लिए मनचले क्लर्कों ने क्या विचित्र सुझाव दिया और मेडिकल विभाग ने उस पर क्या रिपोर्ट दी?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p><strong>मनचले क्लर्कों का विचित्र सुझाव:</strong></p>\n      <p>जब पेड़ काटने की अनुमति किसी विभाग से नहीं मिली, तो एक मनचले क्लर्क ने सुझाव दिया कि क्यों न दबे हुए आदमी को ही बीच से काटकर दो टुकड़ों में बाहर निकाल लिया जाए! आधा आदमी इधर से निकल आएगा और आधा उधर से, और पेड़ भी नहीं काटना पड़ेगा। प्लास्टिक सर्जरी से उसे दोबारा जोड़ दिया जाएगा।</p>\n      <p><strong>मेडिकल विभाग की रिपोर्ट:</strong></p>\n      <p>सर्जन डॉक्टर ने दबे हुए आदमी की नसें, धड़कन, रक्तचाप आदि की सूक्ष्म जाँच की और रिपोर्ट दी कि <em>“ऑपरेशन सफल हो जाएगा, प्लास्टिक सर्जरी से आदमी जुड़ भी जाएगा, मगर आदमी मर जाएगा!”</em> यह हास्य-व्यंग्य आधुनिक चिकित्सा और प्रशासनिक तंत्र की औपचारिकता पर तीखा कटाक्ष करता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">आदमी को बीच से काटकर दो टुकड़ों में निकालने का अमानवीय सुझाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सर्जन की रिपोर्ट: ऑपरेशन सफल रहेगा पर आदमी मर जाएगा</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch7-q4 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch7-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch7-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        फ़ॉरेन (विदेश) डिपार्टमेंट में फ़ाइल क्यों भेजी गई और वहाँ क्या अड़चन आई?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>फ़ॉरेन डिपार्टमेंट में फ़ाइल जाने का कारण और अंतरराष्ट्रीय अड़चन:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>कारण:</strong> वह जामुन का पेड़ दस साल पहले ‘पिटोनिया’ राज्य के प्रधानमंत्री ने भारत यात्रा के दौरान सेक्रेटेरिएट के लॉन में लगाया था। अतः पेड़ काटने का सीधा संबंध विदेश नीति और अंतरराष्ट्रीय कूटनीति से जुड़ गया।</li>\n        <li><strong>अड़चन:</strong> विदेश मंत्रालय ने स्पष्ट कहा कि यदि यह पेड़ काटा गया तो पिटोनिया राज्य से हमारे संबंध सदा के लिए बिगड़ जाएँगे। पिटोनिया सरकार हमारे देश को करोड़ों रुपये की सहायता देती है। क्या एक साधारण आदमी की जान के लिए दोनों देशों के मैत्रीपूर्ण संबंधों की बलि चढ़ाई जा सकती है?</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">पिटोनिया राज्य के प्रधानमंत्री द्वारा पेड़ लगाए जाने का तथ्य</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कूटनीतिक संबंधों और विदेशी सहायता रुकने के भय से पेड़ न काटना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch7-q5 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch7-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch7-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        ‘उसकी जीवन-फ़ाइल भी पूर्ण हो चुकी थी’—कहानी के इस अंतिम वाक्य में क्या व्यंग्य छिपा है?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>यह अंतिम वाक्य पूरी कहानी का सबसे मर्मभेदी, त्रासद और तीखा व्यंग्य है:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>फ़ाइल का अंत बनाम जीवन का अंत:</strong> जब भारत के प्रधानमंत्री विदेश दौरे से लौटे और उन्होंने अपनी व्यक्तिगत ज़िम्मेदारी पर पेड़ काटने की विशेष अनुमति दी, तब सुपरिंटेंडेंट फ़ाइल लेकर खुशी-खुशी दौड़ा आया। परंतु जब उसने दबे हुए आदमी का मुँह देखा, तो उसकी आँखें पथरा चुकी थीं, चींटियों की एक कतार उसके मुँह में जा रही थी और उसका शरीर ठंडा पड़ चुका था।</li>\n        <li><strong>नौकरशाही पर प्रहार:</strong> सरकारी कार्यालयों में कागज़ों और फ़ाइलों की औपचारिकताएँ तो पूरी हो जाती हैं, परंतु तब तक एक जीवित मनुष्य की 'जीवन-फ़ाइल' सदा के लिए बंद हो जाती है। यह लालफ़ीताशाही (Red Tapism), संवेदनहीनता और अमानवीय प्रशासनिक तंत्र पर करारा तमाचा है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">प्रधानमंत्री की अनुमति आने तक आदमी के प्राण पखेरू उड़ जाना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">लालफ़ीताशाही और संवेदनहीन तंत्र में मनुष्य के जीवन का कोई मूल्य न होना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(6)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← पाठ 6</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(8)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#c2410c; color:white; font-weight:700; cursor:pointer;\">अगला पाठ: भारत माता →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[8] = "<section class=\"chapter-section\" id=\"c11h-ch8\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#c2410c;\">8</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#c2410c;\">CBSE Class 11 हिंदी कोर &bull; आरोह भाग - 1 (गद्य खंड) &bull; पाठ 8</div>\n      <h2>भारत माता (जवाहरलाल नेहरू)</h2>\n      <p>NCERT तर्कसंगत (Rationalised) 2026–27 पाठ्यक्रम &bull; संपूर्ण 5 प्रामाणिक प्रश्नोत्तर एवं मार्किंग स्कीम</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #eff6ff, #dbeafe); border:1px solid #bfdbfe; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#1e40af; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M12 2a14.5 14.5 0 0 0 0 20 14.5 14.5 0 0 0 0-20\"/><path d=\"M2 12h20\"/></svg>\n      पंडित नेहरू की दृष्टि में ‘भारत माता’ की समग्र अवधारणा\n    </h3>\n    <svg viewBox=\"0 0 800 150\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"25\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#2563eb\" stroke-width=\"2\"/>\n      <text x=\"137\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1e40af\">सीमित किसान धारणा</text>\n      <text x=\"137\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">गाँव की मिट्टी</text>\n      <text x=\"137\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• धरती, खेत, ज़िला या सूबा</text>\n      <text x=\"137\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• पौराणिक देवी स्वरूप</text>\n\n      <path d=\"M 250 75 L 285 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"285\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <text x=\"397\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#065f46\">भौगोलिक विस्तार</text>\n      <text x=\"397\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">कश्मीर से कन्याकुमारी</text>\n      <text x=\"397\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• पहाड़, नदियाँ, जंगल और खेत</text>\n      <text x=\"397\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• अन्न देने वाली पावन धरा</text>\n\n      <path d=\"M 510 75 L 545 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"545\" y=\"20\" width=\"230\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#dc2626\" stroke-width=\"2\"/>\n      <text x=\"660\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#991b1b\">सर्वोच्च सत्य: जनता</text>\n      <text x=\"660\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">\"तुम स्वयं भारत माता हो\"</text>\n      <text x=\"660\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• करोड़ों करोड़ देशवासी</text>\n      <text x=\"660\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• 'भारत माता की जय' = जनता की जय</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT पाठ्यपुस्तक अभ्यास: पाठ के साथ</div>\n\n  <!-- c11h-ch8-q1 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch8-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch8-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        भारत की चर्चा नेहरू जी कब और किससे करते थे?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>पंडित जवाहरलाल नेहरू स्वतंत्रता आंदोलन के दौरान जब देश के विभिन्न भागों में जनसभाओं को संबोधित करने जाते थे, तब वे भारत की चर्चा करते थे:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>किसानों और ग्रामीणों से चर्चा:</strong> नेहरू जी विशेष रूप से ग्रामीण इलाकों के अशिक्षित व भोले-भाले किसानों से भारत की चर्चा करते थे। शहरी मध्यम वर्ग से वे अधिक चर्चा नहीं करते थे क्योंकि शहरियों का दृष्टिकोण पहले से ही व्यापक था और वे आधुनिक राजनीति समझते थे।</li>\n        <li><strong>समान समस्याओं का बोध कराना:</strong> वे किसानों को समझाते थे कि खैबर के दर्रे से लेकर कन्याकुमारी तक सभी भारतीय किसानों की समस्याएँ एक जैसी हैं—ग़रीबी, क़र्ज़, ज़मींदारों का शोषण, पुलिस का अत्याचार और विदेशी हुकूमत की गुलामी। इसलिए हम सबको मिलकर एक संपूर्ण राष्ट्र (स्वराज) के रूप में सोचना होगा।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">जनसभाओं में विशेषकर ग्रामीण किसानों से चर्चा करना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">उत्तर से दक्षिण तक किसानों की एक जैसी समस्याओं और राष्ट्रबोध का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch8-q2 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch8-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch8-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        नेहरू जी भारत के सभी किसानों से कौन-सा प्रश्न बार-बार करते थे?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>जब नेहरू जी किसी जलसे या सभा में पहुँचते, तो ग्रामीण किसान गगनभेदी आवाज़ में नारा लगाते— <strong>“भारत माता की जय!”</strong></p>\n      <p>नेहरू जी किसानों से तुरंत ठहरकर यह प्रश्न पूछते थे:</p>\n      <blockquote style=\"margin:8px 0; padding:10px 16px; background:#eff6ff; border-left:4px solid #2563eb; font-style:italic;\">\n        “यह भारत माता कौन है, जिसकी जय आप पुकार रहे हैं? वह धरती कौन-सी है जिसे आप भारत माता कहते हैं? क्या वह आपके गाँव की ज़मीन है? ज़िले की ज़मीन है? आपके सूबे की है या सारे हिंदुस्तान की धरती है?”\n      </blockquote>\n      <p>इस अप्रत्याशित प्रश्न को सुनकर किसान एक-दूसरे का मुँह ताकने लगते थे और निरुत्तर हो जाते थे।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">\"भारत माता की जय\" के नारे पर प्रतिप्रश्न पूछना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भारत माता कौन है तथा वह धरती गाँव, ज़िले या देश की है—सटीक प्रश्न उद्धृत</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch8-q3 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch8-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch8-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        दुनिया के बारे में किसानों को बताना नेहरू जी के लिए क्यों आसान था?\n      </div>\n      <div class=\"q-marks\">[4 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>नेहरू जी के लिए भारत के अनपढ़ किसानों को देश और दुनिया की व्यापक परिस्थितियों से परिचित कराना अपेक्षाकृत सरल था, इसके प्रमुख कारण थे:</p>\n      <ol style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>प्राचीन महाकाव्यों व तीर्थयात्राओं की परंपरा:</strong> भारत के ग्रामीण भले ही अशिक्षित थे, परंतु वे रामायण, महाभारत और पुराणों की कथाओं से भलीभांति परिचित थे। उन्होंने चारों धामों (बद्रीनाथ, रामेश्वरम, द्वारका, जगन्नाथपुरी) की तीर्थयात्राओं की कथाएँ सुनी थीं, जिससे वे पूरे देश के भूगोल से परिचित थे।</li>\n        <li><strong>सैनिकों के अनुभव:</strong> गाँवों के कई नौजवान प्रथम विश्वयुद्ध में ब्रिटिश सेना की ओर से विदेशों (फ्रांस, इराक, अफ्रीका आदि) में लड़कर लौटे थे और उन्होंने दुनिया के देशों की कहानियाँ गाँव वालों को सुनाई थीं।</li>\n        <li><strong>1930 की आर्थिक मंदी:</strong> 1930 के वैश्विक आर्थिक महामंदी (Great Depression) का प्रभाव भारत के किसानों पर भी पड़ा था, जिससे वे समझते थे कि विदेशों में होने वाली उथल-पुथल उनके अन्न के भावों को भी प्रभावित करती है।</li>\n      </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">रामायण-महाभारत और चारों धाम की तीर्थयात्राओं से राष्ट्रीय भूगोल का ज्ञान</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रथम विश्वयुद्ध में लड़े ग्रामीण सैनिकों के प्रत्यक्ष अनुभव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">1930 की वैश्विक आर्थिक मंदी का व्यावहारिक प्रभाव</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch8-q4 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch8-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch8-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        किसान सामान्यतः ‘भारत माता’ का क्या अर्थ लेते थे और नेहरू जी ने उन्हें क्या वास्तविक अर्थ समझाया?\n      </div>\n      <div class=\"q-marks\">[4 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p><strong>किसानों की पारंपरिक अवधारणा:</strong></p>\n      <p>किसान सामान्यतः ‘भारत माता’ का अर्थ धरती माता से लेते थे। कोई अपने गाँव की मिट्टी को, तो कोई अपने ज़िले या सूबे (प्रांत) की ज़मीन को भारत माता समझता था। उनके मन में किसी देवी जैसी पावन प्रतिमा की छवि थी।</p>\n      <p><strong>नेहरू जी द्वारा समझाया गया वास्तविक अर्थ:</strong></p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li>नेहरू जी ने बताया कि भारत की मिट्टी, पहाड़, नदियाँ, जंगल और खेत तो भारत माता हैं ही, परंतु भारत माता का सबसे विशाल और सच्चा स्वरूप <strong>इस देश के करोड़ों-करोड़ मनुष्य (जनता)</strong> हैं।</li>\n        <li>उन्होंने किसानों से कहा— <em>“तुम सब, तुम्हारे भाई-बंधु और देश के करोड़ों किसान ही दरअसल ‘भारत माता’ हैं। और इस प्रकार तुम स्वयं ही भारत माता के अंश हो। जब तुम ‘भारत माता की जय’ बोलते हो, तो वास्तव में तुम अपनी ही जयकार करते हो!”</em></li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">किसानों की सीमित अवधारणा: गाँव या राज्य की मिट्टी समझना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नेहरू जी का क्रांतिकारी विचार: करोड़ों देशवासी ही साक्षात् भारत माता हैं</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">\"तुम स्वयं भारत माता हो\" का बोध कराकर आत्मसम्मान जगाना</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch8-q5 (पाठ के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch8-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch8-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">पाठ के साथ</span><br>\n        ‘भारत माता’ पाठ का राष्ट्रीय चेतना और देशभक्ति के विकास में क्या ऐतिहासिक महत्व है?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>पंडित नेहरू द्वारा रचित ‘भारत माता’ (उनकी आत्मकथात्मक कृति <em>'हिंदुस्तान की कहानी' / The Discovery of India</em> का अंश) का ऐतिहासिक महत्व:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>अंधराष्ट्रवाद से मुक्त लोकतान्त्रिक दृष्टि:</strong> यह पाठ भारत माता को किसी रहस्यमयी या अलौकिक देवी की संकीर्ण परिधि से निकालकर आम जनता, अन्नदाताओं और श्रमजीवियों से जोड़ता है।</li>\n        <li><strong>अखंड भारत और राष्ट्रीय एकता का बोध:</strong> भाषाई, प्रांतीय और धार्मिक भिन्नताओं के बावजूद यह संपूर्ण हिंदुस्तान के वासियों को एक सूत्र में पिरोता है।</li>\n        <li><strong>आत्मगौरव की जागृति:</strong> जब शोषित और दरिद्र किसानों को यह अहसास कराया गया कि वे स्वयं भारत माता हैं, तो उनके भीतर सदियों की हीनभावना समाप्त हुई और स्वतंत्रता संग्राम के प्रति अदम्य आत्मसम्मान व ऊर्जा का संचार हुआ।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">संकीर्ण सीमाओं से निकालकर आम जनता को राष्ट्र का केंद्र बनाना</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अखंड राष्ट्रीय एकता और बंधुत्व की भावना का विस्तार</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">किसानों में आत्मसम्मान और लोकतांत्रिक नागरिक चेतना का संचार</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(7)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← पाठ 7</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(9)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#c2410c; color:white; font-weight:700; cursor:pointer;\">अगला पाठ: कबीर →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[9] = "<section class=\"chapter-section\" id=\"c11h-ch9\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#c2410c;\">9</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#c2410c;\">CBSE Class 11 हिंदी कोर &bull; आरोह भाग - 1 (काव्य खंड) &bull; पाठ 9</div>\n      <h2>कबीर (पद: हम तौ एक एक करि जांनां)</h2>\n      <p>NCERT तर्कसंगत (Rationalised) 2026–27 पाठ्यक्रम &bull; संपूर्ण 5 प्रामाणिक प्रश्नोत्तर एवं मार्किंग स्कीम</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #fff7ed, #ffedd5); border:1px solid #fed7aa; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#9a3412; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#ea580c\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M12 2a14.5 14.5 0 0 0 0 20 14.5 14.5 0 0 0 0-20\"/></svg>\n      कबीर का अद्वैत दर्शन: \"सब घटि अंतरि तूही\"\n    </h3>\n    <svg viewBox=\"0 0 800 150\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"25\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#ea580c\" stroke-width=\"2\"/>\n      <text x=\"137\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#9a3412\">ईश्वर की अद्वैत सत्ता</text>\n      <text x=\"137\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">एक ही परमात्मा</text>\n      <text x=\"137\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• \"एकै पवन एक ही पानी\"</text>\n      <text x=\"137\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• \"एकै जोति समाना\"</text>\n\n      <path d=\"M 250 75 L 285 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"285\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#c2410c\" stroke-width=\"2\"/>\n      <text x=\"397\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#9a3412\">अग्नि और काष्ठ का दृष्टांत</text>\n      <text x=\"397\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">अविनाशी आत्मा</text>\n      <text x=\"397\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• बढ़ई लकड़ी काट सकता है,</text>\n      <text x=\"397\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• उसमें छिपी अग्नि को नहीं</text>\n\n      <path d=\"M 510 75 L 545 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"545\" y=\"20\" width=\"230\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <text x=\"660\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#065f46\">माया-मोह से मुक्ति</text>\n      <text x=\"660\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">\"निरभै भया कबीरा\"</text>\n      <text x=\"660\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• संसार झूठे गर्व में पागल है</text>\n      <text x=\"660\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• निर्भय होकर प्रभु में दीवाना</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT पाठ्यपुस्तक अभ्यास: कविता के साथ एवं काव्य सौंदर्य</div>\n\n  <!-- c11h-ch9-q1 (कविता के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch9-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch9-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">कविता के साथ</span><br>\n        कबीर की दृष्टि में ईश्वर एक है। इसके समर्थन में उन्होंने क्या-क्या तर्क दिए हैं?\n      </div>\n      <div class=\"q-marks\">[4 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>कबीरदास जी ने एकेश्वरवाद (अद्वैतवाद) की पुष्टि के लिए प्रकृति और सांसारिक जीवन से अत्यंत सशक्त तर्क दिए हैं:</p>\n      <ol style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>प्राकृतिक एकरूपता:</strong> समस्त संसार में एक ही वायु (पवन) बहती है और सभी प्राणी एक ही जल का पान करते हैं। जब प्रकृति में कोई भेद नहीं, तो ईश्वर भिन्न कैसे हो सकते हैं? (<em>“एकै पवन एक ही पानी, एकै जोति समाना।”</em>)</li>\n        <li><strong>एक ही ज्योति का प्रसार:</strong> संसार के समस्त जीवों में एक ही परमात्मा का चैतन्य प्रकाश (परम ज्योति) व्याप्त है।</li>\n        <li><strong>कुम्हार और मिट्टी का उदाहरण:</strong> जिस प्रकार कुम्हार एक ही प्रकार की मिट्टी से विभिन्न प्रकार के बर्तन (घड़े, कटोरे आदि) गढ़ता है, उसी प्रकार सृष्टि के रचयिता ने एक ही पंचतत्व रूपी मिट्टी से सभी मानव शरीरों का निर्माण किया है। (<em>“एकै खाक गढ़े सब भांडै, एकै कोहरा साना।”</em>)</li>\n        <li><strong>अग्नि और काष्ठ का दृष्टांत:</strong> बढ़ई लकड़ी को तो काट सकता है, परंतु लकड़ी के भीतर अदृश्य रूप से समाई अग्नि को कोई नहीं काट सकता। इसी प्रकार नश्वर शरीर नष्ट हो जाता है, परंतु उसके भीतर का परमात्मा अविनाशी रहता है।</li>\n      </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">एक ही पवन और जल का प्राकृतिक तर्क</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कुम्हार द्वारा एक ही मिट्टी से भाँडे गढ़ने का दृष्टांत</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बढ़ई द्वारा लकड़ी काटने और अग्नि के न कटने का तर्क</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">समस्त घट-घट में एक ही परम ज्योति के संव्याप्त होने की पुष्टि</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch9-q2 (कविता के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch9-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch9-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">कविता के साथ</span><br>\n        मानव शरीर का निर्माण किन पाँच तत्वों (पंचतत्वों) से हुआ है?\n      </div>\n      <div class=\"q-marks\">[2 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>भारतीय दर्शन एवं कबीरदास जी के अनुसार मानव शरीर का निर्माण निम्नलिखित <strong>पाँच तत्वों (पंचमहाभूतों)</strong> के संयोग से हुआ है:</p>\n      <ol style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>पृथ्वी (धरा / मिट्टी)</strong> — जो शरीर की अस्थियों, माँस और भौतिक आकार का आधार है।</li>\n        <li><strong>जल (पानी)</strong> — जो शरीर में रक्त और तरलता के रूप में प्रवाहित होता है।</li>\n        <li><strong>अग्नि (तेज / ताप)</strong> — जो शरीर की जीवन-ऊष्मा और जठराग्नि के रूप में सक्रिय रहती है।</li>\n        <li><strong>वायु (पवन / प्राण)</strong> — जो श्वास-प्रश्वास के रूप में जीवन का संचार करती है।</li>\n        <li><strong>आकाश (गगन / शून्य)</strong> — जो शरीर के भीतर का अवकाश और चेतना का विस्तार है।</li>\n      </ol>\n      <p>मृत्यु के उपरांत यह नश्वर देह पुनः इन्हीं पाँचों मूल तत्वों में विलीन हो जाती है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">पाँचों तत्वों (पृथ्वी, जल, अग्नि, वायु, आकाश) का सही उल्लेख</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शरीर के निर्माण और मृत्यु उपरांत तत्वों में विलीनीकरण का संक्षिप्त विवरण</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch9-q3 (कविता के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch9-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch9-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">कविता के साथ</span><br>\n        ‘जैसे बाढ़ी काष्ठ ही काटै अगिनि न काटै कोई। सब घटि अंतरि तूही व्यापक धरै सरूपै सोई॥’—इन पंक्तियों के माध्यम से कबीर क्या प्रतिपादित करना चाहते हैं?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>इन अमर पंक्तियों के माध्यम से कबीरदास जी <strong>आत्मा की अमरता</strong> और <strong>परमात्मा की सर्वव्यापकता</strong> को प्रतिपादित करते हैं:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>दृष्टांत का मर्म:</strong> बाढ़ी (बढ़ई) अपनी कुल्हाड़ी या आरी से लकड़ी (काष्ठ) के टुकड़े-टुकड़े तो कर सकता है, परंतु उस काष्ठ के भीतर गुप्त रूप से विद्यमान अग्नि तत्व को वह कभी नहीं काट सकता।</li>\n        <li><strong>दार्शनिक सत्य:</strong> ठीक इसी प्रकार काल (मृत्यु) मनुष्य के नश्वर भौतिक शरीर को तो विनष्ट कर सकता है, परंतु शरीर के भीतर रमी हुई अविनाशी जीवात्मा और घट-घट वासी परमात्मा को कभी नष्ट नहीं किया जा सकता।</li>\n        <li><strong>सर्वव्यापक स्वरूप:</strong> वह एक ही परब्रह्म भिन्न-भिन्न जीवों और पदार्थों में अपनी लीला के अनुसार अनेक रूप धारण करके व्यापक रूप से विद्यमान है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">बढ़ई और काष्ठ की अग्नि के दृष्टांत का स्पष्टीकरण</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भौतिक शरीर के नाशवान और आत्मा के अविनाशी होने का निरूपण</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">घट-घट में परमात्मा के व्यापक स्वरूप का दार्शनिक निष्कर्ष</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch9-q4 (कविता के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch9-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch9-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">कविता के साथ</span><br>\n        कबीर ने अपने को ‘दीवाना’ क्यों कहा है?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>कबीरदास जी ने स्वयं को ‘दीवाना’ (ईश्वर-प्रेम में मतवाला / बावला) इसलिए कहा है क्योंकि:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>सांसारिक मोह-माया से विरक्ति:</strong> सामान्य संसार धन, पद, जाति और बाह्य आडंबरों के झूठे अभिमान में पागल है। कबीर ने सांसारिक प्रपंचों और नश्वर बंधनों को त्याग दिया है।</li>\n        <li><strong>ईश्वरीय प्रेम का नशा:</strong> वे सच्चे अंतःकरण से परब्रह्म के अद्वैत प्रेम में पूरी तरह डूब चुके हैं। जिसे परमात्मा के सत्य का साक्षात्कार हो जाता है, वह लोकलाज और सामाजिक भय से सर्वथा मुक्त होकर एक प्रेमी (दीवाने) की भाँति निर्भय हो जाता है। (<em>“कहै कबीर दीवाना।”</em>)</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">सांसारिक आडंबरों व माया-मोह से पूर्ण मुक्ति</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">परमात्मा के अनन्य प्रेम में लीन होकर निर्भय दीवाने का स्वरूप ग्रहण करना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch9-q5 (काव्य सौंदर्य) -->\n  <div class=\"q-card\" id=\"c11h-ch9-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch9-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">काव्य सौंदर्य</span><br>\n        कबीर के पद ‘हम तौ एक एक करि जांनां’ का शिल्प सौंदर्य (भाषा-शैली एवं अलंकार) स्पष्ट कीजिए।\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>कबीर के इस पद का शिल्प सौंदर्य अत्यंत प्रौढ़, प्रभावकारी और लोक-संस्कृति से जुड़ा हुआ है:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>सधुक्कड़ी / पंचमेल खिचड़ी भाषा:</strong> पद में अवधी, ब्रज, राजस्थानी और पूरबी बोलियों के सहज शब्दों का सुंदर समन्वय है। भाषा में उपदेशात्मकता और गेयता (संगीतात्मकता) है।</li>\n        <li><strong>अलंकार योजना:</strong>\n          <br>1. <strong>यमक अलंकार:</strong> <em>‘एक एक’</em> में पहले ‘एक’ का अर्थ परमात्मा और दूसरे ‘एक’ का अर्थ संख्या (अद्वैत) है।\n          <br>2. <strong>अनुप्रास अलंकार:</strong> <em>‘काष्ठ ही काटै’</em>, <em>‘सरूपै सोई’</em> में वर्णों की सुंदर आवृत्ति है।\n          <br>3. <strong>दृष्टांत एवं रूपकातिशयोक्ति:</strong> कुम्हार द्वारा मिट्टी गढ़े जाने और बढ़ई द्वारा काष्ठ काटने का अत्यंत सटीक दृष्टांत दिया गया है।</li>\n        <li><strong>शांत रस:</strong> पद में आध्यात्मिक ज्ञान और वैराग्य से परिपूर्ण शांत रस की प्रधानता है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">सधुक्कड़ी भाषा एवं गेय पद शैली का उल्लेख</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">यमक (\"एक एक\") और अनुप्रास अलंकार का सटीक उद्घाटन</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दृष्टांत अलंकार और शांत रस का प्रभावी विवेचन</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(8)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← पाठ 8</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(10)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#c2410c; color:white; font-weight:700; cursor:pointer;\">अगला पाठ: मीरा →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[10] = "<section class=\"chapter-section\" id=\"c11h-ch10\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#c2410c;\">10</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#c2410c;\">CBSE Class 11 हिंदी कोर &bull; आरोह भाग - 1 (काव्य खंड) &bull; पाठ 10</div>\n      <h2>मीरा (पद: मेरे तो गिरधर गोपाल दूसरो न कोई)</h2>\n      <p>NCERT तर्कसंगत (Rationalised) 2026–27 पाठ्यक्रम &bull; संपूर्ण 5 प्रामाणिक प्रश्नोत्तर एवं मार्किंग स्कीम</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #fdf2f8, #fce7f3); border:1px solid #fbcfe8; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#9d174d; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#db2777\" stroke-width=\"2\"><path d=\"M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z\"/></svg>\n      मीरा की अनन्य माधुर्य भक्ति: \"गिरधर गोपाल दूसरो न कोई\"\n    </h3>\n    <svg viewBox=\"0 0 800 150\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"25\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#db2777\" stroke-width=\"2\"/>\n      <text x=\"137\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#9d174d\">अनन्य समर्पण</text>\n      <text x=\"137\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">पति रूप में कृष्ण</text>\n      <text x=\"137\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• \"जाके सिर मोर-मुकुट\"</text>\n      <text x=\"137\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• कुल की कानि (मर्यादा) त्यागी</text>\n\n      <path d=\"M 250 75 L 285 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"285\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#9333ea\" stroke-width=\"2\"/>\n      <text x=\"397\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#7e22ce\">विरह साधना</text>\n      <text x=\"397\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">प्रेम-बेलि का सिंचन</text>\n      <text x=\"397\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• \"अंसुवन जल सींचि-सींचि\"</text>\n      <text x=\"397\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• अब तौ बेलि फैलि गई</text>\n\n      <path d=\"M 510 75 L 545 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"545\" y=\"20\" width=\"230\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <text x=\"660\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#065f46\">सार-तत्व की प्राप्ति</text>\n      <text x=\"660\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">दधि मथि घृत काढ़ि लियौ</text>\n      <text x=\"660\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• भक्ति का घी रख लिया</text>\n      <text x=\"660\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• संसार रूपी छाछ छोड़ दी</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT पाठ्यपुस्तक अभ्यास: कविता के साथ एवं काव्य सौंदर्य</div>\n\n  <!-- c11h-ch10-q1 (कविता के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch10-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch10-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">कविता के साथ</span><br>\n        मीरा कृष्ण की उपासना किस रूप में करती हैं? वह रूप कैसा है?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>मीराबाई श्रीकृष्ण की उपासना <strong>कांता भाव (पति / प्रियतम रूप)</strong> में करती हैं:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>माधुर्य भाव का स्वरूप:</strong> मीरा ने मन, वचन और कर्म से श्रीकृष्ण को ही अपना एकमात्र स्वामी और पति स्वीकार किया है। उनके अतिरिक्त संसार में उनका कोई दूसरा सगा-संबंधी नहीं है। (<em>“मेरे तो गिरधर गोपाल दूसरो न कोई।”</em>)</li>\n        <li><strong>कृष्ण का रूप-सौंदर्य:</strong> मीरा जिस रूप की दीवानी हैं, वह गोवर्धन पर्वत को उँगली पर उठाने वाले ‘गिरधर’ और गायों को चराने वाले ‘गोपाल’ हैं। उनके मस्तक पर मयूर पंखों का बना मुकुट (मोर-मुकुट) सुशोभित है। मीरा उसी मनोहर छवि पर अपना सर्वस्व न्योछावर कर चुकी हैं।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">कृष्ण को पति/प्रियतम (माधुर्य भाव) रूप में स्वीकारना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सिर पर मोर-मुकुट धारण करने वाले गिरधर गोपाल के रूप का चित्रण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch10-q2 (कविता के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch10-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch10-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">कविता के साथ</span><br>\n        ‘अंसुवन जल सींचि-सींचि प्रेम-बेलि बोयी। अब तौ बेलि फैलि गई आणंद-फल होई॥’—काव्य पंक्ति का भाव और शिल्प स्पष्ट कीजिए।\n      </div>\n      <div class=\"q-marks\">[4 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p><strong>भाव-सौंदर्य:</strong></p>\n      <p>मीराबाई कहती हैं कि उन्होंने श्रीकृष्ण के प्रति अपने अनन्य प्रेम रूपी लता को बड़ी कठिन साधना से रोपा है। उन्होंने विरह के वियोग में बहाए गए अश्रुओं के जल से रात-दिन सींचकर इस प्रेम-बेल को बड़ा किया है। अब यह साधना परिपक्व हो चुकी है और प्रेम-बेलि चारों ओर फैल गई है, जिस पर अब भक्ति के अलौकिक आनंद रूपी फल लगने लगे हैं। अर्थात् अब विरह की पीड़ा आनंदमय मिलन के संतोष में बदल चुकी है।</p>\n      <p><strong>शिल्प-सौंदर्य:</strong></p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><em>‘प्रेम-बेलि’</em> और <em>‘आणंद-फल’</em> में <strong>रूपक अलंकार</strong> है।</li>\n        <li><em>‘सींचि-सींचि’</em> में <strong>पुनरुक्ति प्रकाश अलंकार</strong> है।</li>\n        <li>राजस्थानी मिश्रित ब्रजभाषा की मधुर शब्दावली और संगीतात्मकता है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">भाव सौंदर्य: विरह के आंसुओं से सिंचित प्रेम लता का आनंद फल देना</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शिल्प सौंदर्य: रूपक अलंकार, पुनरुक्ति प्रकाश एवं राजस्थानी-ब्रज भाषा</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch10-q3 (कविता के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch10-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch10-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">कविता के साथ</span><br>\n        ‘दध मथि घृत काढ़ि लियौ, डारि दयी छोयी’—इस रूपक के माध्यम से मीरा क्या कहना चाहती हैं?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>दूध और मथानी के रूपक के माध्यम से मीराबाई संसार और ईश्वरीय भक्ति के सार-तत्व का गहन आध्यात्मिक उद्घाटन करती हैं:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>रूपक का अर्थ:</strong> जिस प्रकार दही को मथकर मक्खन (घी) निकाल लिया जाता है और व्यर्थ व सारहीन छाछ (मट्ठा) को फेंक दिया जाता है।</li>\n        <li><strong>दार्शनिक संदेश:</strong> मीरा कहती हैं कि उन्होंने ज्ञान और प्रेम की मथानी से इस संसार का भलीभांति मंथन किया है। उन्होंने पाया कि इस संसार का एकमात्र मूल्यवान सार-तत्व (घी) श्रीकृष्ण का पावन नाम और उनकी भक्ति है, जिसे उन्होंने अपने हृदय में सहेज लिया है। शेष संसार के भौतिक रिश्ते, भोग-विलास और सांसारिक मोह-माया केवल तुच्छ छाछ के समान व्यर्थ हैं, जिसे उन्होंने त्याग दिया है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">दही मथकर घी निकालने और छाछ छोड़ने के रूपक का स्पष्टीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कृष्ण भक्ति को सारभूत \"घी\" और भौतिक संसार को व्यर्थ \"छाछ\" सिद्ध करना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch10-q4 (कविता के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch10-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch10-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">कविता के साथ</span><br>\n        लोग मीरा को ‘बावरी’ क्यों कहते हैं?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>संसार के लोग मीरा को ‘बावरी’ (पागल / मतवाली) इसलिए कहते हैं क्योंकि:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>राजघराने की मर्यादाओं का परित्याग:</strong> मेवाड़ के राजघराने की महारानी (राजवधू) होने के बावजूद मीरा ने पर्दा प्रथा, राजसी वैभव और सुख-सुविधाओं को ठोकर मार दी।</li>\n        <li><strong>साधु-संतों की संगति:</strong> वे राजमहलों को छोड़कर नंगे पाँव मंदिरों में जाकर साधु-संतों की संगति में बैठती थीं, करताल बजाकर कृष्ण-प्रेम में भाव-विभोर होकर नृत्य करती थीं।</li>\n        <li>संसार जो भौतिक मान-सम्मान और कुल की मर्यादा (कानि) को सब कुछ समझता था, मीरा के लिए वह सब तिनके के समान व्यर्थ था। सांसारिक दृष्टि से अंधे लोगों को मीरा का यह अलौकिक ईश्वरीय उन्माद पागलपन (बावरापन) प्रतीत होता था।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">राजघराने के वैभव और कुल-मर्यादा की उपेक्षा</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">साधु-संगति और कृष्ण प्रेम में सुध-बुध खोकर नाचने को सांसारिक लोगों द्वारा पागलपन समझना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch10-q5 (कविता के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch10-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch10-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">कविता के साथ</span><br>\n        ‘भगत देखि राजी भई, जगत देखि रोयी’—मीरा के हर्ष और रुदन का क्या कारण है?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>मीराबाई के हर्ष (प्रसन्नता) और रुदन (शोक) के कारण:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>भक्तों को देखकर हर्षित होना:</strong> जब मीरा ईश्वर के सच्चे भक्तों, संतों और साधकों को प्रभु की भक्ति में लीन देखती हैं, तो वे फूली नहीं समातीं। उन्हें लगता है कि यही सच्चा जीवन है और आत्मा का सच्चा कल्याण इसी में है।</li>\n        <li><strong>संसार को देखकर रोना:</strong> जब वे सांसारिक मनुष्यों को धन, वासना, ईर्ष्या और नश्वर माया-मोह के दलदल में डूबते देखती हैं, तो उनका हृदय करुणा और पीड़ा से रो पड़ता है। वे दुःखी होती हैं कि अभागा संसार अमृत रूपी प्रभु-भक्ति को छोड़कर विष रूपी सांसारिक प्रपंचों में अपना अमूल्य मानव जीवन व्यर्थ गँवा रहा है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">सच्चे भक्तों को देखकर आत्मा के कल्याण की प्रसन्नता</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सांसारिक लोगों को माया-मोह में नष्ट होते देखकर गहरी करुणा और रुदन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(9)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← पाठ 9</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(11)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#c2410c; color:white; font-weight:700; cursor:pointer;\">अगला पाठ: घर की याद →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[11] = "<section class=\"chapter-section\" id=\"c11h-ch11\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#c2410c;\">11</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#c2410c;\">CBSE Class 11 हिंदी कोर &bull; आरोह भाग - 1 (काव्य खंड) &bull; पाठ 11</div>\n      <h2>घर की याद (भवानीप्रसाद मिश्र)</h2>\n      <p>NCERT तर्कसंगत (Rationalised) 2026–27 पाठ्यक्रम &bull; संपूर्ण 5 प्रामाणिक प्रश्नोत्तर एवं मार्किंग स्कीम</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #eff6ff, #dbeafe); border:1px solid #bfdbfe; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#1e40af; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"2\"><path d=\"M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z\"/></svg>\n      जेल प्रवास में घर की स्मृतियाँ और सावन का दूत रूप\n    </h3>\n    <svg viewBox=\"0 0 800 150\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"25\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#2563eb\" stroke-width=\"2\"/>\n      <text x=\"137\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1e40af\">कारागार और वर्षा</text>\n      <text x=\"137\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">1942 भारत छोड़ो जेल</text>\n      <text x=\"137\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• आज पानी गिर रहा है,</text>\n      <text x=\"137\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• बहुत पानी गिर रहा है</text>\n\n      <path d=\"M 250 75 L 285 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"285\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#dc2626\" stroke-width=\"2\"/>\n      <text x=\"397\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#991b1b\">परिवार का आत्मीय संसार</text>\n      <text x=\"397\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">पिता, माँ, भाई व बहनें</text>\n      <text x=\"397\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• चार भाई, चार बहिनें</text>\n      <text x=\"397\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• पाँचवाँ मैं अभागा भवानी</text>\n\n      <path d=\"M 510 75 L 545 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"545\" y=\"20\" width=\"230\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <text x=\"660\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#065f46\">सावन को संदेश</text>\n      <text x=\"660\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">पिता को सांत्वना</text>\n      <text x=\"660\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• कहना मैं मजे में हूँ,</text>\n      <text x=\"660\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• जेल की व्यथा मत कह देना</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT पाठ्यपुस्तक अभ्यास: कविता के साथ एवं शिल्प सौंदर्य</div>\n\n  <!-- c11h-ch11-q1 (कविता के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch11-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch11-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">कविता के साथ</span><br>\n        पानी के रात भर गिरने और प्राण-मन के घिरने में परस्पर क्या संबंध है?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>कवि भवानीप्रसाद मिश्र 1942 के स्वतंत्रता आंदोलन के दौरान जेल में बंद हैं। सावन की घनघोर वर्षा और उनकी अंतर्मन की वेदना में गहरा संवेदनात्मक संबंध है:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>बाहरी वर्षा से आंतरिक स्मृतियों का जागरण:</strong> बाहर आकाश से रात भर मूसलाधार पानी बरस रहा है। जैसे-जैसे वर्षा का वेग बढ़ता है, वैसे-वैसे कवि के विरही मन में अपने प्रिय घर, माता-पिता और भाई-बहनों की स्मृतियाँ घिर-घिर कर छाने लगती हैं।</li>\n        <li><strong>एकाकीपन और विरह की सघनता:</strong> कारागार के अकेलेपन में वर्षा की बूँदें कवि की आँख के आँसू बन जाती हैं। पानी का गिरना केवल एक प्राकृतिक घटना नहीं, बल्कि कवि के भावुक हृदय का अश्रुपात है जो घर की यादों में आकंठ डूब गया है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">बाहरी वर्षा की तीव्रता से मन में पारिवारिक स्मृतियों का उमड़ना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कारागार के एकाकीपन में विरह वेदना और आंसुओं का एकाकार होना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch11-q2 (कविता के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch11-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch11-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">कविता के साथ</span><br>\n        मायके आई बहन के लिए कवि ने घर को ‘परिताप का घर’ क्यों कहा है?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>मायके आई बहन के लिए घर को ‘परिताप (अत्यधिक दुःख व संताप) का घर’ कहने का मर्मभेदी कारण:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>सुख की कल्पना:</strong> विवाहित बहन बड़े उत्साह, उल्लास और उमंग के साथ सावन में अपने मायके आई थी कि वह अपने सभी भाइयों और माता-पिता से मिलकर खुशियाँ मनाएगी।</li>\n        <li><strong>पाँचवें भाई की अनुपस्थिति:</strong> परंतु घर पहुँचकर उसने देखा कि उसका प्यारा पाँचवाँ भाई (भवानी) घर पर नहीं है, बल्कि स्वतंत्रता संग्राम के कारण अंग्रेज़ों की जेल में यातनाएँ सह रहा है। भाई की अनुपस्थिति के कारण घर का पूरा वातावरण रोने-धोने और शोक में डूबा हुआ था। जो घर आनंद और उल्लास का केंद्र होना चाहिए था, वह बहन के लिए असह्य संताप और शोक का घर बन गया।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">मायके में खुशियाँ मनाने आई बहन की प्रत्याशा</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भवानी के जेल में होने के कारण परिवार के विलाप से घर का परिताप बनना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch11-q3 (कविता के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch11-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch11-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">कविता के साथ</span><br>\n        पिता के व्यक्तित्व की किन-किन विशेषताओं को कविता में उकेरा गया है?\n      </div>\n      <div class=\"q-marks\">[4 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>कविता में कवि ने अपने पिता के अत्यंत तेजस्वी, कर्मठ और भावुक व्यक्तित्व का सजीव चित्र खींचा है:</p>\n      <ol style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>अद्भुत शारीरिक स्वास्थ्य और स्फूर्ति:</strong> बुढ़ापे ने उन्हें छुआ तक नहीं था। वे आज भी दौड़ सकते थे, खिलखिलाकर हँसते थे और रोज़ नियम से 260 दंड-बैठक लगाकर मुग्दर घुमाते थे।</li>\n        <li><strong>निर्भीकता और ओजस्वी वाणी:</strong> मौत के सामने भी वे हिचकते नहीं थे और शेर के आगे भी नहीं डरते थे। उनकी आवाज़ में बादलों की तरह गरजना थी और काम में तूफ़ान जैसी गति थी।</li>\n        <li><strong>कोमल एवं भावुक हृदय:</strong> बाहर से वज्र जैसे कठोर दिखने वाले पिता भीतर से अत्यंत कोमल थे। जब गीता पाठ करके वे छत से नीचे उतरे और अपने चार बेटों के बीच पाँचवें बेटे भवानी को न पाया, तो उनकी आँखों से अश्रुधारा बह निकली।</li>\n      </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">शारीरिक स्फूर्ति, 260 दंड-बैठक और बुढ़ापे पर विजय</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शेर और मौत के आगे न डरने वाली निर्भीकता</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पाँचवें बेटे की याद में फफक कर रो पड़ने वाला कोमल पितृ-हृदय</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch11-q4 (कविता के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch11-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch11-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">कविता के साथ</span><br>\n        निम्नलिखित पंक्तियों में ‘बस’ शब्द के लाक्षणिक प्रयोग की विशेषता बताइए: “मैं मजे में हूँ सही है, घर नहीं हूँ बस यही है, किंतु इस बस में बड़ा बस है, इसी बस से सब विरस है।”\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>कवि ने इन पंक्तियों में <strong>‘बस’</strong> शब्द का अत्यंत विलक्षण, चमत्कारी और मार्मिक लाक्षणिक प्रयोग (यमक सदृश) किया है:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>प्रथम ‘बस’ (केवल / मात्र):</strong> <em>“घर नहीं हूँ बस यही है”</em> — यहाँ ‘बस’ का अर्थ है 'केवल' इतनी सी बात है कि मैं घर पर नहीं हूँ। कवि इसे एक छोटी सी बात के रूप में प्रस्तुत करता है।</li>\n        <li><strong>द्वितीय ‘बस’ (विवशता / लाचारी):</strong> <em>“किंतु इस बस में बड़ा बस है”</em> — यहाँ ‘बस’ का अर्थ है गहरी 'विवशता' और पराधीनता। जेल में बंद होना कोई साधारण बात नहीं, बल्कि एक भारी बेबसी है।</li>\n        <li><strong>तृतीय ‘बस’ (कारण / वियोग):</strong> <em>“इसी बस से सब विरस है”</em> — इसी विवशता और अलगाव के कारण जीवन का सारा रस और आनंद समाप्त हो गया है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">प्रथम \"बस\" का अर्थ: केवल / मात्र (अल्पता का द्योतक)</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">द्वितीय \"बस\" का अर्थ: विवशता / लाचारी (पराधीनता का बोध)</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तृतीय \"बस\" का अर्थ: वियोग का कारण जिससे जीवन विरस हो गया</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch11-q5 (कविता के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch11-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch11-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">कविता के साथ</span><br>\n        कविता के अंतिम हिस्से में कवि ने सावन को क्या संदेश देकर अपने पिता के पास भेजा?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>कवि सावन को एक स्नेही दूत (कालिदास के मेघदूत की भाँति) बनाकर अपने घर भेजता है और हिदायत देता है:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>सच्चाई छिपाने का निर्देश:</strong> सावन से कहता है कि हे मंगलकारी सावन! तुम चाहे जितना बरस लो, पर मेरे पिता की आँखों से आँसू नहीं बरसने चाहिए। उन्हें जाकर यह मत बताना कि मैं यहाँ जेल में रोता हूँ, उदास रहता हूँ, रात भर जागता हूँ और आदमियों से डरकर भागता हूँ।</li>\n        <li><strong>धैर्य और आनंद का संदेश:</strong> उनसे कहना कि भवानी जेल में बहुत मजे में है। वह सूत कातता है, वजन उसका सत्तर सेर हो गया है, वह खूब खाता-पीता और खेलता-कूदता है। इस प्रकार कवि अपने माता-पिता के हृदय को पीड़ा से बचाने के लिए अपने समस्त कष्टों को हँसते-हँसते छिपा लेता है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">सावन को दूत बनाकर पिता के आँसू रोकने की प्रार्थना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">जेल के कष्टों को छिपाकर कुशल-मंगल व सूत कातने का झूठा संदेश देना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(10)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← पाठ 10</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(12)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#c2410c; color:white; font-weight:700; cursor:pointer;\">अगला पाठ: चंपा काले काले अच्छर नहीं चीन्हती →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[12] = "<section class=\"chapter-section\" id=\"c11h-ch12\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#c2410c;\">12</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#c2410c;\">CBSE Class 11 हिंदी कोर &bull; आरोह भाग - 1 (काव्य खंड) &bull; पाठ 12</div>\n      <h2>चंपा काले-काले अच्छर नहीं चीन्हती (त्रिलोचन)</h2>\n      <p>NCERT तर्कसंगत (Rationalised) 2026–27 पाठ्यक्रम &bull; संपूर्ण 4 प्रामाणिक प्रश्नोत्तर एवं मार्किंग स्कीम</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #f0fdf4, #ecfdf5); border:1px solid #a7f3d0; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#065f46; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/></svg>\n      निरक्षरता, ग्रामीण भोलापन और कलकत्ता का अभिशाप\n    </h3>\n    <svg viewBox=\"0 0 800 150\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"25\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <text x=\"137\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#065f46\">चंपा का भोलापन</text>\n      <text x=\"137\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">ग्वाले की नटखट बेटी</text>\n      <text x=\"137\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• अक्षरों को काले चिह्न समझना</text>\n      <text x=\"137\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• कलम व कागज़ चुराकर छिपाना</text>\n\n      <path d=\"M 250 75 L 285 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"285\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d97706\" stroke-width=\"2\"/>\n      <text x=\"397\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#b45309\">कवि का उपदेश</text>\n      <text x=\"397\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">गांधी बाबा का नाम</text>\n      <text x=\"397\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• \"पढ़ना-लिखना अच्छा है\"</text>\n      <text x=\"397\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• पति परदेस जाएगा तो पत्र लिखना</text>\n\n      <path d=\"M 510 75 L 545 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"545\" y=\"20\" width=\"230\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#dc2626\" stroke-width=\"2\"/>\n      <text x=\"660\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#991b1b\">चंपा का शाप</text>\n      <text x=\"660\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">\"कलकत्ते पर बजर गिरे\"</text>\n      <text x=\"660\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• पति को कभी कलकत्ता न जाने देगी</text>\n      <text x=\"660\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• परिवार तोड़ने वाले नगर का विनाश</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT पाठ्यपुस्तक अभ्यास: कविता के साथ</div>\n\n  <!-- c11h-ch12-q1 (कविता के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch12-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch12-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">कविता के साथ</span><br>\n        चंपा ने किसके बारे में ऐसा क्यों कहा कि ‘कलकत्ते पर बजर गिरे’?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>चंपा ने महानगर <strong>कलकत्ता (कोलकाता)</strong> के बारे में यह तीव्र अभिशाप दिया कि <em>“कलकत्ते पर बजर (वज्र / बिजली) गिरे!”</em></p>\n      <p><strong>ऐसा कहने का कारण:</strong></p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>परिवारों को उजाड़ने वाला महानगर:</strong> चंपा ने अपने गाँव में देखा था कि गरीब परिवारों के नवविवाहित युवक आजीविका की तलाश में कलकत्ता चले जाते हैं और बरसों तक वापस नहीं लौटते। उनकी पत्नियाँ वियोग और लाचारी में तड़पती रहती हैं।</li>\n        <li><strong>विस्थापन का भय:</strong> जब कवि ने उससे कहा कि जब तेरी शादी होगी और तेरा पति कलकत्ता कमाने जाएगा, तब तू उसे पत्र कैसे लिखेगी? चंपा को लगा कि यह कलकत्ता शहर ही ग्रामीण दांपत्य जीवन को नष्ट करने वाला राक्षस है। इसलिए वह अपने सुहाग और परिवार को सुरक्षित रखने के लिए कलकत्ता के समूल विनाश की कामना करती है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">कलकत्ता महानगर पर वज्र गिरने के अभिशाप का उल्लेख</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">ग्रामीण युवकों के पलायन और विस्थापन की त्रासद पीड़ा</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पारिवारिक विघटन के प्रति चंपा का स्वाभाविक ग्रामीण आक्रोश</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch12-q2 (कविता के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch12-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch12-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">कविता के साथ</span><br>\n        चंपा को इस बात पर क्यों विश्वास नहीं होता कि गांधी बाबा ने पढ़ने-लिखने को कहा होगा?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>चंपा को कवि की इस बात पर विश्वास नहीं होता कि महात्मा गांधी (गांधी बाबा) ने पढ़ने-लिखने की सीख दी होगी, इसके प्रमुख कारण हैं:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>गांधी जी की लोक-छवि:</strong> चंपा के अबोध मन में गांधी बाबा की छवि एक अत्यंत दयालु, भले, संन्यासी और गरीबों का भला करने वाले महापुरुष के रूप में थी।</li>\n        <li><strong>शिक्षा के प्रति चंपा का अनुभव:</strong> चंपा के अनुभव में जो लोग पढ़-लिख जाते हैं, वे चालाक, धूर्त, स्वार्थी हो जाते हैं और गाँव छोड़कर शहर भाग जाते हैं तथा अपने परिवार को कष्ट देते हैं। चंपा सोचती है कि जो गांधी बाबा इतने अच्छे हैं, वे भला ऐसा अनिष्टकारी और धूर्तता सिखाने वाला काम (पढ़ना-लिखना) करने के लिए कैसे कह सकते हैं!</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">गांधी जी की परोपकारी व दयालु लोक-छवि का चित्रण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">चंपा की दृष्टि में शिक्षित लोगों का स्वार्थी होना और पलायन करना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch12-q3 (कविता के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch12-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch12-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">कविता के साथ</span><br>\n        कवि ने चंपा की किन-किन विशेषताओं का उल्लेख किया है?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>कवि त्रिलोचन ने चंपा के चरित्र की निम्नलिखित स्वाभाविक एवं ग्रामीण विशेषताओं को उकेरा है:</p>\n      <ol style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>अत्यंत चंचल और नटखट:</strong> चंपा सुंदर ग्वाले की निरक्षर बेटी है जो दिन भर गाय-भैंसों को चराने का काम करती है। वह बहुत शरारती है और कभी कवि की कलम छिपा देती है, तो कभी कागज़ गायब कर देती है।</li>\n        <li><strong>स्पष्टवक्ता और विद्रोही:</strong> वह जो सोचती है, बिना किसी झिझक के साफ़-साफ़ कह देती है। जब कवि पढ़ने के लिए कहते हैं, तो वह डंके की चोट पर कहती है— <em>“मैं तो नहीं पढ़ूँगी!”</em></li>\n        <li><strong>पारिवारिक मूल्यों की रक्षक:</strong> वह अपने भावी पति के साथ रहना चाहती है, उसे कभी कलकत्ता नहीं जाने देगी। उसका प्रेम छल-कपट से रहित और प्राकृतिक है।</li>\n      </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">सुंदर ग्वाले की नटखट व चंचल चरवाहे कन्या की छवि</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कलम-कागज़ चुराने की शरारत और निडर स्पष्टवादिता</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दांपत्य प्रेम और परिवार को एकजुट रखने की निष्ठा</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch12-q4 (कविता के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch12-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch12-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">कविता के साथ</span><br>\n        कविता में पूर्वी उत्तर प्रदेश के ग्रामीण जीवन की किन सामाजिक विसंगतियों को उठाया गया है?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>त्रिलोचन की यह कविता ग्रामीण यथार्थ की दो बड़ी विसंगतियों पर गहरा प्रकाश डालती है:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>बालिका शिक्षा का अभाव (व्यापक निरक्षरता):</strong> ग्रामीण भारत में विशेषकर बालिकाओं की शिक्षा को व्यर्थ समझा जाता था। चंपा अक्षरों को केवल काले-काले चिह्न मानती है और यह नहीं समझ पाती कि इन बेजान रेखाओं से बोल कैसे निकलते हैं।</li>\n        <li><strong>महानगरों की ओर पलायन (विस्थापन की त्रासदी):</strong> गाँवों में रोज़गार न होने के कारण पुरुषों का कलकत्ता जैसे औद्योगिक शहरों की ओर पलायन और पीछे छूटे परिवारों का विरह में तिल-तिल कर जलना। यह विसंगति आज भी भारतीय ग्रामीण समाज का कड़वा सच है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">बालिका निरक्षरता और शिक्षा के प्रति अज्ञानता का चित्रण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आर्थिक तंगी के कारण महानगरों की ओर पलायन और विस्थापन की पीड़ा</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(11)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← पाठ 11</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(13)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#c2410c; color:white; font-weight:700; cursor:pointer;\">अगला पाठ: गजल →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[13] = "<section class=\"chapter-section\" id=\"c11h-ch13\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#c2410c;\">13</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#c2410c;\">CBSE Class 11 हिंदी कोर &bull; आरोह भाग - 1 (काव्य खंड) &bull; पाठ 13</div>\n      <h2>गजल (दुष्यंत कुमार)</h2>\n      <p>NCERT तर्कसंगत (Rationalised) 2026–27 पाठ्यक्रम &bull; संपूर्ण 4 प्रामाणिक प्रश्नोत्तर एवं मार्किंग स्कीम</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #fef2f2, #fee2e2); border:1px solid #fecaca; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#991b1b; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#dc2626\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"4.93\" y1=\"4.93\" x2=\"19.07\" y2=\"19.07\"/></svg>\n      राजनीतिक मोहभंग और जन-क्रांति का आह्वान: ‘साए में धूप’\n    </h3>\n    <svg viewBox=\"0 0 800 150\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"25\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#dc2626\" stroke-width=\"2\"/>\n      <text x=\"137\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#991b1b\">व्यवस्था की विसंगति</text>\n      <text x=\"137\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">झूठे राजनीतिक वादे</text>\n      <text x=\"137\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• \"कहाँ तो तय था चिराग़ाँ\"</text>\n      <text x=\"137\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• पूरे शहर में चिराग नहीं</text>\n\n      <path d=\"M 250 75 L 285 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"285\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#ea580c\" stroke-width=\"2\"/>\n      <text x=\"397\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#c2410c\">जनता का समझौता</text>\n      <text x=\"397\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">चुप्पी और लाचारी</text>\n      <text x=\"397\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• \"न हो कमीज़ तो पाँवों से\"</text>\n      <text x=\"397\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• पेट ढँक लेने वाले लोग</text>\n\n      <path d=\"M 510 75 L 545 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"545\" y=\"20\" width=\"230\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#16a34a\" stroke-width=\"2\"/>\n      <text x=\"660\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#15803d\">क्रांति की प्रतीक्षा</text>\n      <text x=\"660\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">पत्थर में चिंगारी</text>\n      <text x=\"660\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• \"पत्थर पिघल नहीं सकता\"</text>\n      <text x=\"660\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• कवि आवाज़ के असर को बेकरार</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT पाठ्यपुस्तक अभ्यास: गजल के साथ</div>\n\n  <!-- c11h-ch13-q1 (गजल के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch13-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch13-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">गजल के साथ</span><br>\n        ‘कहाँ तो तय था चिराग़ाँ हरेक घर के लिए, कहाँ चिराग़ मयस्सर नहीं शहर के लिए।’—गजल के इस पहले शेर का आशय स्पष्ट कीजिए।\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>दुष्यंत कुमार का यह शेर आज़ादी के बाद भारतीय जनता में फैले <strong>गहरे राजनीतिक मोहभंग और निराशा</strong> का प्रतीक है:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>वादा बनाम हक़ीक़त:</strong> स्वतंत्रता प्राप्ति के समय देश के कर्णधारों ने स्वप्न दिखाया था कि आज़ाद भारत में हर घर में खुशहाली और रोशनी होगी (<em>“चिराग़ाँ हरेक घर के लिए”</em>)।</li>\n        <li><strong>कड़वी सच्चाई:</strong> आज़ादी के दशकों बाद भी स्थिति यह है कि पूरे के पूरे शहर के लिए भी एक चिराग (मूलभूत सुविधाएँ जैसे बिजली, पानी, रोज़गार) उपलब्ध नहीं है। यह शेर शासक वर्ग के झूठे वादों और आम जनता की बदहाली पर तीखा व्यंग्य करता है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">स्वतंत्रता आंदोलन के समय किए गए झूठे राजनीतिक वादों का प्रकटीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दशकों बाद भी आम जनता को मूलभूत सुविधाओं से वंचित रखने का यथार्थ</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch13-q2 (गजल के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch13-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch13-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">गजल के साथ</span><br>\n        ‘न हो कमीज़ तो पाँवों से पेट ढँक लेंगे, ये लोग कितने मुनासिब हैं इस सफ़र के लिए।’—यह पंक्ति किस प्रकार के लोगों की ओर संकेत करती है?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>यह पंक्ति हमारे देश के <strong>अत्यंत दबे-कुचले, शोषित, मूक और समझौतावादी नागरिकों</strong> की ओर संकेत करती है:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>अन्याय सहने की आदत:</strong> ये वे लोग हैं जिनके पास पहनने के लिए कमीज़ (वस्त्र / मूलभूत अधिकार) तक नहीं है, परंतु वे व्यवस्था के विरुद्ध आवाज़ उठाने या बगावत करने के बजाय अपने पैरों को सिकोड़कर पेट ढँकने का समझौता कर लेते हैं।</li>\n        <li><strong>सत्ताधारियों की पसंद:</strong> निरंकुश और भ्रष्ट शासकों के लिए ऐसे दीन-हीन, चुपचाप अत्याचार सहने वाले मूक लोग ही सबसे 'मुनासिब' (उपयुक्त) होते हैं, क्योंकि ऐसे निस्तेज समाज में सत्ताधारियों को अपनी कुर्सी छिनने का कोई भय नहीं रहता।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">अभावग्रस्त और समझौतावादी शोषित वर्ग की पहचान</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अन्याय के विरुद्ध न बोलने के कारण भ्रष्ट शासकों के लिए अनुकूल सिद्ध होना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch13-q3 (गजल के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch13-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch13-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">गजल के साथ</span><br>\n        ‘वे मुतमइन हैं कि पत्थर पिघल नहीं सकता, मैं बेक़रार हूँ आवाज़ में असर के लिए।’—कवि का इस पर क्या दृष्टिकोण है?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>इस शेर में आम जनता की निराशा और कवि की क्रांतिकारी आशावादिता का द्वंद्व उपस्थित है:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>जनता का विश्वास (मुतमइन):</strong> शोषित जनता यह मानकर पूरी तरह आश्वस्त (मुतमइन) और शांत बैठ चुकी है कि व्यवस्था रूपी यह कठोर 'पत्थर' (संवेदनहीन शासन तंत्र) कभी नहीं पिघल सकता, इसलिए विद्रोह करना व्यर्थ है।</li>\n        <li><strong>कवि का क्रांतिकारी संकल्प:</strong> कवि इस निराशा को स्वीकार नहीं करता। वह जानता है कि यदि आम आदमी की आवाज़ में पीड़ा और सच्चाई का 'असर' पैदा हो जाए, तो बड़े से बड़ा कठोर पत्थर भी पिघल सकता है। कवि जनता के भीतर सोए हुए उसी क्रांतिकारी आक्रोश को जगाने के लिए बेकरार है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">जनता की यह निराशावादी धारणा कि व्यवस्था कभी नहीं सुधर सकती</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">जन-आक्रोश की आवाज़ से व्यवस्था बदलने के प्रति कवि की अटूट आशावादिता</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch13-q4 (गजल के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch13-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch13-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">गजल के साथ</span><br>\n        दुष्यंत कुमार की गजल की भाषा-शैली की प्रमुख विशेषताएँ बताइए।\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>दुष्यंत कुमार ने उर्दू गजल विधा को हिंदी जनमानस और सामाजिक चेतना का सशक्त माध्यम बनाया:</p>\n      <ol style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>सहज और संप्रेषणीय हिंदुस्तानी भाषा:</strong> गजल में क्लिष्ट उर्दू या संस्कृतनिष्ठ हिंदी के बजाय आम बोलचाल की हिंदुस्तानी भाषा (मयस्सर, मुतमइन, मुनासिब, चिराग आदि) का सजीव प्रयोग है।</li>\n        <li><strong>प्रतीकात्मकता और व्यंग्य:</strong> 'चिराग', 'साए में धूप', 'पत्थर' आदि शब्द व्यवस्था की विद्रूपताओं को उजागर करने वाले धारदार प्रतीक हैं।</li>\n        <li><strong>बह्र और गेयता:</strong> गजल का प्रत्येक शेर तयशुदा छन्द (बह्र) और तुकबंदी (क़ाफ़िया और रदीफ़: 'के लिए') के कड़े नियमों में बंधा हुआ और अत्यंत गेय है।</li>\n      </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">सहज एवं प्रहारक हिंदुस्तानी भाषा का प्रयोग</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सटीक राजनीतिक प्रतीकों और तीखे व्यंग्य का समावेश</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पारंपरिक गजल शिल्प (बह्र, क़ाफ़िया, रदीफ़) का सफल निर्वाह</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(12)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← पाठ 12</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(14)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#c2410c; color:white; font-weight:700; cursor:pointer;\">अगला पाठ: हे भूख मत मचल →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[14] = "<section class=\"chapter-section\" id=\"c11h-ch14\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#c2410c;\">14</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#c2410c;\">CBSE Class 11 हिंदी कोर &bull; आरोह भाग - 1 (काव्य खंड) &bull; पाठ 14</div>\n      <h2>हे भूख! मत मचल, हे मेरे जूही के फूल जैसे ईश्वर (अक्कमहादेवी)</h2>\n      <p>NCERT तर्कसंगत (Rationalised) 2026–27 पाठ्यक्रम &bull; संपूर्ण 4 प्रामाणिक प्रश्नोत्तर एवं मार्किंग स्कीम</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #fdf4ff, #fae8ff); border:1px solid #f0abfc; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#86198f; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#c026d3\" stroke-width=\"2\"><path d=\"M12 2a10 10 0 1 0 10 10A10 10 0 0 0 12 2zm1 14.93V17a1 1 0 0 1-2 0v-.07A7 7 0 0 1 5.07 11H5a1 1 0 0 1 0-2h.07A7 7 0 0 1 11 3.07V3a1 1 0 0 1 2 0v.07A7 7 0 0 1 18.93 9H19a1 1 0 0 1 0 2h-.07A7 7 0 0 1 13 16.93z\"/></svg>\n      वीरशैव भक्ति आंदोलन: इंद्रिय-निग्रह और सर्वस्व-त्याग\n    </h3>\n    <svg viewBox=\"0 0 800 150\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"25\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#c026d3\" stroke-width=\"2\"/>\n      <text x=\"137\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#86198f\">इंद्रिय-निग्रह</text>\n      <text x=\"137\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">षड्विकारों पर नियंत्रण</text>\n      <text x=\"137\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• भूख, प्यास, नींद को आदेश</text>\n      <text x=\"137\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• क्रोध, मोह, लोभ का दमन</text>\n\n      <path d=\"M 250 75 L 285 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"285\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#9333ea\" stroke-width=\"2\"/>\n      <text x=\"397\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#7e22ce\">‘अपना घर’ भूलना</text>\n      <text x=\"397\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">अहंकार का विसर्जन</text>\n      <text x=\"397\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• सांसारिक घर = देह व मोह</text>\n      <text x=\"397\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• ईश्वर का घर = सच्चा धाम</text>\n\n      <path d=\"M 510 75 L 545 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"545\" y=\"20\" width=\"230\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <text x=\"660\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#065f46\">चेन्नमल्लिकार्जुन</text>\n      <text x=\"660\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">जूही के फूल जैसे प्रभु</text>\n      <text x=\"660\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• भीख माँगने की स्थिति</text>\n      <text x=\"660\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• कुत्ता झपट ले = पूर्ण समर्पण</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT पाठ्यपुस्तक अभ्यास: वचनों के साथ</div>\n\n  <!-- c11h-ch14-q1 (वचनों के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch14-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch14-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">वचनों के साथ</span><br>\n        लक्ष्य प्राप्ति में इंद्रियाँ बाधक होती हैं—इसके लिए कवयित्री अक्कमहादेवी ने विभिन्न इंद्रियों और विकारों से क्या-क्या प्रार्थना की है?\n      </div>\n      <div class=\"q-marks\">[4 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>कवयित्री ने ईश्वर-साक्षात्कार के मार्ग में बाधक बनने वाले षड्विकारों और इंद्रियों से निम्नलिखित प्रार्थना की है:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>भूख से:</strong> हे भूख! तू मचलकर मुझे मत सता ताकि मेरा ध्यान देह-पोषण में न भटके।</li>\n        <li><strong>प्यास से:</strong> हे प्यास! तू मुझे तड़पाना बंद कर।</li>\n        <li><strong>नींद से:</strong> हे नींद! तू मुझे प्रमाद और आलस्य में डालकर सताना छोड़ दे।</li>\n        <li><strong>क्रोध और मोह से:</strong> हे क्रोध! तू मेरे भीतर उथल-पुथल मत मचा, और हे मोह! तू अपने माया-पाश के बंधन ढीले कर दे।</li>\n        <li><strong>लोभ और ईर्ष्या से:</strong> हे लोभ! तू मुझे मत ललचा, और हे अहंकार व ईर्ष्या! तुम जलना और जलाना छोड़ दो ताकि मैं शुद्ध अंतःकरण से भगवान शिव की भक्ति कर सकूँ।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">भूख, प्यास और नींद से की गई प्रार्थना का स्पष्ट विवरण</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">क्रोध, मोह, लोभ और अहंकार के शमन की प्रार्थना</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch14-q2 (वचनों के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch14-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch14-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">वचनों के साथ</span><br>\n        ‘हे मेरे जूही के फूल जैसे ईश्वर’—कवयित्री ईश्वर को जूही के फूल जैसा क्यों कहती हैं?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>कवयित्री भगवान शिव (चेन्नमल्लिकार्जुन) को <strong>‘जूही के फूल जैसे ईश्वर’</strong> कहकर संबोधित करती हैं, इसके प्रमुख कारण हैं:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>अत्यंत कोमलता और स्निग्धता:</strong> जूही का फूल अत्यंत कोमल, श्वेत, शांत और सादगीपूर्ण होता है। कवयित्री के लिए ईश्वर कोई भयानक या संहारक सत्ता नहीं, बल्कि असीम करुणा, कोमलता और वात्सल्य के सागर हैं।</li>\n        <li><strong>सुगंध का प्रसार:</strong> जिस प्रकार जूही का छोटा सा पुष्प अपनी भीनी-भीनी सुगंध से पूरे परिवेश को सुवासित कर देता है, उसी प्रकार ईश्वर की उपस्थिति भक्त के संपूर्ण जीवन को प्रेम और दिव्यता से भर देती है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">जूही के फूल की कोमलता, सादगी और स्निग्धता से तुलना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">ईश्वर की सुगंधित एवं कल्याणकारी उपस्थिति का दार्शनिक भाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch14-q3 (वचनों के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch14-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch14-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">वचनों के साथ</span><br>\n        दूसरे वचन में ‘अपना घर’ से क्या तात्पर्य है? इसे भूलने की बात क्यों कही गई है?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p><strong>‘अपना घर’ का तात्पर्य:</strong></p>\n      <p>यहाँ ‘अपना घर’ सांसारिक मोह-माया, पारिवारिक सुख-सुविधाओं, भौतिक देह-अभिमान और सामाजिक मान-प्रतिष्ठा का प्रतीक है।</p>\n      <p><strong>भूलने की बात क्यों कही गई:</strong></p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li>जब तक मनुष्य अपने इस संकीर्ण भौतिक 'घर' (अहंकार और देहासक्ति) से जुड़ा रहता है, तब तक वह परमात्मा के शाश्वत घर (मुक्ति) में प्रवेश नहीं कर सकता।</li>\n        <li>कवयित्री चाहती हैं कि उनका यह सांसारिक 'अहं' पूरी तरह नष्ट हो जाए, वे ऐसी निर्धन और विरक्त हो जाएँ कि उन्हें भीख माँगनी पड़े, और यदि कोई झोली में भीख डाले भी तो कुत्ता उसे झपट ले—ताकि उनके अहंकार का लेशमात्र भी न बचे और वे संपूर्ण रूप से ईश्वर में लीन हो जाएँ।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">\"अपना घर\" को भौतिक देह, परिवार व अहंकार का प्रतीक बताना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पूर्ण ईश्वर-समर्पण हेतु भौतिक बंधनों को भूलने की अनिवार्यता</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch14-q4 (वचनों के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch14-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch14-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">वचनों के साथ</span><br>\n        अक्कमहादेवी के वचनों का दार्शनिक एवं सामाजिक संदेश क्या है?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>12वीं सदी की कन्नड़ संत कवयित्री अक्कमहादेवी के वचनों का संदेश अत्यंत क्रांतिकारी और सार्वकालिक है:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>आंतरिक विकारों पर विजय:</strong> वास्तविक मुक्ति बाहर की दुनिया में नहीं, बल्कि काम, क्रोध, लोभ, मोह, मद और मत्सर जैसे आंतरिक शत्रुओं को वश में करने से मिलती है।</li>\n        <li><strong>स्त्री स्वाधीनता और सामाजिक विद्रोह:</strong> अक्कमहादेवी ने तत्कालीन सामंती पुरुषवादी समाज और राजा कौशिश के राजवैभव को ठुकराकर निर्वस्त्र होकर शिव (चेन्नमल्लिकार्जुन) की साधना की। उनके वचन सिखाते हैं कि आत्मा का कोई लिंग नहीं होता और आत्मा की सर्वोच्च निष्ठा केवल सत्य और परमात्मा के प्रति होती है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">इंद्रिय-निग्रह और वासनाओं से मुक्ति का आध्यात्मिक संदेश</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">स्त्री मुक्ति, निर्भीकता और रूढ़ियों को तोड़ने का सामाजिक आह्वान</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(13)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← पाठ 13</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(15)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#c2410c; color:white; font-weight:700; cursor:pointer;\">अगला पाठ: सबसे खतरनाक →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[15] = "<section class=\"chapter-section\" id=\"c11h-ch15\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#c2410c;\">15</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#c2410c;\">CBSE Class 11 हिंदी कोर &bull; आरोह भाग - 1 (काव्य खंड) &bull; पाठ 15</div>\n      <h2>सबसे खतरनाक (पाश)</h2>\n      <p>NCERT तर्कसंगत (Rationalised) 2026–27 पाठ्यक्रम &bull; संपूर्ण 4 प्रामाणिक प्रश्नोत्तर एवं मार्किंग स्कीम</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #fef2f2, #fee2e2); border:1px solid #fecaca; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#991b1b; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#dc2626\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"8\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"16\" x2=\"12.01\" y2=\"16\"/></svg>\n      संवेदनहीनता और मुर्दा शांति: सबसे खतरनाक स्थिति\n    </h3>\n    <svg viewBox=\"0 0 800 150\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"25\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#eab308\" stroke-width=\"2\"/>\n      <text x=\"137\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#854d0e\">खतरनाक परिस्थितियाँ</text>\n      <text x=\"137\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">शारीरिक कष्ट</text>\n      <text x=\"137\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• मेहनत की लूट, पुलिस की मार</text>\n      <text x=\"137\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• गद्दारी और लोभ की मुट्ठी</text>\n\n      <path d=\"M 250 75 L 285 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"285\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#dc2626\" stroke-width=\"2\"/>\n      <text x=\"397\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#991b1b\">सबसे खतरनाक क्या है?</text>\n      <text x=\"397\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">मुर्दा शांति और संवेदनहीनता</text>\n      <text x=\"397\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• सपनों का मर जाना</text>\n      <text x=\"397\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• अन्याय पर तड़प न होना</text>\n\n      <path d=\"M 510 75 L 545 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"545\" y=\"20\" width=\"230\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#475569\" stroke-width=\"2\"/>\n      <text x=\"660\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1e293b\">पथराई हुई आँख</text>\n      <text x=\"660\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">जड़ता का प्रतीक</text>\n      <text x=\"660\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• जो सब कुछ देखती है बर्फ जैसी</text>\n      <text x=\"660\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• जिसकी नज़र में कोई चिंगारी नहीं</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT पाठ्यपुस्तक अभ्यास: कविता के साथ</div>\n\n  <!-- c11h-ch15-q1 (कविता के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch15-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch15-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">कविता के साथ</span><br>\n        कवि ने किस बात को ‘सबसे खतरनाक’ माना है और क्यों?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>कवि अवतार सिंह संधू ‘पाश’ ने <strong>हमारे सपनों का मर जाना</strong> और <strong>मनुष्य का मुर्दा शांति से भर जाना</strong> ही सबसे खतरनाक माना है:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>कारण:</strong> शारीरिक यातना, पुलिस की मार, गद्दारी या धन की लूट से केवल शरीर या संपत्ति को क्षति पहुँचती है। जब तक मनुष्य के भीतर विद्रोह की चिंगारी और बेहतर भविष्य के सपने जीवित हैं, तब तक क्रांति संभव है।</li>\n        <li><strong>संवेदनहीनता ही वास्तविक मृत्यु है:</strong> परंतु जब मनुष्य अन्याय देखकर भी विचलित होना बंद कर देता है, उसकी तड़प समाप्त हो जाती है और वह चुपचाप अत्याचार सहने की जड़ता (मुर्दा शांति) का शिकार हो जाता है, तो समाज की आत्मा मर जाती है। ऐसी संवेदनहीन जीवित लाशों का समाज कभी प्रगति नहीं कर सकता।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">सपनों के मर जाने और मुर्दा शांति को सबसे खतरनाक घोषित करना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">संवेदनहीनता और विद्रोह की भावना समाप्त होने को आत्मा की मृत्यु बताना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch15-q2 (कविता के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch15-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch15-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">कविता के साथ</span><br>\n        कवि के अनुसार किन परिस्थितियों में जीना ‘खतरनाक’ तो होता है, पर ‘सबसे खतरनाक’ नहीं?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>कवि ने जीवन की कई विषम परिस्थितियों को 'खतरनाक' माना है, परंतु वे 'सबसे खतरनाक' नहीं हैं:</p>\n      <ol style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>मेहनत की लूट:</strong> मज़दूर और किसान की गाढ़ी कमाई का किसी पूँजीपति द्वारा लूटा जाना खतरनाक है, पर सबसे खतरनाक नहीं।</li>\n        <li><strong>पुलिस की मार और रिश्वतखोरी:</strong> पुलिस की लाठियाँ खाना या भ्रष्ट व्यवस्था में मुट्ठी भर रिश्वत के लोभ में पकड़ा जाना खतरनाक है।</li>\n        <li><strong>गद्दारी और छल:</strong> मित्रों या सहयोगियों द्वारा पीठ में छुरा घोंपना या कपट करना खतरनाक है।</li>\n      </ol>\n      <p>ये सब बाह्य आघात हैं जिनसे मनुष्य उबर सकता है, परंतु आंतरिक चेतना का मर जाना ही चरम खतरा है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">मेहनत की लूट और पुलिस की मार को खतरनाक बताना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गद्दारी और लोभ को केवल बाहरी संकट मानकर अंतर स्पष्ट करना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch15-q3 (कविता के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch15-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch15-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">कविता के साथ</span><br>\n        ‘सबसे खतरनाक वह आँख होती है, जो सब कुछ देखती हुई भी जमी बर्फ होती है’—इस पंक्ति का भावार्थ स्पष्ट कीजिए।\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>इस मर्मभेदी पंक्ति का भावार्थ:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>जमी बर्फ जैसी आँख:</strong> आँख मनुष्य के अंतर्मन और संवेदनशीलता का दर्पण होती है। 'जमी बर्फ' का अर्थ है—पूर्णतः संवेदनहीन, भावशून्य, ठंडी और निस्तेज दृष्टि।</li>\n        <li><strong>अन्याय पर मूक दर्शक बने रहना:</strong> ऐसी आँख अपने चारों ओर समाज में हो रहे शोषण, भ्रष्टाचार, अत्याचार और हत्याओं को खुली आँखों से देखती है, परंतु उसके भीतर न तो कोई क्रोध की ज्वाला धधकती है और न ही करुणा का कोई आँसू बहता है। वह सब कुछ एक जड़ पत्थर की भाँति देखती रहती है। कवि ऐसी संवेदनहीन और मूक दर्शक बनी दृष्टि को समाज के लिए सबसे घातक मानता है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">\"जमी बर्फ\" का अर्थ: संवेदनशून्य, निष्प्राण और भावहीन दृष्टि</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अन्याय देखकर भी प्रतिक्रिया न करने वाली मूक दर्शक आँख को सर्वाधिक घातक सिद्ध करना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch15-q4 (कविता के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch15-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch15-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">कविता के साथ</span><br>\n        ‘सबसे खतरनाक वह घड़ी होती है, जो आपकी कलाई पर चलती हुई भी आपकी निगाह में रुकी होती है’—का आशय स्पष्ट कीजिए।\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>इस अद्भुत प्रतीकात्मक पंक्ति का आशय:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>घड़ी की भौतिक गति:</strong> कलाई की घड़ी अपनी सुइयों के साथ टिक-टिक करती हुई समय को लगातार आगे बढ़ा रही है।</li>\n        <li><strong>मानसिक ठहराव (जड़ता):</strong> परंतु मनुष्य की निगाह और चेतना में वह पूरी तरह 'रुकी हुई' है। इसका अर्थ है कि मनुष्य एक बंधी-बंधाई, यांत्रिक, उबाऊ दिनचर्या (घर से दफ़्तर और दफ़्तर से घर) में फँस चुका है। वह समय के बदलाव, समाज की क्रांतियों और जीवन के नवीन मूल्यों के प्रति पूरी तरह उदासीन हो चुका है। ऐसा यांत्रिक और लक्ष्यविहीन जीवन घोर त्रासदी है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">कलाई पर घड़ी का भौतिक रूप से चलते रहना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मानसिक रूप से जीवन की दिनचर्या में जड़, यांत्रिक और निस्तेज हो जाना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(14)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← पाठ 14</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(16)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#c2410c; color:white; font-weight:700; cursor:pointer;\">अगला पाठ: आओ मिलकर बचाएँ →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[16] = "<section class=\"chapter-section\" id=\"c11h-ch16\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#c2410c;\">16</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#c2410c;\">CBSE Class 11 हिंदी कोर &bull; आरोह भाग - 1 (काव्य खंड) &bull; पाठ 16</div>\n      <h2>आओ, मिलकर बचाएँ (निर्मला पुतुल)</h2>\n      <p>NCERT तर्कसंगत (Rationalised) 2026–27 पाठ्यक्रम &bull; संपूर्ण 4 प्रामाणिक प्रश्नोत्तर एवं मार्किंग स्कीम</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #f0fdf4, #dcfce7); border:1px solid #bbf7d0; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#14532d; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"2\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg>\n      संथाली आदिवासी संस्कृति और प्राकृतिक संपदा का संरक्षण\n    </h3>\n    <svg viewBox=\"0 0 800 150\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"25\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#16a34a\" stroke-width=\"2\"/>\n      <text x=\"137\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#14532d\">माटी का रंग</text>\n      <text x=\"137\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">संथाली पहचान</text>\n      <text x=\"137\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• भोलापन, अक्खड़पन, जुझारूपन</text>\n      <text x=\"137\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• तीर-धनुष, कुल्हाड़ी की धार</text>\n\n      <path d=\"M 250 75 L 285 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"285\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#dc2626\" stroke-width=\"2\"/>\n      <text x=\"397\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#991b1b\">शहरी सभ्यता का ख़तरा</text>\n      <text x=\"397\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">नग्नता और जड़ता</text>\n      <text x=\"397\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• जंगलों का अंधाधुंध कटना</text>\n      <text x=\"397\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• शहरी बनावटीपन व ठंडी दिनचर्या</text>\n\n      <path d=\"M 510 75 L 545 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"545\" y=\"20\" width=\"230\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n      <text x=\"660\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#0369a1\">उम्मीद और विश्वास</text>\n      <text x=\"660\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">सामूहिक संकल्प</text>\n      <text x=\"660\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• \"इस अविश्वास भरे दौर में\"</text>\n      <text x=\"660\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• थोड़ा सा विश्वास, थोड़ी सी उम्मीद</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT पाठ्यपुस्तक अभ्यास: कविता के साथ</div>\n\n  <!-- c11h-ch16-q1 (कविता के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch16-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch16-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">कविता के साथ</span><br>\n        कवयित्री निर्मला पुतुल ने अपनी बस्तियों को शहर की किस आबोहवा (जलवायु) से बचाने का आह्वान किया है?\n      </div>\n      <div class=\"q-marks\">[4 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>कवयित्री ने अपनी संथाली आदिवासी बस्तियों को आधुनिक शहरी सभ्यता के निम्नलिखित विनाशकारी प्रभावों से बचाने का आह्वान किया है:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>शारीरिक व सांस्कृतिक नग्नता:</strong> शहरी सभ्यता प्रकृति और संस्कृति को निर्वस्त्र (नंगा) कर रही है—पेड़ काटे जा रहे हैं और पहाड़ नंगे हो रहे हैं। साथ ही आधुनिकता के नाम पर सांस्कृतिक मर्यादाओं का पतन हो रहा है।</li>\n        <li><strong>संवेदनहीनता एवं आलस्य (ठंडापन):</strong> नगरों की दिनचर्या में मशीनी व्यस्तता और आत्मीयता का अभाव (ठंडापन) है। कवयित्री चाहती हैं कि आदिवासियों का उत्साह, उमंग और मन का हरापन शहरों की इस ठंडी संवेदनहीनता की भेंट न चढ़े।</li>\n        <li><strong>हड्डियों तक का काँपना:</strong> बस्तियों को शहरों के प्रदूषण, शोषण और अनैतिक विकृतियों से बचाकर उनकी प्राकृतिक स्वच्छता को सुरक्षित रखना आवश्यक है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">जंगलों के कटने से उत्पन्न प्राकृतिक नग्नता का संकट</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शहरी संवेदनहीनता, बनावटीपन और मानसिक ठंडेपन से बचाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आदिवासी बस्तियों को शोषण और प्रदूषण से मुक्त रखने का संकल्प</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch16-q2 (कविता के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch16-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch16-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">कविता के साथ</span><br>\n        ‘माटी का रंग’ बचाने से क्या तात्पर्य है?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p><strong>‘माटी का रंग’</strong> बचाने से कवयित्री का तात्पर्य संथाली आदिवासी समाज की <strong>मौलिक सांस्कृतिक पहचान, सादगी और मिट्टी से जुड़े जीवन-मूल्यों को अक्षुण्ण बनाए रखने</strong> से है:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li>संथाल परगना के लोगों का भोलापन, अक्खड़पन, स्वाभिमान और जुझारूपन उनकी मिट्टी की असली पहचान है।</li>\n        <li>उनकी पारंपरिक भाषा (संथाली), उनके लोकगीतों की मधुर तान, मांदर और नगाड़ों की थाप, नदियों की निर्मलता और पहाड़ों की शांति ही उनकी माटी का असली रंग है।</li>\n        <li>शहरी चमक-दमक के प्रभाव में आकर आदिवासी अपनी इस पैतृक विरासत को न भूलें, यही 'माटी का रंग' बचाना है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">माटी के रंग को आदिवासी अस्मिता एवं मौलिक संस्कृति का प्रतीक बताना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">लोकगीत, संथाली भाषा, नदियों की निर्मलता और सादगी के संरक्षण का संकल्प</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch16-q3 (कविता के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch16-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch16-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">कविता के साथ</span><br>\n        कवयित्री संथाली जीवन की किन-किन विशिष्ट पहचानों और प्राकृतिक उपादानों को बचाना चाहती हैं?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>कवयित्री निम्नलिखित प्राकृतिक संपदा और सांस्कृतिक धरोहरों को सहेजने का आह्वान करती हैं:</p>\n      <ol style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>प्राकृतिक उपादान:</strong> नाचने के लिए खुला आँगन, गाने के लिए मधुर लोकगीत, हँसने के लिए खिलखिलाहट, रोने के लिए थोड़ा सा एकांत, बच्चों के लिए खेलने का मैदान, पशुओं के लिए हरी-हरी घास और बूढ़ों के लिए पहाड़ों की शांति।</li>\n        <li><strong>संस्कृति और पारंपरिक शस्त्र:</strong> शिकार और स्वावलंबन के प्रतीक—तीर-धनुष की नोक, कुल्हाड़ी की तीखी धार, ताज़ा जंगल की ताज़ी हवा और पवित्र नदियों का कलकल बहता जल।</li>\n      </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">आँगन, मैदान, हरी घास और पहाड़ों की शांति का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तीर-धनुष, कुल्हाड़ी और जंगल-नदियों के संरक्षण की महत्ता</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch16-q4 (कविता के साथ) -->\n  <div class=\"q-card\" id=\"c11h-ch16-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch16-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">कविता के साथ</span><br>\n        ‘इस अविश्वास भरे दौर में भी थोड़ा सा विश्वास, थोड़ी सी उम्मीद, थोड़े से सपने बचाना’—कवयित्री का यह आशावादी संदेश आज के संदर्भ में क्यों प्रासंगिक है?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>यह अंतिम अंश घोर निराशा के बीच भी <strong>अदम्य आशावाद और जिजीविषा</strong> का संदेश देता है:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>आज का अविश्वास भरा दौर:</strong> समकालीन समाज में स्वार्थ, धोखा, धोखाधड़ी और भौतिक अंधी दौड़ के कारण लोग एक-दूसरे पर विश्वास खो चुके हैं। पर्यावरण विनाश और मानवीय मूल्यों के पतन ने निराशा का माहौल बना दिया है।</li>\n        <li><strong>आशा की प्रासंगिकता:</strong> ऐसे संकटपूर्ण समय में भी यदि मनुष्य के भीतर थोड़ा सा विश्वास, आने वाले कल के लिए थोड़ी सी उम्मीद और एक सुंदर मानवीय संसार के कुछ सपने बचे रहें, तो पूरी मानवता और प्रकृति को विनाश से बचाया जा सकता है। सामूहिक संकल्प से ही संस्कृति और पृथ्वी की रक्षा संभव है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">आधुनिक उपभोक्तावादी युग में बढ़ते अविश्वास और स्वार्थ का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">थोड़े से विश्वास और सामूहिक संकल्प द्वारा मानवता को बचाने की प्रासंगिकता</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(15)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← पाठ 15</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(17)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#c2410c; color:white; font-weight:700; cursor:pointer;\">अगला पाठ: भारतीय गायिकाओं में बेजोड़: लता मंगेशकर →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[17] = "<section class=\"chapter-section\" id=\"c11h-ch17\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#c2410c;\">17</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#c2410c;\">CBSE Class 11 हिंदी कोर &bull; वितान भाग - 1 &bull; पाठ 17</div>\n      <h2>भारतीय गायिकाओं में बेजोड़: लता मंगेशकर (कुमार गंधर्व)</h2>\n      <p>NCERT तर्कसंगत (Rationalised) 2026–27 पाठ्यक्रम &bull; संपूर्ण 5 प्रामाणिक प्रश्नोत्तर एवं मार्किंग स्कीम</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #fffbeb, #fef3c7); border:1px solid #fde68a; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#92400e; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#d97706\" stroke-width=\"2\"><path d=\"M9 18V5l12-2v13\"/><circle cx=\"6\" cy=\"18\" r=\"3\"/><circle cx=\"18\" cy=\"16\" r=\"3\"/></svg>\n      लता की गायकी का रहस्य: ‘गानपन’, नादमय उच्चार और स्वर की निर्मलता\n    </h3>\n    <svg viewBox=\"0 0 800 150\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"25\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d97706\" stroke-width=\"2\"/>\n      <text x=\"137\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#92400e\">गानपन (Gaanpan)</text>\n      <text x=\"137\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">श्रोता को मंत्रमुग्ध करना</text>\n      <text x=\"137\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• आम आदमी को झूमने पर विवश</text>\n      <text x=\"137\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• जैसे मनुष्यता = मनुष्य का लक्षण</text>\n\n      <path d=\"M 250 75 L 285 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"285\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#c2410c\" stroke-width=\"2\"/>\n      <text x=\"397\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#9a3412\">नादमय उच्चार</text>\n      <text x=\"397\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">स्वरों का विलीन होना</text>\n      <text x=\"397\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• दो शब्दों का कोमल अंतर</text>\n      <text x=\"397\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• एक दूसरे में घुल-मिल जाना</text>\n\n      <path d=\"M 510 75 L 545 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"545\" y=\"20\" width=\"230\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <text x=\"660\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#065f46\">चित्रपट संगीत क्रांति</text>\n      <text x=\"660\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">शास्त्रीय व सुगम का सेतु</text>\n      <text x=\"660\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• आम जनता के कान सुरीले किए</text>\n      <text x=\"660\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• नूराँ जहाँ की मादकता + अपनी निर्मलता</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT पाठ्यपुस्तक अभ्यास: विचार एवं अभ्यास</div>\n\n  <!-- c11h-ch17-q1 (विचार एवं अभ्यास) -->\n  <div class=\"q-card\" id=\"c11h-ch17-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch17-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">विचार एवं अभ्यास</span><br>\n        लेखक कुमार गंधर्व ने लता मंगेशकर की गायकी की किन-किन मुख्य विशेषताओं को उजागर किया है?\n      </div>\n      <div class=\"q-marks\">[4 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>प्रसिद्ध शास्त्रीय गायक कुमार गंधर्व ने लता जी की गायकी की निम्नलिखित अप्रतिम विशेषताओं का विश्लेषण किया है:</p>\n      <ol style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>गानपन (Gaanpan):</strong> जिस प्रकार मनुष्य का लक्षण 'मनुष्यता' है, उसी प्रकार संगीत का प्राण 'गानपन' है। गानपन का अर्थ है गाने की वह रंजकता और मिठास, जो साधारण से साधारण श्रोता को भी भाव-विभोर होकर झूमने पर विवश कर दे। लता के प्रत्येक गीत में यह शत-प्रतिशत मौजूद है।</li>\n        <li><strong>स्वरों की निर्मलता:</strong> पूर्ववर्ती गायिका नूरजहाँ के गायन में जहाँ एक मादक उत्तान था, वहीं लता के स्वरों में अद्भुत कोमलता, पवित्रता और पारदर्शी निर्मलता है।</li>\n        <li><strong>नादमय उच्चार:</strong> लता जी के गीत के किन्हीं दो शब्दों के बीच का अंतर स्वरों के सुंदर आलाप द्वारा इस प्रकार भर दिया जाता है कि दोनों शब्द एक-दूसरे में विलीन होते प्रतीत होते हैं।</li>\n        <li><strong>उच्च स्वर (तारसप्तक) में सहज गायकी:</strong> कठिन से कठिन और ऊँचे सुरों को वे बिना किसी तनाव या चीख के अत्यंत स्वाभाविक और सहज भाव से गा लेती हैं।</li>\n      </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">गानपन (रंजकता एवं मिठास) का विश्लेषण</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">स्वरों की अद्वितीय निर्मलता और पवित्रता का उल्लेख</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नादमय उच्चार: दो शब्दों का एक-दूसरे में घुल-मिल जाना</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तारसप्तक (ऊँचे सुरों) में सहज गायकी की क्षमता</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch17-q2 (विचार एवं अभ्यास) -->\n  <div class=\"q-card\" id=\"c11h-ch17-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch17-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">विचार एवं अभ्यास</span><br>\n        ‘लता ने करुण रस के गानों के साथ उतना न्याय नहीं किया है, जितना शृंगार परक गानों के साथ’—लेखक के इस विचार से आप कहाँ तक सहमत हैं?\n      </div>\n      <div class=\"q-marks\">[4 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p><strong>समीक्षात्मक उत्तर:</strong></p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>लेखक का दृष्टिकोण:</strong> कुमार गंधर्व का मानना है कि लता जी की स्वाभाविक आवाज़ में एक कोमल, उत्कट और चुलबुलापन है, जिसके कारण वे शृंगार, प्रेम और द्रुत लय के गीतों को बहुत प्रभावशाली ढंग से गाती हैं, जबकि करुण रस में वह गहराई और उदासी पूरी तरह नहीं उभर पाती।</li>\n        <li><strong>असहमति एवं यथार्थ:</strong> हम लेखक के इस विचार से <em>पूर्णतः सहमत नहीं हैं</em>। लता जी ने करुण रस के ऐसे कालजयी गीत गाए हैं जिन्होंने पूरे राष्ट्र की आँखों को नम कर दिया। इसका सबसे ज्वलंत उदाहरण कवि प्रदीप द्वारा रचित अमर गीत— <strong>“ऐ मेरे वतन के लोगो, ज़रा आँख में भर लो पानी”</strong> है, जिसे सुनकर तत्कालीन प्रधानमंत्री पंडित जवाहरलाल नेहरू की आँखों से भी अश्रु छलक पड़े थे। इसके अतिरिक्त <em>“ओ बाबुल प्यारे”</em> और <em>“अल्ला तेरो नाम”</em> जैसे करुण व शांत रस के गीतों में उनकी भावुकता बेमिसाल है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">लेखक के व्यक्तिगत मत (शृंगार में अधिक उत्कटता) का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">\"ऐ मेरे वतन के लोगो\" आदि गीतों का उदाहरण देकर असहमति का प्रामाणिक तर्क</span><span class=\"marking-marks\">2.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch17-q3 (विचार एवं अभ्यास) -->\n  <div class=\"q-card\" id=\"c11h-ch17-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch17-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">विचार एवं अभ्यास</span><br>\n        ‘गानपन’ से आप क्या समझते हैं? लता के गानों में यह किस प्रकार प्रकट होता है?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p><strong>‘गानपन’ का अर्थ:</strong></p>\n      <p>‘गानपन’ संगीत का वह मूल तत्व है जो गीत को रसीला, कर्णप्रिय और सम्मोहक बनाता है। जिस प्रकार किसी व्यक्ति में मानवीय गुणों के होने से 'मनुष्यता' सिद्ध होती है, उसी प्रकार शास्त्रीय नियमों के सही होने के साथ-साथ जब संगीत आम आदमी के दिल को छू ले और उसके कानों में अमृत घोल दे, तो उसे 'गानपन' कहा जाता है।</p>\n      <p><strong>लता के गानों में प्रकटीकरण:</strong></p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li>लता के गाते ही एक आम रिक्शेवाला, गृहिणी या अनपढ़ किसान भी अनजाने में सुर में सीटी बजाने या गुनगुनाने लगता है।</li>\n        <li>उनके उच्चारण की स्पष्टता, शब्दों की कोमल अदायगी और सुरों का सम्मोहन मिलकर ऐसा गानपन रचते हैं कि श्रोता मुग्ध होकर झूमने लगता है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">गानपन की स्पष्ट परिभाषा (संगीत का रसीलापन व सम्मोहन)</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">लता के गीतों में आम श्रोता को मंत्रमुग्ध करने वाले गानपन का अंकन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch17-q4 (विचार एवं अभ्यास) -->\n  <div class=\"q-card\" id=\"c11h-ch17-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch17-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">विचार एवं अभ्यास</span><br>\n        लेखक के अनुसार शास्त्रीय संगीत और चित्रपट (फ़िल्मी) संगीत में क्या मूलभूत अंतर और संबंध है?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>कुमार गंधर्व ने दोनों संगीत शैलियों के अंतर और संबंध का अत्यंत संतुलित मूल्यांकन किया है:</p>\n      <table style=\"width:100%; border-collapse:collapse; margin:12px 0; font-size:0.95rem;\">\n        <thead>\n          <tr style=\"background:#f1f5f9; text-align:left;\">\n            <th style=\"padding:10px; border:1px solid #cbd5e1;\">शास्त्रीय संगीत</th>\n            <th style=\"padding:10px; border:1px solid #cbd5e1;\">चित्रपट (फ़िल्मी) संगीत</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td style=\"padding:10px; border:1px solid #cbd5e1;\">गंभीरता, ताल-सुर की शुद्धता और कड़े शास्त्रीय नियमों पर आधारित।</td>\n            <td style=\"padding:10px; border:1px solid #cbd5e1;\">लचीलापन, चपलता, त्वरित प्रभाव और रंजकता (मनोरंजन) मुख्य उद्देश्य।</td>\n          </tr>\n          <tr>\n            <td style=\"padding:10px; border:1px solid #cbd5e1;\">इसमें तीन घंटे की महफ़िल में राग का धीमा विस्तार होता है।</td>\n            <td style=\"padding:10px; border:1px solid #cbd5e1;\">साढ़े तीन मिनट के सीमित समय में संपूर्ण भाव और रस का प्रकटीकरण।</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>परस्पर संबंध:</strong> चित्रपट संगीत का आधार भी कहीं न कहीं शास्त्रीय राग और लोकधुनें ही हैं। लता जी ने चित्रपट संगीत के माध्यम से आम जनता के कानों को सुरीला बनाकर शास्त्रीय संगीत की समझ का मार्ग भी प्रशस्त किया है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">शास्त्रीय संगीत की गंभीरता और नियमों का उल्लेख</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">चित्रपट संगीत की चपलता, रंजकता और साढ़े तीन मिनट की सीमा</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दोनों के आपसी पूरक संबंध का निरूपण</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch17-q5 (विचार एवं अभ्यास) -->\n  <div class=\"q-card\" id=\"c11h-ch17-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch17-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">विचार एवं अभ्यास</span><br>\n        संगीत के क्षेत्र में लता मंगेशकर का स्थान अद्वितीय और बेजोड़ क्यों माना गया है?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>लता जी का स्थान संगीत के इतिहास में अद्वितीय है, इसके प्रमुख कारण:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>शताब्दी की अप्रतिम गायिका:</strong> लेखक का मानना है कि शताब्दियों में कोई एक कलाकार ऐसा जन्म लेता है। जिस प्रकार क्रिकेट में सचिन या अभिनय में दिलीप कुमार, उसी प्रकार भारतीय गायन में लता का कोई सानी नहीं है।</li>\n        <li><strong>विशाल दायरा और विविधता:</strong> उन्होंने शास्त्रीय रागों से लेकर पहाड़ी लोकगीतों, कव्वालियों, ग़ज़लों, भजनों और पश्चिमी धुनों तक हज़ारों गीतों को अपनी अद्वितीय आवाज़ से अमर बना दिया।</li>\n        <li><strong>देश की सीमाएँ लांघने वाला जादू:</strong> उनका संगीत केवल भारत ही नहीं, बल्कि पाकिस्तान, बांग्लादेश और सात समंदर पार रहने वाले विदेशियों को भी मंत्रमुग्ध कर देता है। वे साक्षात् सरस्वती का अवतार मानी गई हैं।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">शताब्दियों में एक बार जन्म लेने वाली प्रतिभा का उल्लेख</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हज़ारों गीतों और विविध शैलियों में महारत</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अंतरराष्ट्रीय स्तर पर भारतीय संगीत की प्रतिष्ठा स्थापित करना</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(16)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← पाठ 16</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(18)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#c2410c; color:white; font-weight:700; cursor:pointer;\">अगला पाठ: राजस्थान की रजत बूँदें →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[18] = "<section class=\"chapter-section\" id=\"c11h-ch18\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#c2410c;\">18</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#c2410c;\">CBSE Class 11 हिंदी कोर &bull; वितान भाग - 1 &bull; पाठ 18</div>\n      <h2>राजस्थान की रजत बूँदें (अनुपम मिश्र)</h2>\n      <p>NCERT तर्कसंगत (Rationalised) 2026–27 पाठ्यक्रम &bull; संपूर्ण 5 प्रामाणिक प्रश्नोत्तर एवं मार्किंग स्कीम</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #fefce8, #fef08a); border:1px solid #fde047; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#854d0e; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#ca8a04\" stroke-width=\"2\"><path d=\"M12 2.69l5.66 5.66a8 8 0 1 1-11.31 0z\"/></svg>\n      रेगिस्तान में जल का त्रिविध रूप एवं कुंई निर्माण का विज्ञान\n    </h3>\n    <svg viewBox=\"0 0 800 150\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"25\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#ca8a04\" stroke-width=\"2\"/>\n      <text x=\"137\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#854d0e\">पार्लर पानी</text>\n      <text x=\"137\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">धरातलीय जल</text>\n      <text x=\"137\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• वर्षा का बहता हुआ पानी</text>\n      <text x=\"137\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• तालाबों, पोखरों में संचित</text>\n\n      <path d=\"M 250 75 L 285 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"285\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n      <text x=\"397\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#0369a1\">पाताल पानी</text>\n      <text x=\"397\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">भूजल</text>\n      <text x=\"397\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• गहरा भूजल स्तर</text>\n      <text x=\"397\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• राजस्थान में प्रायः खारा पानी</text>\n\n      <path d=\"M 510 75 L 545 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"545\" y=\"20\" width=\"230\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <text x=\"660\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#065f46\">रेजाणी पानी (अमृत)</text>\n      <text x=\"660\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">खड़िया पट्टी के ऊपर</text>\n      <text x=\"660\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• कुंई में बूँद-बूँद रिसने वाला</text>\n      <text x=\"660\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• मीठा, शुद्ध व जीवनदाता जल</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT पाठ्यपुस्तक अभ्यास: विचार एवं अभ्यास</div>\n\n  <!-- c11h-ch18-q1 (विचार एवं अभ्यास) -->\n  <div class=\"q-card\" id=\"c11h-ch18-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch18-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">विचार एवं अभ्यास</span><br>\n        राजस्थान में कुंई किसे कहते हैं? इसकी गहराई और व्यास तथा सामान्य कुएँ की गहराई और व्यास में क्या अंतर होता है?\n      </div>\n      <div class=\"q-marks\">[4 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p><strong>कुंई की परिभाषा:</strong></p>\n      <p>राजस्थान के रेतीले इलाकों में वर्षा के नमी रूपी जल को बूँद-बूँद सहेजने के लिए बनाए गए अत्यंत संकरे और गहरे गड्ढे को <strong>‘कुंई’</strong> (स्त्रीलिंग रूप) कहा जाता है।</p>\n      <p><strong>कुंई और सामान्य कुएँ में अंतर:</strong></p>\n      <table style=\"width:100%; border-collapse:collapse; margin:12px 0; font-size:0.95rem;\">\n        <thead>\n          <tr style=\"background:#f1f5f9; text-align:left;\">\n            <th style=\"padding:10px; border:1px solid #cbd5e1;\">विशेषता</th>\n            <th style=\"padding:10px; border:1px solid #cbd5e1;\">सामान्य कुआँ</th>\n            <th style=\"padding:10px; border:1px solid #cbd5e1;\">कुंई</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td style=\"padding:10px; border:1px solid #cbd5e1;\"><strong>व्यास (चौड़ाई)</strong></td>\n            <td style=\"padding:10px; border:1px solid #cbd5e1;\">बहुत चौड़ा (15 से 20 फीट या अधिक)।</td>\n            <td style=\"padding:10px; border:1px solid #cbd5e1;\">अत्यंत संकरा (मात्र 4 से 5 हाथ, लगभग 3-4 फीट)।</td>\n          </tr>\n          <tr>\n            <td style=\"padding:10px; border:1px solid #cbd5e1;\"><strong>जल का स्रोत</strong></td>\n            <td style=\"padding:10px; border:1px solid #cbd5e1;\">भूजल (पाताल पानी) जो राजस्थान में प्रायः खारा होता है।</td>\n            <td style=\"padding:10px; border:1px solid #cbd5e1;\">रेत में समाई वर्षा की नमी, जो खड़िया पट्टी पर रुककर रिसती है।</td>\n          </tr>\n          <tr>\n            <td style=\"padding:10px; border:1px solid #cbd5e1;\"><strong>गहराई</strong></td>\n            <td style=\"padding:10px; border:1px solid #cbd5e1;\">100 से 200 फीट तक गहरी।</td>\n            <td style=\"padding:10px; border:1px solid #cbd5e1;\">30 से 60 हाथ (लगभग 45 से 65 फीट) गहरी।</td>\n          </tr>\n        </tbody>\n      </table>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">कुंई की प्रामाणिक परिभाषा</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">व्यास (चौड़ाई) का तुलनात्मक अंतर</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">जल स्रोत (भूजल बनाम खड़िया पट्टी पर संचित नमी) का अंतर</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गहराई और उपयोगिता का विश्लेषण</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch18-q2 (विचार एवं अभ्यास) -->\n  <div class=\"q-card\" id=\"c11h-ch18-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch18-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">विचार एवं अभ्यास</span><br>\n        ‘रेजाणी पानी’ किसे कहते हैं? पार्लर पानी, पाताल पानी और रेजाणी पानी में क्या अंतर है?\n      </div>\n      <div class=\"q-marks\">[4 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>अनुपम मिश्र ने राजस्थान में मिलने वाले जल को तीन स्पष्ट रूपों में वर्गीकृत किया है:</p>\n      <ol style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>पार्लर पानी:</strong> यह धरातल पर सीधे वर्षा से मिलने वाला जल है, जो नदी, नालों, तालाबों और पोखरों में बहता और एकत्र होता है।</li>\n        <li><strong>पाताल पानी:</strong> यह वह भूजल है जो रिसकर बहुत गहराई में चला जाता है और कुओं के माध्यम से निकाला जाता है। राजस्थान में यह पानी प्रायः बहुत खारा और पीने अयोग्य होता है।</li>\n        <li><strong>रेजाणी पानी (Rejani Pani):</strong> यह पार्लर पानी और पाताल पानी के बीच का अनोखा जल रूप है। वर्षा का जो पानी रेत में समा जाता है, परंतु नीचे 30-40 हाथ की गहराई पर मौजूद <strong>खड़िया पत्थर की पट्टी</strong> के कारण खारे पाताल पानी में नहीं मिल पाता, वह रेत के कणों में नमी बनकर ठहर जाता है। कुंई खोदने पर यही नमी बूँद-बूँद रिसकर एकत्र होती है। यह अमृत के समान मीठा, शीतल और शुद्ध पेय जल होता है।</li>\n      </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">पार्लर पानी (धरातलीय जल) का स्पष्टीकरण</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पाताल पानी (गहरा भूजल) का स्पष्टीकरण</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">रेजाणी पानी की परिभाषा और खड़िया पट्टी की भूमिका</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch18-q3 (विचार एवं अभ्यास) -->\n  <div class=\"q-card\" id=\"c11h-ch18-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch18-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">विचार एवं अभ्यास</span><br>\n        कुंई निर्माण में ‘चेलवांजी’ (चेजो) की भूमिका और उनके सामाजिक सम्मान का वर्णन कीजिए।\n      </div>\n      <div class=\"q-marks\">[4 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p><strong>चेलवांजी (चेजो) की भूमिका:</strong></p>\n      <p>चेलवांजी कुंई खोदने और उसकी चिनाई करने वाले अत्यंत सिद्धहस्त और कुशल कारीगर होते हैं। 30 से 60 हाथ गहरे संकरे गड्ढे में, जहाँ साँस लेना भी दूभर होता है और ऊपर से गर्म हवा व रेत गिरने का ख़तरा रहता है, चेलवांजी <em>‘बसौली’</em> (लोहे की छोटी कुदाल) से खुदाई करते हैं और ऊपर से सिर पर धातु का टोप पहनते हैं। वे ईंटों या <strong>खींप की रस्सी</strong> से कुंई की दीवार को नीचे से ऊपर तक ऐसा सुदृढ़ बाँधते हैं कि रेत धँसने न पाए।</p>\n      <p><strong>सामाजिक सम्मान की परंपरा:</strong></p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li>कुंई का काम पूरा होने पर विशेष उत्सव और भोज होता था। चेलवांजी को पगड़ी, धोती और बहुमूल्य उपहार दिए जाते थे।</li>\n        <li>यही नहीं, वर्ष भर के तीज-त्योहारों, विवाह और फ़सल कटाई के समय भी खलिहान में चेलवांजी के नाम का अनाज निकाला जाता था। यद्यपि आज यह प्रथा मजदूरी तक सीमित हो गई है, परंतु पहले समाज उन्हें देवतुल्य सम्मान देता था।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">चेलवांजी द्वारा बसौली से खुदाई और खींप की रस्सी से चिनाई का हुनर</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कुंई निर्माण के उपरांत सामाजिक उत्सव, उपहार और फ़सल में हिस्सा देने की परंपरा</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch18-q4 (विचार एवं अभ्यास) -->\n  <div class=\"q-card\" id=\"c11h-ch18-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch18-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">विचार एवं अभ्यास</span><br>\n        कुंई पर ग्राम समाज के सार्वजनिक और निजी अधिकार का संतुलन किस प्रकार बना रहता है?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>राजस्थान का समाज कुंई के संदर्भ में निजी और सार्वजनिक अधिकारों का अद्भुत लोकतांत्रिक संतुलन साधता है:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>निजी संपत्ति:</strong> प्रत्येक परिवार अपने घर के उपयोग के लिए अपनी व्यक्तिगत कुंई खुदवाता है और उस पर ताला लगाने का अधिकार रखता है।</li>\n        <li><strong>सार्वजनिक ज़मीन और नियंत्रण:</strong> कुंइयाँ जिस ज़मीन पर खोदी जाती हैं, वह ग्राम समाज की <strong>सार्वजनिक (शामलात) भूमि</strong> होती है। उस क्षेत्र में रेत के नीचे नमी की एक सीमित मात्रा होती है। यदि हर कोई अनगिनत कुंइयाँ खोदने लगेगा, तो नमी बँट जाएगी और किसी भी कुंई में पर्याप्त पानी नहीं आ पाएगा।</li>\n        <li><strong>ग्राम पंचायत का अंकुश:</strong> इसलिए नई कुंई खोदने के लिए पूरे ग्राम समाज (पंचायत) की पूर्व स्वीकृति अनिवार्य होती है। जब तक समाज आश्वस्त न हो, नई कुंई की अनुमति नहीं दी जाती। यह निजी आवश्यकता और प्राकृतिक संतुलन का अनुपम उदाहरण है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">निजी उपयोग और ताले लगाने के अधिकार का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सार्वजनिक भूमि और नमी के बँटवारे को रोकने हेतु सामाजिक नियंत्रण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch18-q5 (विचार एवं अभ्यास) -->\n  <div class=\"q-card\" id=\"c11h-ch18-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch18-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">विचार एवं अभ्यास</span><br>\n        ‘दिनों-दिन बढ़ता पानी का संकट’—इस संदर्भ में अनुपम मिश्र की यह रचना आज के भारत के लिए क्या संदेश देती है?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>‘राजस्थान की रजत बूँदें’ आज के भीषण जल-संकट के दौर में पूरे देश के लिए एक अमूल्य मार्गदर्शक है:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>वर्षा के जल का सम्मान:</strong> जहाँ आज का आधुनिक समाज वर्षा के अमूल्य जल को नालों में बहाकर बर्बाद कर देता है, वहीं राजस्थान के लोगों ने रेत में समाई बूँद-बूँद नमी को अमृत मानकर सहेजना सिखाया।</li>\n        <li><strong>पारंपरिक ज्ञान की पुनर्प्रतिष्ठा:</strong> यह पाठ हमें सिखाता है कि भूजल का अंधाधुंध दोहन करने और ट्यूबवेलों पर निर्भर रहने के बजाय हमें अपनी पारंपरिक जल-संरक्षण पद्धतियों (जैसे बावड़ियाँ, तालाब, कुंइयाँ और रूफ-टॉप रेनवाटर हार्वेस्टिंग) को पुनर्जीवित करना होगा। प्रकृति के साथ सह-अस्तित्व ही जल-संकट का एकमात्र स्थायी समाधान है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">आधुनिक जल बर्बादी के विपरीत बूँद-बूँद जल संचयन का आदर्श</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पारंपरिक ज्ञान, रेनवाटर हार्वेस्टिंग और प्रकृति के साथ तालमेल की प्रासंगिकता</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(17)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← पाठ 17</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(19)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#c2410c; color:white; font-weight:700; cursor:pointer;\">अगला पाठ: आलो-आँधारि →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[19] = "<section class=\"chapter-section\" id=\"c11h-ch19\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#c2410c;\">19</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#c2410c;\">CBSE Class 11 हिंदी कोर &bull; वितान भाग - 1 &bull; पाठ 19</div>\n      <h2>आलो-आँधारि (बेबी हालदार)</h2>\n      <p>NCERT तर्कसंगत (Rationalised) 2026–27 पाठ्यक्रम &bull; संपूर्ण 5 प्रामाणिक प्रश्नोत्तर एवं मार्किंग स्कीम</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #fdf4ff, #fae8ff); border:1px solid #f0abfc; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#86198f; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#c026d3\" stroke-width=\"2\"><path d=\"M4 19.5A2.5 2.5 0 0 1 6.5 17H20\"/><path d=\"M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z\"/></svg>\n      घरेलू नौकरानी से विदुषी लेखिका बनने की प्रेरणादायी गाथा\n    </h3>\n    <svg viewBox=\"0 0 800 150\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"25\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#c026d3\" stroke-width=\"2\"/>\n      <text x=\"137\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#86198f\">आँधारि (अंधकार)</text>\n      <text x=\"137\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">घोर सामाजिक उत्पीड़न</text>\n      <text x=\"137\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• बाल-विवाह, क्रूर पति की मार</text>\n      <text x=\"137\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• 3 बच्चों संग बेघर होकर पलायन</text>\n\n      <path d=\"M 250 75 L 285 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"285\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n      <text x=\"397\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#0369a1\">तातुश का वरदान</text>\n      <text x=\"397\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">पिता-तुल्य गुरु</text>\n      <text x=\"397\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• घर में काम व सम्मानजनक शरण</text>\n      <text x=\"397\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• कॉपी-कलम देकर लिखने की प्रेरणा</text>\n\n      <path d=\"M 510 75 L 545 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"545\" y=\"20\" width=\"230\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#16a34a\" stroke-width=\"2\"/>\n      <text x=\"660\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#15803d\">आलो (प्रकाश की किरण)</text>\n      <text x=\"660\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">साहित्यिक चमत्कार</text>\n      <text x=\"660\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• 'आलो-आँधारि' पुस्तक प्रकाशित</text>\n      <text x=\"660\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• 14+ भाषाओं में अनुवाद, विश्व ख्याति</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT पाठ्यपुस्तक अभ्यास: विचार एवं अभ्यास</div>\n\n  <!-- c11h-ch19-q1 (विचार एवं अभ्यास) -->\n  <div class=\"q-card\" id=\"c11h-ch19-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch19-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">विचार एवं अभ्यास</span><br>\n        बेबी हालदार की घरेलू नौकरानी से प्रख्यात लेखिका बनने की प्रेरणादायक जीवन यात्रा का संक्षेप में वर्णन कीजिए।\n      </div>\n      <div class=\"q-marks\">[4 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>बेबी हालदार का जीवन संघर्ष अदम्य साहस, नारी चेतना और आत्म-सम्मान की अद्भुत विजयगाथा है:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>शुरुआती नारकीय जीवन:</strong> तेरह वर्ष की अल्पायु में अपने से दोगुने उम्र के व्यक्ति से बाल-विवाह, पति द्वारा निरंतर शारीरिक हिंसा व प्रताड़ना। अंततः तीन छोटे बच्चों को लेकर अपने अत्याचारी पति को छोड़ दिया और आजीविका की तलाश में दुर्गापुर से दिल्ली आ गईं।</li>\n        <li><strong>घरेलू सहायिका के रूप में संघर्ष:</strong> दिल्ली के घरों में बर्तन मांजने और झाड़ू-पोंछा करने का काम किया, जहाँ नौकरानियों को तुच्छ समझा जाता था।</li>\n        <li><strong>तातुश का सान्निध्य और कायापलट:</strong> जब वे सेवानिवृत्त समाजशास्त्री प्रोफेसर प्रबोध कुमार (तातुश) के घर काम करने पहुँचीं, तो तातुश ने उन्हें नौकरानी नहीं बल्कि अपनी बेटी जैसा मान दिया। तातुश ने देखा कि काम करते समय बेबी की आँखें किताबों की अलमारी पर टिकी रहती हैं। उन्होंने उसे पढ़ने के लिए पुस्तकें और लिखने के लिए कॉपी-कलम दी।</li>\n        <li><strong>साहित्यिक सृजन:</strong> बेबी ने अपने जीवन के आँसुओं और संघर्षों को बांग्ला में लिखना शुरू किया। उनकी आत्मकथा <strong>‘आलो-आँधारि’</strong> प्रकाशित हुई और 14 से अधिक राष्ट्रीय व अंतरराष्ट्रीय भाषाओं में अनूदित होकर विश्वप्रसिद्ध हुई।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">बाल-विवाह, घरेलू हिंसा और तीन बच्चों संग दिल्ली पलायन</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">घरेलू सहायिका के रूप में सामाजिक अपमान व संघर्ष</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रोफेसर तातुश द्वारा कॉपी-कलम देकर साहित्य सृजन की प्रेरणा</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">\"आलो-आँधारि\" की विश्वस्तरीय सफलता और नारी चेतना की मिसाल</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch19-q2 (विचार एवं अभ्यास) -->\n  <div class=\"q-card\" id=\"c11h-ch19-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch19-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">विचार एवं अभ्यास</span><br>\n        तातुश (प्रोफेसर प्रबोध कुमार) और उनके परिवार ने बेबी हालदार को किस प्रकार सहारा और प्रोत्साहन दिया?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>तातुश (पिता-समान संरक्षक) का बेबी हालदार के जीवन में योगदान किसी देवदूत से कम नहीं था:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>पारिवारिक सम्मान और संरक्षण:</strong> तातुश ने अन्य मकान मालिकों की तरह बेबी से केवल काम नहीं लिया, बल्कि उसे अपनी बेटी की तरह सम्मानजनक छत दी, समय पर पौष्टिक भोजन दिया और उसके बच्चों की पढ़ाई का प्रबंध किया।</li>\n        <li><strong>अध्ययन की प्रेरणा:</strong> उन्होंने बेबी को तस्लीमा नसरीन की आत्मकथा <em>‘अमार मेयेबेला’</em> (मेरा बचपन) और आशापूर्णा देवी की पुस्तकें पढ़ने के लिए दीं।</li>\n        <li><strong>लेखन का संबल:</strong> उन्होंने एक दिन बाज़ार से एक सुंदर नोटबुक और पेन लाकर बेबी को दिया और कहा— <em>“तुम रोज़ इसमें कुछ न कुछ लिखा करो।”</em> जब बेबी झिझकती, तो वे उसका हौसला बढ़ाते और उसकी लिखी कॉपियों को पढ़कर परिमार्जित करते।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">घरेलू सहायिका को पुत्री समान सम्मान और सुरक्षा प्रदान करना</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">विश्वस्तरीय लेखिकाओं की पुस्तकें पढ़ने हेतु उपलब्ध कराना</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कॉपी-कलम देकर निरंतर लेखन हेतु प्रेरित व मार्गदर्शन करना</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch19-q3 (विचार एवं अभ्यास) -->\n  <div class=\"q-card\" id=\"c11h-ch19-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch19-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">विचार एवं अभ्यास</span><br>\n        जेठू (आनंद जी) ने बेबी हालदार की पांडुलिपि देखकर क्या प्रतिक्रिया व्यक्त की?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>तातुश के परम मित्र जेठू (आनंद जी) स्वयं एक प्रबुद्ध साहित्यकार थे। जब उन्होंने बेबी हालदार की हाथ से लिखी पांडुलिपि पढ़ी, तो उनकी प्रतिक्रिया अत्यंत विस्मयकारी और भावुक थी:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>तुलना महान लेखिका से:</strong> उन्होंने बेबी की लेखन शैली और जीवंत ईमानदारी की तुलना प्रसिद्ध रूसी लेखिका <strong>मैक्सिम गोर्की की माँ</strong> अथवा <strong>आशापूर्णा देवी</strong> के स्तर से की।</li>\n        <li><strong>प्रोत्साहन और गौरव:</strong> उन्होंने तातुश से कहा— <em>“प्रबोध, तुम्हारे घर में एक हीरा छिपा था, जिसे तुमने पहचान लिया!”</em> जेठू ने बेबी की पीठ थपथपाई और कहा कि तुम बिना रुके लिखती रहो, तुम्हारा यह सच पूरे समाज की आँखें खोल देगा। उनकी इस प्रशंसा ने बेबी के मन से हीनभावना को पूरी तरह मिटा दिया।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">पांडुलिपि पढ़कर आश्चर्यचकित होना और भाषा की सादगी की प्रशंसा</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">महान साहित्यकारों से तुलना एवं निरंतर लिखने हेतु अगाध संबल</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch19-q4 (विचार एवं अभ्यास) -->\n  <div class=\"q-card\" id=\"c11h-ch19-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch19-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">विचार एवं अभ्यास</span><br>\n        ‘आलो-आँधारि’ (अँधेरे से उजाले की ओर) शीर्षक की सार्थकता स्पष्ट कीजिए।\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>बांग्ला भाषा के शब्द <strong>‘आलो’ का अर्थ है ‘प्रकाश’ (उजाला)</strong> और <strong>‘आँधारि’ का अर्थ है ‘अंधकार’</strong>। यह शीर्षक आत्मकथा की विषयवस्तु के लिए पूर्णतः सार्थक और सटीक है:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>अंधकार (आँधारि):</strong> बेबी हालदार के जीवन का पहला चरण घोर अज्ञान, अशिक्षा, गरीबी, बाल-विवाह, पति की क्रूर लाठियों, भुखमरी और घरेलू नौकरानी के अपमानजनक अंधकार से घिरा हुआ था।</li>\n        <li><strong>प्रकाश (आलो):</strong> तातुश के घर आने के बाद शिक्षा, किताबों, कलम और लेखन के माध्यम से उनके जीवन में नव-चेतना का दिव्य प्रकाश फैला। वे एक बेनाम नौकरानी से उठकर एक सशक्त अंतरराष्ट्रीय ख्यातिप्राप्त लेखिका बन गईं। इस प्रकार यह अंधकार से ज्ञान के प्रकाश की ओर की यात्रा है, अतः ‘आलो-आँधारि’ शीर्षक अत्यंत उपयुक्त है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">\"आलो\" (प्रकाश) और \"आँधारि\" (अंधकार) का शाब्दिक अर्थ</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रताड़ना और गरीबी के अंधकारमय अतीत का निरूपण</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शिक्षा और साहित्य द्वारा सम्मानजनक प्रकाश की प्राप्ति से शीर्षक की सार्थकता</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch19-q5 (विचार एवं अभ्यास) -->\n  <div class=\"q-card\" id=\"c11h-ch19-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch19-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">विचार एवं अभ्यास</span><br>\n        घरेलू कामगार महिलाओं के जीवन की किन विसंगतियों और सामाजिक समस्याओं को इस आत्मकथा में उभारा गया है?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>बेबी हालदार की यह आत्मकथा भारत की असंगठित घरेलू कामगार महिलाओं (मेड/दाई) की दयनीय स्थिति का सजीव दस्तावेज़ है:</p>\n      <ol style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>आर्थिक एवं शारीरिक शोषण:</strong> दिन-रात खटने के बावजूद नाममात्र का वेतन मिलना, छुट्टी माँगने पर नौकरी से निकाल दिए जाने की धमकी और बासी खाना दिया जाना।</li>\n        <li><strong>सामाजिक दृष्टि में हेय समझना:</strong> समाज नौकरानियों को मनुष्य न समझकर केवल एक साधन समझता है। उन पर चोरी का झूठा शक करना और सम्मान न देना आम बात है।</li>\n        <li><strong>घरेलू हिंसा और असहायता:</strong> अधिकांश कामगार महिलाएं अपने घरों में शराबी व हिंसक पतियों की मार सहने को विवश हैं। यह रचना समाज को घरेलू कामगारों के प्रति मानवीय और संवेदनशील बनने का कड़ा संदेश देती है।</li>\n      </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">असंगठित क्षेत्र में अल्प वेतन, अत्यधिक श्रम और छुट्टी का अभाव</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">चोरी के झूठे संदेह और सामाजिक सम्मान से वंचित रखना</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">घरेलू हिंसा और कामगार स्त्रियों की सामाजिक विवशता का चित्रण</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(18)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← पाठ 18</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(20)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#c2410c; color:white; font-weight:700; cursor:pointer;\">अगला पाठ: भारतीय कलाएँ →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[20] = "<section class=\"chapter-section\" id=\"c11h-ch20\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#c2410c;\">20</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#c2410c;\">CBSE Class 11 हिंदी कोर &bull; वितान भाग - 1 &bull; पाठ 20</div>\n      <h2>भारतीय कलाएँ (NCERT संकलन)</h2>\n      <p>NCERT तर्कसंगत (Rationalised) 2026–27 पाठ्यक्रम &bull; संपूर्ण 4 प्रामाणिक प्रश्नोत्तर एवं मार्किंग स्कीम</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #fff7ed, #fed7aa); border:1px solid #fdba74; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#9a3412; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#ea580c\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"m14 12-4-4v8z\"/></svg>\n      भारतीय कलाओं की अजस्र धारा: संगीत, नृत्य, चित्र और वास्तुकला\n    </h3>\n    <svg viewBox=\"0 0 800 150\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"25\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#ea580c\" stroke-width=\"2\"/>\n      <text x=\"137\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#9a3412\">लोक कला आधार</text>\n      <text x=\"137\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">जन-जीवन से उद्भव</text>\n      <text x=\"137\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• सामूहिकता व सहचर्य</text>\n      <text x=\"137\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• उत्सव, खेती और प्रकृति से जुड़ाव</text>\n\n      <path d=\"M 250 75 L 285 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"285\" y=\"20\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#c2410c\" stroke-width=\"2\"/>\n      <text x=\"397\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#9a3412\">शास्त्रीय परिष्कार</text>\n      <text x=\"397\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">नाट्यशास्त्र परंपरा</text>\n      <text x=\"397\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• भरतनाट्यम, कथक, मोहिनीअट्टम</text>\n      <text x=\"397\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• राग, ताल और रस का विधान</text>\n\n      <path d=\"M 510 75 L 545 75\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"545\" y=\"20\" width=\"230\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <text x=\"660\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#065f46\">जीवन का उत्कर्ष</text>\n      <text x=\"660\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">कला ही मानवता है</text>\n      <text x=\"660\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• \"साहित्यसंगीतकलाविहीनः साक्षात्पशुः\"</text>\n      <text x=\"660\" y=\"113\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• आत्मिक आनंद और राष्ट्रीय एकता</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT पाठ्यपुस्तक अभ्यास: विचार एवं अभ्यास</div>\n\n  <!-- c11h-ch20-q1 (विचार एवं अभ्यास) -->\n  <div class=\"q-card\" id=\"c11h-ch20-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch20-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">विचार एवं अभ्यास</span><br>\n        कला और भाषा के अंतर्संबंध पर अपने विचार व्यक्त कीजिए।\n      </div>\n      <div class=\"q-marks\">[4 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>कला और भाषा मानवीय चेतना और अभिव्यक्ति के दो परस्पर पूरक एवं अभिन्न माध्यम हैं:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>अभिव्यक्ति की आदिम यात्रा:</strong> इतिहास गवाह है कि मनुष्य ने अक्षरों और व्याकरण वाली भाषा सीखने से हज़ारों वर्ष पूर्व <strong>चित्रों और रेखाओं</strong> के माध्यम से अपने भाव व्यक्त करना शुरू कर दिया था। भीमबेटका की गुफाओं में मिले आदिमानव के शैलचित्र इसका प्रत्यक्ष प्रमाण हैं। अतः कला भाषा की जननी है।</li>\n        <li><strong>शब्दों से परे की भाषा:</strong> भाषा की अपनी सीमाएं होती हैं—कई गहरे भाव (उदासी, प्रेम, भक्ति, विस्मय) शब्दों में नहीं बांधे जा सकते। वहाँ संगीत के सुर, रंगों की तूलिका और नृत्य की भाव-भंगिमाएँ मुखर हो उठती हैं। कला वह सार्वभौमिक भाषा है जिसके लिए किसी अनुवाद की आवश्यकता नहीं होती।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">भीमबेटका के शैलचित्रों द्वारा कला को भाषा की आदिम जननी सिद्ध करना</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शब्दों की सीमाओं से परे कला को सार्वभौमिक मूक भाषा के रूप में निरूपित करना</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch20-q2 (विचार एवं अभ्यास) -->\n  <div class=\"q-card\" id=\"c11h-ch20-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch20-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">विचार एवं अभ्यास</span><br>\n        भारतीय लोक कला और शास्त्रीय कला के बीच क्या संबंध है? क्या शास्त्रीय कलाओं का आधार लोक कलाएँ ही हैं?\n      </div>\n      <div class=\"q-marks\">[4 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>हाँ, भारतीय <strong>शास्त्रीय कलाओं का मूल आधार जनजातीय और लोक कलाएँ ही हैं</strong>:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>उद्भव और परिष्कार:</strong> कोई भी शास्त्रीय कला अचानक शून्य से उत्पन्न नहीं हुई। लोक समाज जब अपने उत्सवों, खेती, ऋतु-परिवर्तन और पूजा में उन्मुक्त होकर गाता और नाचता था, तो वही लोक धुनें और लोक नृत्य कालांतर में आचार्यों द्वारा परिष्कृत, व्याकरणबद्ध और नियमबद्ध होकर 'शास्त्रीय संगीत' और 'शास्त्रीय नृत्य' (जैसे भरतनाट्यम, कथक, ओडिसी आदि) बने।</li>\n        <li><strong>पारस्परिक आदान-प्रदान:</strong> लोक कला यदि सहज प्रवाह और जीवन की ऊर्जा देती है, तो शास्त्रीय कला उसे अनुशासन, मर्यादा और सौंदर्यशास्त्र प्रदान करती है। दोनों नदियाँ एक ही सांस्कृतिक सागर में विलीन होती हैं।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">शास्त्रीय कलाओं के मूल स्रोत के रूप में लोक कलाओं की पुष्टि</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">लोक की सहजता और शास्त्रीयता के नियमों के आपसी आदान-प्रदान का विश्लेषण</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch20-q3 (विचार एवं अभ्यास) -->\n  <div class=\"q-card\" id=\"c11h-ch20-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch20-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">विचार एवं अभ्यास</span><br>\n        सामूहिकता और सहचर्य की भावना भारतीय लोक नृत्यों में किस प्रकार प्रकट होती है?\n      </div>\n      <div class=\"q-marks\">[3 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>भारतीय लोक नृत्य व्यक्तिवादी प्रदर्शन नहीं, बल्कि <strong>सामूहिकता, समरसता और सहचर्य (साथ जीने) की भावना</strong> का सर्वोत्तम उत्सव हैं:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>हाथों में हाथ और एक ताल:</strong> बिहू, डांडिया, गरबा, भांगड़ा या संथाली लोक नृत्यों में नर्तक एक विशाल गोल घेरे (वृत्त) में एक-दूसरे की कमर या हाथ थामकर एक ही ताल पर एक साथ पैर उठाते और थिरकते हैं। इसमें कोई छोटा या बड़ा नहीं होता।</li>\n        <li><strong>जाति और वर्ग भेद का विलोप:</strong> नृत्य के उस पावन क्षण में अमीर-गरीब, ऊँच-नीच के सारे कृत्रिम भेद मिट जाते हैं। यह सामूहिकता हमारे समाज के 'वसुधैव कुटुंबकम्' और सामाजिक सौहार्द का जीवंत प्रतीक है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">वृत्ताकार घेरे में एक साथ कदमताल मिलाने का उदाहरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सामूहिकता द्वारा जातिगत और वर्गगत भेदभाव के विलोप का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11h-ch20-q4 (विचार एवं अभ्यास) -->\n  <div class=\"q-card\" id=\"c11h-ch20-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11h-ch20-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#fff7ed; color:#c2410c; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">विचार एवं अभ्यास</span><br>\n        ‘साहित्यसंगीतकलाविहीनः साक्षात्पशुः पुच्छविषाणहीनः’—महाकवि भर्तृहरि के इस प्रसिद्ध श्लोक की आधुनिक जीवन में प्रासंगिकता स्पष्ट कीजिए।\n      </div>\n      <div class=\"q-marks\">[4 अंक]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE मानक हिंदी कोर उत्तर (Step-by-Step)</div>\n        <div class=\"answer-text\">\n          <p>संस्कृत के अमर नीति-कवि भर्तृहरि के इस श्लोक का अर्थ है— <em>“जो मनुष्य साहित्य, संगीत और कला के रसास्वादन से रहित है, वह बिना सींग और पूँछ के साक्षात् पशु के समान है।”</em></p>\n      <p><strong>आधुनिक संदर्भ में प्रासंगिकता:</strong></p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>भौतिक अंधी दौड़ से मुक्ति:</strong> आज का 21वीं सदी का मानव केवल पैसे कमाने, करियर और मशीनी दिनचर्या की अंधी दौड़ में फँसकर अपनी मानवीय संवेदनाएँ खोता जा रहा है। वह एक जैविक रोबोट बनता जा रहा है।</li>\n        <li><strong>संवेदना का जागरण:</strong> साहित्य और कलाएँ मनुष्य के भीतर करुणा, प्रेम, सौंदर्यबोध और सामाजिक सहानुभूति जगाती हैं। कला विहीन मनुष्य केवल पेट भरने और बच्चे जनने तक सीमित रहता है, जो पशु भी करते हैं। मनुष्य को वास्तव में 'मनुष्य' बनाए रखने के लिए साहित्य और कला की उपस्थिति आज पहले से कहीं अधिक अनिवार्य है।</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना एवं मूल्यांकन निर्देश (सत्र 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">श्लोक का शुद्ध भावार्थ (कला विहीन मनुष्य बिना सींग-पूँछ का पशु)</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आधुनिक मशीनी जीवन, तनाव और संवेदनहीनता के परिप्रेक्ष्य में प्रासंगिकता</span><span class=\"marking-marks\">2.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(19)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← पाठ 19</button>\n    <a href=\"../ncert-solutions-class-11.html\" class=\"ch-nav-btn next\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#c2410c; color:white; font-weight:700; text-decoration:none;\">Class 11 All Subjects Hub →</a>\n  </div>\n</section>";
